window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["I2"]={"deck":"I2","slides":[{"p":1,"title":"2강 표지: 데이터 흐름과 IoT 파이프라인","terms":["Internet of Things","IoT Data Pipeline","1-Loop","AIoT","AI@Home","Non-identifying Sensing","Privacy-by-Design"],"pass1":[{"kind":"title","big":"데이터가 흐르는 집","sub":"2강 데이터 흐름과 IoT 파이프라인"},{"kind":"say","lines":["1강에서는 똑똑한 집이 어떤 층으로 지어지는지 봤어요.","2강은 그 집 안에서 **데이터**가 어디로, 어떻게 흘러가는지 따라가 봐요.","데이터는 센서가 느낀 것을 숫자로 적어 둔 기록이에요.","IoT는 물건들이 인터넷으로 이어진 **사물인터넷(Internet of Things)**을 줄인 말이에요."]},{"kind":"say","lines":["이번 강의 내내 붙들고 갈 한 문장이 있어요.","센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요.","이 흐름이 끊기지 않고 이어지는 길을 **IoT 데이터 파이프라인(IoT Data Pipeline)**이라고 불러요."]}],"pass2":[{"kind":"points","head":"2강은 세 묶음이에요","items":["첫 묶음: 데이터가 흐르는 길인 **IoT 데이터 파이프라인(IoT Data Pipeline)**과, 집이 한 바퀴 돌며 반응하는 **1-Loop(원 루프)**예요.","둘째 묶음: 집에서 나오는 데이터를 세 종류로 나눠요. 인공지능이 붙은 사물인터넷, 즉 **AIoT(인공지능 사물인터넷)** 공간의 데이터예요.","셋째 묶음: 데이터를 화면으로 보여 주는 법과, 얼굴을 찍지 않고 사람을 알아채는 **비식별 센싱(Non-identifying Sensing)**이에요."]},{"kind":"points","head":"표지 아래 상자의 뜻","items":["데이터는 **지능형 홈(AI@Home)**을 똑똑하게 만드는 재료예요.","수집된 데이터가 판단과 실행으로 이어지는 길을 배워요.","그리고 그 과정에서 사는 사람의 사생활을 지키는 원칙도 함께 배워요."]},{"kind":"check","q":"2강에서 '데이터가 센서에서 출발해 판단과 실행까지 흘러가는 길'을 부르는 이름은?","choices":["IoT 데이터 파이프라인","세대단말기","Wi-Fi","대시보드"],"a":0,"why":"**IoT 데이터 파이프라인(IoT Data Pipeline)**이에요. 수도관 속 물처럼 데이터가 정해진 길로 흘러가요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"세 소강 이름을 정확히","items":["[2.1강] 공간의 IoT 파이프라인과 **1-Loop(원 루프)** 순환 메커니즘","[2.2강] **AIoT(인공지능 사물인터넷)** 공간 데이터의 3대 유형과 공간적 의미","[2.3강] 공간 데이터 가시화와 비식별 센싱"]}],"pass4":[],"pass5":[],"walk":{"head":null,"parts":[{"b":[0.086,0.207,0.271,0.237],"c":[0.0724,0.191,0.2981,0.269],"r":1.5672,"img":"img/I2/walk/p001_30_01.jpg","say":"강의 제목은 '데이터 흐름과 IoT 파이프라인'이에요. 담당은 김철재 교수님이에요."},{"b":[0.086,0.473,0.407,0.04],"c":[0.0656,0.438,0.4477,0.11],"r":5.7559,"img":"img/I2/walk/p001_30_02.jpg","say":"2.1강: 공간의 IoT 파이프라인과 1-Loop 순환 메커니즘. 데이터의 길과 한 바퀴 반응이에요."},{"b":[0.086,0.523,0.379,0.04],"c":[0.067,0.488,0.4169,0.11],"r":5.3599,"img":"img/I2/walk/p001_30_03.jpg","say":"2.2강: AIoT 공간 데이터의 3대 유형과 공간적 의미. 상태, 이벤트, 시계열 세 가지예요."},{"b":[0.086,0.574,0.311,0.04],"c":[0.0704,0.539,0.3421,0.11],"r":4.3983,"img":"img/I2/walk/p001_30_04.jpg","say":"2.3강: 공간 데이터 가시화와 비식별 센싱. 대시보드 화면과 사생활 보호 이야기예요."},{"b":[0.086,0.682,0.829,0.136],"c":[0.0445,0.6579,0.9119,0.1842],"r":7.0013,"img":"img/I2/walk/p001_30_05.jpg","say":"교과목 핵심 연결: 데이터가 AI@Home의 '지능'을 만드는 원천이고, 파이프라인과 프라이버시 보호 원칙을 배워요."}]}},{"p":2,"title":"1강 역사 회고: 공급자 주도권의 한계와 주거 공간의 위기","terms":["4 Core Values of AI@Home Design","Convenience","Comfort","Safety","Saving","Protocol","Smart Home","IoT Data Pipeline"],"pass1":[{"kind":"say","lines":["집은 원래 사람을 위해 있어요.","편하게, 기분 좋게, 다치지 않게, 돈과 전기를 아끼게 해 줘야 하죠.","집이 꼭 지켜야 할 이 네 가지 약속을 **지능형홈 설계 4대 가치(4 Core Values of AI@Home Design)**라고 불러요.","AI@Home은 시키지 않아도 알아서 챙겨 주는 똑똑한 집이라는 뜻이에요."]},{"kind":"analogy","head":"회사마다 다른 말을 쓰던 집","scene":"한 반 친구들이 저마다 다른 나라 말만 쓴다고 생각해 봐요. 모둠 숙제를 하려 해도 말이 안 통해요. 예전 집 안 기기들이 이랬어요. 회사마다 자기 기기끼리만 통하게 만들었거든요.","map":[["저마다 다른 나라 말","회사마다 다른 통신 약속, **프로토콜(Protocol)**"],["말이 안 통하는 모둠","섞어 쓰기 어려운 우리 집 기기들"],["모둠 숙제가 안 됨","사람이 원하는 **스마트홈(Smart Home)**이 아직 비어 있음"]]},{"kind":"say","lines":["그래서 공간을 만드는 사람도 이제 가구 배치만 알아서는 부족해요.","데이터가 흐르는 길까지 스스로 설계하는 '공간의 엔지니어'가 되자는 게 이 쪽의 결론이에요."]}],"pass2":[{"kind":"compare","head":"네 가지 가치, 한국어와 영어 짝","cols":["가치","뜻"],"rows":[["**편의(Convenience)**","스위치를 찾지 않아도 되는 편함"],["**쾌적(Comfort)**","공기와 빛, 온도가 늘 기분 좋은 상태"],["**안전(Safety)**","가스, 물 새는 것 같은 위험을 먼저 막음"],["**절감(Saving)**","안 쓰는 전기와 가스를 알아서 줄임"]]},{"kind":"points","head":"나머지 세 칸은 '문제 → 결론' 흐름이에요","items":["공급자 종속: 회사들이 자기 기기와 자기 **프로토콜(Protocol)**만 챙겼어요. 그래서 기기끼리 섞어 쓰기 어려웠어요.","건축공간 계열의 위기: 디자인과 시공만 붙들고 있으면, 일감이 AI나 로봇 같은 기술 산업으로 넘어가요.","정체성 전환: **IoT 데이터 파이프라인(IoT Data Pipeline)**과 **스마트홈(Smart Home)** 전체 구조까지 설계하는 '공간의 엔지니어'가 되어야 해요."]},{"kind":"check","q":"**지능형홈 설계 4대 가치(4 Core Values of AI@Home Design)**에 들어가지 않는 것은?","choices":["편의","쾌적","속도","절감"],"a":2,"why":"네 가지는 **편의(Convenience)**, **쾌적(Comfort)**, **안전(Safety)**, **절감(Saving)**이에요. 속도는 없어요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"시험에 그대로 나올 만한 문장","items":["사용자가 원하는 방식의 **스마트홈(Smart Home)**은 아직 사각지대로 남아 있음.","그 볼륨은 점차 기술, 타산업으로 빼앗길 수밖에 없음(AI, 로봇 등 첨단기술이 주도).","스마트 공간 기획자는 데이터 파이프라인과 IoT 스마트홈 통합 아키텍처까지 스스로 설계, 통제하는 '공간의 엔지니어'."]},{"kind":"bg","src":"용어해설집 14번","lines":["**지능형홈 설계 4대 가치(4 Core Values of AI@Home Design)**는 지능형홈 설계의 핵심 목표예요.","해설집은 영어까지 붙여요: Convenience, Safety, Comfort, Saving."]}],"pass4":[{"kind":"check","q":"1강 회고 슬라이드의 '공급자 종속' 설명으로 옳은 것은?","choices":["공급자들이 경쟁사 기기 호환을 적극적으로 챙겼다","공급자들이 자기 영역 기기와 표준 최적화에만 집중했다","공급자들이 하나의 공통 표준을 일찍 만들었다","사용자가 원하는 스마트홈이 이미 완성되었다"],"a":1,"why":"건설, 통신, 가전 공급자는 자기 영역 중심으로만 최적화했고 경쟁사 기기 호환과 통합은 고려하지 않았어요."},{"kind":"english","head":"답안 문장으로 외우기","en":"지능형홈 설계 4대 가치는 편의(Convenience), 쾌적(Comfort), 안전(Safety), 절감(Saving)이다.","ko":"한국어와 영어를 짝으로 외워야 보기에서 영어만 나와도 골라낼 수 있어요.","tip":"앞 글자만 따서 '편, 쾌, 안, 절'로 소리 내 읽어요."}],"pass5":[],"walk":{"head":{"b":[0.0819,0.1256,0.57,0.0985],"c":[0.0534,0.1096,0.627,0.1305],"r":6.7948,"img":"img/I2/walk/p002_h.jpg"},"parts":[{"b":[0.089,0.234,0.825,0.134],"c":[0.0477,0.2093,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p002_30_01.jpg","say":"① 인간 중심 설계의 4대 가치: 주거 공간은 편의, 쾌적, 안전, 절감을 채워야 해요. 기존 건축은 이걸 시스템으로 구현하기 어려워서 스마트홈이 필요해요."},{"b":[0.089,0.381,0.825,0.168],"c":[0.0477,0.365,0.9075,0.2],"r":6.4171,"img":"img/I2/walk/p002_30_02.jpg","say":"② 공급자 종속의 역사와 구조적 공백: 건설, 통신, 가전 공급자가 자기 영역 기기와 표준만 최적화했어요. 경쟁사 기기 호환은 고려하지 않았어요."},{"b":[0.089,0.559,0.825,0.167],"c":[0.0477,0.543,0.9075,0.199],"r":6.4493,"img":"img/I2/walk/p002_30_03.jpg","say":"③ 건축공간 계열의 위기와 기회: 기획자와 실무자가 디자인, 시공 중심 관행에 머물러 있어요. 일감은 기술, 타산업으로 빠져나가요."},{"b":[0.089,0.736,0.825,0.16],"c":[0.0477,0.72,0.9075,0.192],"r":6.6845,"img":"img/I2/walk/p002_30_04.jpg","say":"④ 공간 엔지니어로의 정체성 전환: AI가 산업 경계를 허물어요. 데이터 파이프라인과 통합 아키텍처를 스스로 설계, 통제해야 해요."}]}},{"p":3,"title":"2강 화두: 스마트홈 진화의 현실 주소와 AI@Home 지향점","terms":["RS-485","Wall Pad","Wi-Fi","Zigbee","Matter","Thread","IPv6","Fragmentation","Protocol","Smart Home","AI@Home","Non-identifying Sensing"],"pass1":[{"kind":"say","lines":["우리 집 조종법은 세 번 크게 바뀌었어요.","처음엔 벽에 붙은 조종 화면으로 눌렀고, 다음엔 휴대폰 앱과 말로 시켰어요.","앞으로 가려는 집은 시키지 않아도 집이 알아서 챙겨요."]},{"kind":"compare","head":"세 번의 변화, 쉬운 말로","cols":["","첫째 집","둘째 집","앞으로의 집"],"rows":[["무엇으로 잇나","벽 속 전선","회사마다 다른 무선","모두 통하는 공통 약속"],["어떻게 조종하나","벽의 조종 화면","휴대폰 앱, 말","집이 알아서"],["누구를 위한 집","아파트 단지 전체","기기마다 따로","사는 사람 맞춤"]]},{"kind":"analogy","head":"말이 통하게 된 집","scene":"둘째 집에서는 기기마다 쓰는 말이 달라서 서로 대화가 잘 안 됐어요. 앞으로의 집은 모든 기기가 같은 말을 쓰기로 약속해요. 말이 통하니 따로따로 놀던 기기들이 한 팀처럼 움직일 수 있어요.","map":[["기기마다 다른 말","회사마다 다른 **프로토콜(Protocol)**, 그래서 생긴 **파편화(Fragmentation)**"],["같은 말을 쓰기로 한 약속","**Matter(매터)** 같은 공통 표준"],["한 팀처럼 움직이는 기기","사는 사람에게 맞춰 주는 **지능형 홈(AI@Home)**"]]}],"pass2":[{"kind":"compare","head":"세대 표의 용어 뜻","cols":["용어","뜻"],"rows":[["**RS-485(유선 직렬 통신)**","월패드와 설비를 잇는 옛날식 유선 줄이에요."],["**세대단말기(Wall Pad)**","현관이나 거실 벽에 붙은 집 조종 화면, 흔히 월패드라고 불러요."],["**Wi-Fi(와이파이)**, **Zigbee(지그비)**","집 안 무선이에요. 둘째 집에서는 회사마다 따로 써서 흩어졌어요."],["**Matter(매터)**, **Thread(스레드)**, **IPv6(새 인터넷 주소 체계)**","기기끼리 말이 통하게 하는 공통 약속, 그 약속이 다니는 저전력 무선 그물망, 모든 기기에 주는 새 인터넷 주소예요."]]},{"kind":"points","head":"표 아래 두 상자의 뜻","items":["기술은 이미 둘째 세대를 넘어 빨리 가는데, 실제 현장은 그 중간쯤에 머물러 있어요.","그래서 지금은 흩어진 무선 기기들 위에 AI를 안전하게 붙이려고 고민하는 갈림길이에요.","**지능형 홈(AI@Home)**은 우리가 가야 할 목표예요. 그러려면 데이터가 흐르는 길과 구조부터 알아야 해요."]},{"kind":"check","q":"둘째 세대 스마트홈의 '공간 가치'를 가장 잘 나타낸 말은?","choices":["공동생활주거 중심","제조사, 기기별로 파편화된 개별 경험","거주자 UX 맞춤 공간 케어","비식별 센서 기반 자율 환경 조율"],"a":1,"why":"회사마다 앱과 무선이 달라서 경험이 조각조각 났어요. 이게 **파편화(Fragmentation)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"look","walked":1},{"kind":"compare","head":"세대 비교 표 전체","cols":["구분","1세대 유선 홈네트워크","2세대 개별 무선 IoT","AI@Home"],"rows":[["통신 매체","RS-485 유선 직렬","Wi-Fi, Zigbee 개별 파편화 무선","Matter, Thread, IPv6 통합 통신"],["제어 방식","월패드","스마트폰 앱 및 음성 스피커 명령","비식별 센서 기반 자율 환경 조율"],["공간 가치","공동생활주거 중심","제조사, 기기별 파편화된 개별 경험","거주자 UX 맞춤 공간 케어"]]},{"kind":"points","head":"숫자 하나 챙기기","items":["현장은 **1.5세대**에 머물러 있어요. 1세대와 2세대의 중간이라는 뜻이에요.","통신은 '선 → 따로 무선 → 하나로 통합' 순서로 바뀌었어요.","**지능형 홈(AI@Home)** 칸의 제어 방식에 나온 **비식별 센싱(Non-identifying Sensing)**은 2.3강 뒤쪽에서 자세히 나와요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 18번","q":"다음 중 지능형 홈 구현에 사용되는 무선 통신 기술에 해당하지 않는 것은? (Thread, Z-Wave, RS-485, Zigbee)","qko":"보기 넷 중에서 무선이 아닌 것 하나를 고르는 문제예요.","solve":["Thread, Z-Wave, Zigbee는 모두 저전력 무선 메시 통신이에요.","RS-485는 두 가닥 꼬임선을 쓰는 유선 직렬 통신이에요.","이 쪽 표에서도 RS-485는 '1세대 유선 직렬'로 나와요."],"answer":"RS-485"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 23번","q":"Matter 환경에서 저전력 IoT 기기 연결에 쓰이는 Thread 프로토콜의 특징으로 가장 적절하지 않은 것은?","qko":"Thread 설명 넷 중 틀린 것을 고르는 문제예요.","solve":["Thread는 IPv6를 기반으로 동작해요. 맞는 말이에요.","저전력 메시 네트워크를 지원해요. 맞는 말이에요.","Zigbee처럼 IEEE 802.15.4 표준을 바탕으로 해요. 맞는 말이에요.","'VPN 기반의 암호화 무선 통신 기술'은 Thread를 설명하는 말이 아니에요."],"answer":"VPN 기반의 암호화 무선 통신 기술이다"},{"kind":"check","q":"세대 비교 표에서 AI@Home의 통신 매체로 나오지 않은 것은?","choices":["Matter","Thread","IPv6","RS-485"],"a":3,"why":"**RS-485(유선 직렬 통신)**은 1세대 유선 홈네트워크 칸에 있어요. AI@Home 칸은 **Matter(매터)**, **Thread(스레드)**, **IPv6(새 인터넷 주소 체계)**예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["월패드의 정식 용어는 **세대단말기(Wall Pad)**예요. 보기에서 '세대단말기'로 나와도 같은 것이에요.","현장은 '2세대'가 아니라 '1.5세대'에 머물러 있다고 했어요. 숫자를 바꿔 내는 보기에 주의해요."]}],"pass5":[],"walk":{"head":{"b":[0.0819,0.125,0.5969,0.0983],"c":[0.0521,0.109,0.6566,0.1303],"r":7.1265,"img":"img/I2/walk/p003_h.jpg"},"parts":[{"b":[0.089,0.23,0.825,0.044],"c":[0.0477,0.1603,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p003_30_01.jpg","say":"열 이름: 1세대(유선 홈네트워크) 현장, 2세대(개별 무선 IoT) 기술, AI@Home 컨셉. 빨간 점 표시는 지금 어디쯤인지를 가리켜요."},{"b":[0.089,0.277,0.825,0.077],"c":[0.0477,0.2238,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p003_30_02.jpg","say":"통신 매체: RS-485 유선 직렬 → Wi-Fi, Zigbee 개별 파편화 무선 → Matter, Thread, IPv6 통합 통신."},{"b":[0.089,0.356,0.825,0.079],"c":[0.0477,0.3038,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p003_30_03.jpg","say":"제어 방식: 월패드 → 스마트폰 앱 및 음성 스피커 명령 → 비식별 센서 기반 자율 환경 조율."},{"b":[0.089,0.436,0.825,0.059],"c":[0.0477,0.3738,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p003_30_04.jpg","say":"공간 가치: 공동생활주거 중심 → 제조사, 기기별 파편화된 개별 경험 → 거주자 UX 맞춤 공간 케어."},{"b":[0.089,0.5,0.825,0.136],"c":[0.0477,0.4763,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p003_31_01.jpg","say":"현장의 기술 격차: 기술은 이미 2세대를 넘어 빠르게 진화 중인데, 산업 현장의 체감 수용력은 여전히 1.5세대예요. 극심한 과도기적 격차예요."},{"b":[0.089,0.647,0.825,0.174],"c":[0.0477,0.631,0.9075,0.206],"r":6.2302,"img":"img/I2/walk/p003_31_02.jpg","say":"현재 위치 진단과 당위성: AI@Home은 지향점이에요. 시장은 파편화를 딛고 AI를 안전하게 접목할지 고민하는 전환점이라, 공학적 기본기(데이터 파이프라인과 아키텍처)를 다져야 해요."}]}},{"p":4,"title":"2강 학습 목표","terms":["1-Loop","IoT Data Pipeline","Sensor","Actuator","State Data","Event Data","Time-series Data","Privacy-by-Design","Dashboard"],"pass1":[{"kind":"goal","items":["집이 느끼고 움직이는 한 바퀴를 따라가 보기","집에서 나오는 데이터를 세 종류로 나눠 보기","화면으로 보여 주면서도 사는 사람의 사생활을 지키는 법 알기"]},{"kind":"say","lines":["오늘 목표는 이 세 가지예요.","센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요.","이 문장이 첫째 목표이고, 나머지 두 목표도 이 흐름 위에 올라가요."]}],"pass2":[{"kind":"points","head":"목표 세 칸의 용어 풀이","items":["**1-Loop(원 루프)**: 감지 → 전달 → 판단 → 실행으로 한 바퀴 도는 집의 반응이에요. **센서(Sensor)**에서 출발해 **액추에이터(Actuator)**까지 가요.","3대 데이터: 계속 알려 주는 **상태 데이터(State Data)**, 한 번 딱 알리는 **이벤트 데이터(Event Data)**, 날마다 쌓이는 **시계열 데이터(Time-series Data)**예요.","**Privacy-by-Design(프라이버시 바이 디자인)**: 처음 설계할 때부터 사생활 보호를 기본으로 넣는다는 뜻이에요. **대시보드(Dashboard)** 이야기와 함께 나와요."]},{"kind":"check","q":"학습 목표 ①에서 '센서에서 액추에이터까지 이어지는 자율 반응 회로'를 부르는 이름은?","choices":["1-Loop","Privacy-by-Design","데이터 레이크","월패드"],"a":0,"why":"**1-Loop(원 루프)**예요. 센서가 느끼고 액추에이터가 움직이면 한 바퀴가 닫혀요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"'매핑'이라는 말","items":["매핑은 '짝지어 연결한다'는 뜻이에요.","목표 ②는 세 가지 데이터를 **자동화 로직(Trigger-Action)**, 즉 '이러면 저렇게 해'라는 약속에 짝지을 줄 알자는 뜻이에요."]}],"pass4":[],"pass5":[{"kind":"points","head":"실기 연결: 슬라이드의 시뮬레이터 표기","items":["슬라이드는 이번 주 이론이 학습 시뮬레이터 **[0-0 통합 계통도]**의 데이터 흐름 조망 기능과 이어진다고 적었어요.","실기 가이드북 2권 1-1 #5 '구축 및 자동화'는 요건 분석에 따라 스마트기기 수량과 네트워크 방식을 정해 '전체 구성도'를 만들고 구축한다고 설명해요.","즉 구성도를 볼 때도 **센서(Sensor)** → 허브 → 공유기(인터넷) 순으로 데이터가 어디를 지나가는지 읽는 눈이 필요해요."]},{"kind":"warn","head":"주의","items":["[0-0 통합 계통도] 과업의 화면 조작 순서는 실기 가이드북 2권에 따로 적혀 있지 않아요. 순서를 지어내 외우지 말고, 흐름을 읽는 연습으로만 챙겨요."]}],"walk":{"head":{"b":[0.0819,0.1256,0.3704,0.1004],"c":[0.0634,0.1096,0.4074,0.1324],"r":4.3516,"img":"img/I2/walk/p004_h.jpg"},"parts":[{"b":[0.089,0.228,0.268,0.212],"c":[0.0756,0.212,0.2948,0.244],"r":1.7087,"img":"img/I2/walk/p004_30_01.jpg","say":"학습 목표 ① 1-Loop & 파이프라인: 센서에서 액추에이터까지 이어지는 자율 반응 회로와 인프라 경로(파이프라인) 분석 역량."},{"b":[0.366,0.228,0.269,0.212],"c":[0.3525,0.212,0.2959,0.244],"r":1.715,"img":"img/I2/walk/p004_30_02.jpg","say":"학습 목표 ② 3대 데이터 유형: 스마트홈 데이터 정의부터 상태, 이벤트, 시계열 데이터를 자동화 로직으로 매핑하는 역량."},{"b":[0.644,0.228,0.27,0.212],"c":[0.6305,0.212,0.297,0.244],"r":1.7214,"img":"img/I2/walk/p004_30_03.jpg","say":"학습 목표 ③ Privacy-by-Design: 대시보드의 실무 필수 기능과 거주자 프라이버시 보호를 위한 비식별 설계 원칙 습득."},{"b":[0.089,0.449,0.825,0.092],"c":[0.0477,0.4033,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p004_30_04.jpg","say":"시뮬레이터 연계: 국가공인 지능형홈관리사 학습 시뮬레이터 [0-0 통합 계통도]의 데이터 흐름 조망 기능과 이어져요."}]}},{"p":5,"title":"2.1 공간의 IoT 파이프라인과 1-Loop 순환 메커니즘 (목차)","terms":["IoT Data Pipeline","1-Loop","Intelligent Space","Edge Computing","Cloud Computing","Sense","Transmit","Analyze","Act"],"pass1":[{"kind":"say","lines":["여기부터 첫 묶음이에요.","데이터가 흐르는 길 전체를 먼저 보고, 그중 사람이 실제로 느끼는 한 바퀴만 뽑아내요.","센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요."]}],"pass2":[{"kind":"points","head":"다섯 소절을 한 줄씩","items":["2.1.1 **지능형 공간(Intelligent Space)**: 센서가 읽고 스스로 반응하는 집이 무엇인지.","2.1.2 산업계 표준 **IoT 데이터 파이프라인(IoT Data Pipeline)** 일곱 단계.","2.1.3 그 일곱 단계를 **1-Loop(원 루프)** 네 단계에 짝짓기.","2.1.4 집 안에서 바로 처리하는 **엣지 컴퓨팅(Edge Computing)**과 먼 서버에서 처리하는 **클라우드 컴퓨팅(Cloud Computing)** 비교.","2.1.5 **감지(Sense)** → **전달(Transmit)** → **판단(Analyze)** → **실행(Act)** 순환."]},{"kind":"check","q":"2.1.4에서 비교하는 두 가지는?","choices":["Edge(로컬 허브) 처리와 Cloud(클라우드) 서버 처리","Wi-Fi와 Zigbee","상태 데이터와 이벤트 데이터","월패드와 스마트폰"],"a":0,"why":"집 안 허브에서 바로 하는 **엣지 컴퓨팅(Edge Computing)**과 먼 곳 서버의 **클라우드 컴퓨팅(Cloud Computing)**을 비교해요."}],"pass3":[{"kind":"look","walked":1}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.19,0.3346,0.5319,0.071],"c":[0.1634,0.3186,0.5851,0.103],"r":8.0337,"img":"img/I2/walk/p005_h.jpg"},"parts":[{"b":[0.121,0.463,0.45,0.037],"c":[0.0985,0.4265,0.495,0.11],"r":6.364,"img":"img/I2/walk/p005_30_01.jpg","say":"2.1.1 지능형 공간의 본질과 패러다임(데이터 해석과 자율 반응)."},{"b":[0.121,0.508,0.421,0.037],"c":[0.1,0.4715,0.4631,0.11],"r":5.9539,"img":"img/I2/walk/p005_30_02.jpg","say":"2.1.2 산업계 표준 IoT 데이터 파이프라인 참조 모델(7단계)."},{"b":[0.121,0.554,0.357,0.037],"c":[0.1031,0.5175,0.3927,0.11],"r":5.0488,"img":"img/I2/walk/p005_30_03.jpg","say":"2.1.3 IoT 데이터 파이프라인과 1-Loop 동작 매핑."},{"b":[0.121,0.599,0.421,0.037],"c":[0.1,0.5625,0.4631,0.11],"r":5.9539,"img":"img/I2/walk/p005_30_04.jpg","say":"2.1.4 Edge(로컬 허브) 처리 vs Cloud(클라우드) 서버 처리."},{"b":[0.121,0.644,0.404,0.037],"c":[0.1008,0.6075,0.4444,0.11],"r":5.7135,"img":"img/I2/walk/p005_30_05.jpg","say":"2.1.5 Loop 데이터 순환 메커니즘(감지-전달-판단-실행)."}]}},{"p":6,"title":"2.1.1 지능형 공간의 본질과 패러다임","terms":["Intelligent Space","Sensor","AI@Home","Smart Home","Rule-based Automation","Convenience","Safety"],"pass1":[{"kind":"analogy","head":"스스로 겉옷을 걸치는 사람처럼","scene":"방이 추우면 피부가 먼저 느껴요. 머리가 '춥네' 하고 생각하면 손이 알아서 겉옷을 걸치죠. 시키지 않아도 느끼고 생각하고 움직여요. 이렇게 반응하는 집이 **지능형 공간(Intelligent Space)**이에요.","map":[["추위를 느끼는 피부","**센서(Sensor)**, 집의 감각기관"],["'춥네' 하고 생각하는 머리","데이터를 해석하는 시스템"],["겉옷을 집는 손","조명, 보일러처럼 실제로 움직이는 기기"]]},{"kind":"say","lines":["기기를 아무리 많이 놓아도 서로 데이터를 주고받지 않으면 소용없어요.","눈이 봤는데 머리에 안 알려 주면 손이 움직일 수 없는 것과 같아요.","데이터로 집의 가치를 실제로 만들어 내는 체계가 **지능형 홈(AI@Home)**이에요."]}],"pass2":[{"kind":"steps","head":"지능형 공간이 움직이는 순서","steps":["읽기: 공간에 놓인 **센서(Sensor)**가 사람과 환경의 상태를 데이터로 읽어요.","해석: 시스템이 그 데이터가 무슨 뜻인지 풀어요.","반응: 시스템이 스스로 불을 켜거나 온도를 맞추는 물리적 반응을 해요."],"answer":"읽기 → 해석 → 반응. 기기 성능이나 개수가 아니라 '데이터의 해석과 자율 반응'이 핵심이에요."},{"kind":"compare","head":"세 가지 집을 구별해요","cols":["이름","어떻게 움직이나"],"rows":[["**스마트홈(Smart Home)**","앱이나 말로 시켜야 움직여요."],["**규칙 기반 자동화(Rule-based Automation)**","사람이 미리 '이러면 저렇게'를 정해 두고 그대로만 움직여요. 2세대 스마트홈이 이 방식이에요."],["**지능형 홈(AI@Home)**","AI가 생활 패턴을 보고 시키기 전에 먼저 챙겨요."]]},{"kind":"check","q":"**지능형 공간(Intelligent Space)**을 가장 잘 설명한 것은?","choices":["기기 개수가 많은 집","센서가 상태를 데이터로 읽고, 시스템이 해석해 스스로 반응하는 집","월패드로만 조종하는 집","앱을 열어야만 움직이는 집"],"a":1,"why":"기기 수가 아니라 데이터를 읽고, 해석하고, 스스로 반응하는지가 기준이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"부제와 마지막 문장","items":["부제: 기기의 성능이나 개수가 아닌, '데이터의 해석과 자율 반응'에 집중.","편의, 안전 같은 가치는 데이터를 주고받아야 만들어져요. 1강의 **편의(Convenience)**, **안전(Safety)**과 같은 말이에요.","스마트 공간 기획자는 AI가 어디까지 적용될 수 있는지 판단할 수 있어야 해요."]},{"kind":"bg","src":"용어해설집 1, 2번","lines":["**스마트홈(Smart Home)**: 월패드 같은 중앙 제어 인프라를 중심으로 기기를 연결해, 사용자 명령에 따라 원격 제어와 단순 자동화를 해요.","**지능형 홈(AI@Home)**: 인공지능이 생활 패턴과 환경 변화를 스스로 학습, 예측해 먼저 맞춰 주는 집이에요."]}],"pass4":[{"kind":"check","q":"강의 내용과 맞지 않는 것은?","choices":["AI@Home은 데이터를 바탕으로 공간 가치를 실제로 구현하는 체계이다","규칙 기반 2세대에 AI 알고리즘이 결합되며 3세대로 진화 중이다","AI@Home의 완성된 형태는 이미 하나의 표준으로 고정되어 있다","기획자는 AI가 어디까지 적용될지 판단할 수 있어야 한다"],"a":2,"why":"슬라이드는 '완성된 형태는 아직 어디에도 고정되어 있지 않음'이라고 했어요."},{"kind":"check","q":"'사용자가 앱이나 음성으로 명령해야 원격 제어와 단순 자동화가 되는 집'은?","choices":["스마트홈","지능형 홈(AI@Home)","지능형 공간","데이터 레이크"],"a":0,"why":"시켜야 움직이면 **스마트홈(Smart Home)**, 미리 정한 약속대로만 움직이면 **규칙 기반 자동화(Rule-based Automation)**, 알아서 먼저 챙기면 **지능형 홈(AI@Home)**이에요."},{"kind":"english","head":"답안 문장으로 외우기","en":"지능형 공간은 센서가 거주자와 환경의 상태를 데이터로 읽고, 시스템이 이를 해석하여 스스로 물리적 반응을 수행하는 주거 환경이다.","ko":"읽기(센서) → 해석(시스템) → 반응(물리적 반응) 세 동작이 한 문장에 다 들어가야 해요.","tip":"'읽고, 풀고, 움직인다'로 줄여서 떠올려요."}],"pass5":[],"walk":{"head":{"b":[0.0819,0.125,0.3969,0.101],"c":[0.0621,0.109,0.4366,0.133],"r":4.6425,"img":"img/I2/walk/p006_h.jpg"},"parts":[{"b":[0.089,0.236,0.825,0.135],"c":[0.0477,0.2118,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p006_30_01.jpg","say":"지능형 공간의 개념: 공간에 배치된 센서들이 거주자와 환경의 상태를 데이터로 읽어내고, 시스템이 이를 해석하여 스스로 물리적 반응을 수행하는 주거 환경."},{"b":[0.089,0.385,0.825,0.135],"c":[0.0477,0.3608,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p006_30_02.jpg","say":"데이터 기반의 AI@Home: 기기를 많이 배치해도 데이터를 주고받지 않으면 편의, 안전 같은 가치는 만들어지지 않아요. AI@Home은 데이터로 공간 가치를 실제로 구현하는 체계예요."},{"b":[0.089,0.533,0.825,0.179],"c":[0.0477,0.517,0.9075,0.211],"r":6.0825,"img":"img/I2/walk/p006_30_03.jpg","say":"규칙 기반을 넘어서는 진화: 규칙 기반 2세대에 다양한 AI 알고리즘이 결합되며 3세대(AI@Home)로 진화 중이고, 완성된 형태는 아직 어디에도 고정되어 있지 않아요."}]}},{"p":7,"title":"2.1.2 산업계 표준 IoT 데이터 파이프라인 참조 모델","terms":["IoT Data Pipeline","Sensor","WPAN","WAN","Packet","Home Hub","Edge Computing","Fog Computing","Cloud Computing","Data Lake","Response Back To Edge","Dashboard"],"pass1":[{"kind":"analogy","head":"책상과 큰 도서관 사이를 오가는 데이터","scene":"숙제를 하다가 간단한 건 내 책상에서 바로 풀어요. 어려운 자료 조사는 먼 곳의 큰 도서관까지 가서 찾고, 찾은 답을 들고 다시 책상으로 돌아와 숙제를 마무리하죠. 집 안 데이터도 똑같이 우리 집 책상인 허브와 먼 도서관인 클라우드 사이를 오가요.","map":[["내 책상에서 바로 풀기","**엣지 컴퓨팅(Edge Computing)**, 집 안 허브에서 바로 처리"],["먼 곳의 큰 도서관","**클라우드 컴퓨팅(Cloud Computing)**, 집 밖 큰 컴퓨터"],["답을 들고 책상으로 돌아오기","**엣지 환류(Response Back To Edge)**"]]},{"kind":"figure","head":"데이터가 가는 길","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box\" x=\"10\" y=\"36\" width=\"250\" height=\"206\" rx=\"3\"/><text class=\"tm\" x=\"135\" y=\"58\" font-size=\"14\" text-anchor=\"middle\">우리 집 안<\/text><rect class=\"n b1\" x=\"22\" y=\"88\" width=\"72\" height=\"44\" rx=\"3\"/><text class=\"tl b1\" x=\"58\" y=\"116\" font-size=\"15\" text-anchor=\"middle\">센서<\/text><line class=\"e2 b1\" x1=\"94\" y1=\"110\" x2=\"139.0\" y2=\"110.0\"/><polygon class=\"arrow b1\" points=\"148.0,110.0 139.0,105.0 139.0,115.0\"/><rect class=\"n2 b1\" x=\"150\" y=\"88\" width=\"96\" height=\"44\" rx=\"3\"/><text class=\"tl b1\" x=\"198\" y=\"116\" font-size=\"15\" text-anchor=\"middle\">허브<\/text><text class=\"tm b1\" x=\"135\" y=\"262\" font-size=\"14\" text-anchor=\"middle\">허브 = 우리 집 책상<\/text><line class=\"e2 b2\" x1=\"246\" y1=\"102\" x2=\"319.0\" y2=\"102.0\"/><polygon class=\"arrow b2\" points=\"328.0,102.0 319.0,97.0 319.0,107.0\"/><rect class=\"n3 b2\" x=\"330\" y=\"78\" width=\"138\" height=\"66\" rx=\"3\"/><text class=\"tl b2\" x=\"399\" y=\"106\" font-size=\"15\" text-anchor=\"middle\">클라우드<\/text><text class=\"tl b2\" x=\"399\" y=\"130\" font-size=\"14\" text-anchor=\"middle\">먼 곳 큰 도서관<\/text><line class=\"e2 b3\" x1=\"328\" y1=\"128\" x2=\"257.0\" y2=\"128.0\"/><polygon class=\"arrow b3\" points=\"248.0,128.0 257.0,133.0 257.0,123.0\"/><text class=\"t b3\" x=\"399\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">답이 돌아와요<\/text><line class=\"e2 b3\" x1=\"198\" y1=\"132\" x2=\"198.0\" y2=\"171.0\"/><polygon class=\"arrow b3\" points=\"198.0,180.0 203.0,171.0 193.0,171.0\"/><rect class=\"n b3\" x=\"150\" y=\"182\" width=\"96\" height=\"40\" rx=\"3\"/><text class=\"tl b3\" x=\"198\" y=\"207\" font-size=\"14\" text-anchor=\"middle\">조명 켜짐<\/text><\/svg>","caption":"센서 → 허브(책상) → 클라우드(도서관) → 답이 허브로 돌아와 조명이 켜져요.","builds":3},{"kind":"say","lines":["이렇게 정해진 길을 따라 데이터가 흐르는 모양을 **IoT 데이터 파이프라인(IoT Data Pipeline)**이라고 해요.","수도관 속 물처럼, 데이터도 길을 벗어나지 않고 차례로 흘러가요."]}],"pass2":[{"kind":"steps","head":"일곱 단계를 쉬운 말로","steps":["센서가 느껴요. 온도나 움직임을 숫자로 바꿔요.","집 안 가까운 무선 길로 허브까지 보내요. 이 길이 **WPAN(근거리 무선망)**이에요.","허브가 쓸데없는 신호를 거르고, 잠깐 모아 두고, 보내기 좋게 포장해요.","집 밖 먼 곳까지 가는 큰 인터넷 길로 보내요. 이 길이 **WAN(광역 인터넷망)**이에요.","클라우드의 큰 창고인 **데이터 레이크(Data Lake)**에 쌓고 살펴봐요.","AI가 '지금 무슨 상황이지?'를 추론해 할 일을 정하고 답을 돌려보내요.","화면에 보여 주고 사는 사람에게 알림을 보내요."],"answer":"느끼기 → 가까운 길 → 거르기 → 먼 길 → 쌓기 → 판단 → 알림."},{"kind":"compare","head":"가까이서 처리할까, 멀리서 처리할까","cols":["이름","어디서","쉬운 뜻"],"rows":[["**엣지 컴퓨팅(Edge Computing)**","집 안 허브","데이터가 생긴 곳 바로 옆에서 처리해요."],["**포그 컴퓨팅(Fog Computing)**","허브와 클라우드 사이","땅 가까이 깔린 안개처럼 중간 층에서 나눠 처리해요."],["**클라우드 컴퓨팅(Cloud Computing)**","집 밖 먼 서버","아주 큰 컴퓨터가 한꺼번에 처리해요."]]},{"kind":"points","head":"길 위에서 오가는 것","items":["**패킷(Packet)**: 데이터를 작게 나눠 담은 택배 상자예요. 센서는 이 상자에 담아 보내요.","**홈 허브(Home Hub)**: 집 안 기기들을 한데 모아 주는 반장이에요. 그림의 3단계 자리예요.","**엣지 환류(Response Back To Edge)**: 클라우드가 정한 답이 다시 집 안 허브로 내려오는 길이에요."]},{"kind":"check","q":"집 안 가까운 거리만 닿는 무선 길로, 센서 패킷을 허브까지 보내는 단계의 이름은?","choices":["WPAN","WAN","데이터 레이크","Alert"],"a":0,"why":"**WPAN(근거리 무선망)**이에요. 집 밖 먼 곳까지 가는 큰 길은 **WAN(광역 인터넷망)**이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"look","walked":1},{"kind":"compare","head":"그림 라벨 한눈에","cols":["윗줄 분류","박스","아랫줄 우리말"],"rows":[["Sensor","Sense","센서 감지"],["WPAN","Communicate Data","근거리 전송"],["Edge or Fog Node","Locally filter, store, aggregate, package data","로컬 필터링, 저장"],["WAN","Transmit Data","광역 전송"],["Cloud Storage & Networking / Analytics Service","Store Data Lake, Inspect / Predict, Respond","클라우드 저장, 검사 / 예측, 응답"],["Dashboard","Alert","대시보드 경보"]]},{"kind":"points","head":"Edge 박스의 영어 네 단어","items":["Locally filter: 로컬에서 잡음(노이즈)을 걸러내요.","store: 잠깐 저장해요.","aggregate: 여러 값을 모아요(집계).","package data: 보내기 좋게 포장해요(패키징)."]},{"kind":"figure","head":"일곱 단계와 되돌아오는 길","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tb\" x=\"60\" y=\"40\" font-size=\"15\" text-anchor=\"middle\">센서<\/text><text class=\"tm\" x=\"60\" y=\"60\" font-size=\"14\" text-anchor=\"middle\">Sense<\/text><text class=\"tb\" x=\"170\" y=\"40\" font-size=\"15\" text-anchor=\"middle\">허브 쪽<\/text><text class=\"tm\" x=\"170\" y=\"60\" font-size=\"14\" text-anchor=\"middle\">Edge / Fog<\/text><text class=\"tb\" x=\"300\" y=\"40\" font-size=\"15\" text-anchor=\"middle\">클라우드<\/text><text class=\"tm\" x=\"300\" y=\"60\" font-size=\"14\" text-anchor=\"middle\">Cloud<\/text><text class=\"tb\" x=\"420\" y=\"40\" font-size=\"15\" text-anchor=\"middle\">화면<\/text><text class=\"tm\" x=\"420\" y=\"60\" font-size=\"14\" text-anchor=\"middle\">Alert<\/text><rect class=\"n b1\" x=\"20\" y=\"90\" width=\"80\" height=\"40\" rx=\"3\"/><text class=\"tl b1\" x=\"60\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">1 감지<\/text><line class=\"e2 b1\" x1=\"100\" y1=\"110\" x2=\"119.0\" y2=\"110.0\"/><polygon class=\"arrow b1\" points=\"128.0,110.0 119.0,105.0 119.0,115.0\"/><text class=\"tm b1\" x=\"114\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">WPAN<\/text><rect class=\"n2 b2\" x=\"130\" y=\"90\" width=\"80\" height=\"40\" rx=\"3\"/><text class=\"tl b2\" x=\"170\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">3 거르기<\/text><line class=\"e2 b2\" x1=\"210\" y1=\"110\" x2=\"249.0\" y2=\"110.0\"/><polygon class=\"arrow b2\" points=\"258.0,110.0 249.0,105.0 249.0,115.0\"/><text class=\"tm b2\" x=\"234\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">WAN<\/text><rect class=\"n3 b3\" x=\"260\" y=\"80\" width=\"80\" height=\"60\" rx=\"3\"/><text class=\"tl b3\" x=\"300\" y=\"105\" font-size=\"14\" text-anchor=\"middle\">5 저장<\/text><text class=\"tl b3\" x=\"300\" y=\"127\" font-size=\"14\" text-anchor=\"middle\">6 예측<\/text><line class=\"e2 b3\" x1=\"340\" y1=\"110\" x2=\"369.0\" y2=\"110.0\"/><polygon class=\"arrow b3\" points=\"378.0,110.0 369.0,105.0 369.0,115.0\"/><rect class=\"n b3\" x=\"380\" y=\"90\" width=\"80\" height=\"40\" rx=\"3\"/><text class=\"tl b3\" x=\"420\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">7 경보<\/text><line class=\"e b4\" x1=\"300\" y1=\"142\" x2=\"300.0\" y2=\"196.0\"/><line class=\"e b4\" x1=\"300\" y1=\"205\" x2=\"179.0\" y2=\"205.0\"/><line class=\"e2 b4\" x1=\"170\" y1=\"205\" x2=\"170.0\" y2=\"143.0\"/><polygon class=\"arrow b4\" points=\"170.0,134.0 165.0,143.0 175.0,143.0\"/><text class=\"t b4\" x=\"236\" y=\"230\" font-size=\"14\" text-anchor=\"middle\">엣지 환류 (결과가 허브로)<\/text><\/svg>","caption":"번호는 파이프라인 단계예요. 5, 6단계가 끝나면 결과가 엣지 환류로 허브에 돌아와요.","builds":4},{"kind":"bg","src":"기초 다지기 5단원 (무선의 저울)","lines":["무선망은 닿는 범위로 이름이 달라져요. WPAN(개인 주변) < WLAN(건물) < WMAN(도시) < WWAN(광역) 순서로 넓어져요.","파이프라인의 2단계가 가장 좁은 **WPAN(근거리 무선망)**, 4단계가 넓은 **WAN(광역 인터넷망)**이라고 짝지어 두면 편해요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 5번","q":"에지 디바이스의 대규모 데이터를 중앙 클라우드로 모두 보내지 않고, 에지와 클라우드 사이의 중간 계층에서 분산 처리하여 지연 시간(Latency)을 줄이는 컴퓨팅 방식은?","qko":"엣지와 클라우드 '사이'에서 처리하는 방식의 이름을 묻는 문제예요.","solve":["보기: 포그 컴퓨팅, 클라우드 컴퓨팅, 양자 컴퓨팅, 앰비언트 컴퓨팅.","클라우드 컴퓨팅은 중앙 서버로 다 보내는 방식이라 반대예요.","용어해설집 16번: 포그 컴퓨팅은 엣지와 클라우드 사이 로컬 네트워크 계층에서 처리해요.","그림의 3단계 이름도 'Edge or Fog Node'였어요."],"answer":"포그 컴퓨팅(Fog Computing)"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 19번","q":"무선 네트워크 기술의 서비스 영역(통신 범위)을 작은 것부터 큰 것 순으로 올바르게 나열한 것은?","qko":"무선망 네 종류를 좁은 것부터 넓은 것 순으로 고르는 문제예요.","solve":["P는 개인(Personal), L은 지역(Local), M은 도시(Metropolitan), W는 광역(Wide)이에요.","개인 주변 → 건물 → 도시 → 광역 순으로 넓어져요."],"answer":"WPAN < WLAN < WMAN < WWAN"},{"kind":"check","q":"파이프라인 참조 모델의 단계와 역할 연결로 옳지 않은 것은?","choices":["1단계: 센서가 물리적 변화를 디지털 데이터로 변환","3단계: Edge 허브 노드에서 노이즈 필터링 및 임시 저장","5단계: WAN 광역망으로 세대 밖에 패킷 전송","7단계: 대시보드에 상태 시각화 및 알림 경보 송출"],"a":2,"why":"WAN 광역 전송은 4단계예요. 5단계는 클라우드 **데이터 레이크(Data Lake)** 누적 저장, 검사, 분석이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["필기 가이드북 1권은 **엣지 컴퓨팅(Edge Computing)**을 지표면 가까운 안개 같은 개념이라 '포그 컴퓨팅' 또는 '클라우드렛(Cloudlet)'이라고도 부른다고 적었어요. 기출은 '중간 계층'이라는 말이 나오면 포그를 답으로 봐요.","저장은 두 번 나와요. 3단계 로컬 임시 저장과 5단계 클라우드 대규모 저장이에요."]}],"pass5":[{"kind":"points","head":"실기 연결: 구성도 속 파이프라인 (실기 가이드북 2권 1-1 #5 구축 및 자동화)","items":["문제: 지그비 엔드 디바이스가 최종적으로 연결되는 네트워크 장비와, 인터넷과 최종 연결되는 게이트웨이 역할 장비를 드래그해 구성도를 완성해요.","가이드북 풀이: 지그비 코디네이터는 지그비 네트워크를 묶고 유무선 공유기와도 연결해서, 판매할 때 '지그비 허브'나 '지그비 게이트웨이'라고 불러요.","파이프라인으로 읽으면: 센서(1단계) → **WPAN(근거리 무선망)**(2단계, 지그비) → 지그비 허브(3단계) → 공유기를 거쳐 인터넷(4단계, **WAN(광역 인터넷망)**)이에요.","지그비 라우터는 신호를 강하게 이어 주는 역할도 해서 '지그비 리피터'라고도 불려요."]},{"kind":"check","q":"실기 구성도 문제에서 지그비 센서가 가장 먼저 연결되는 장비로 알맞은 것은?","choices":["지그비 허브","스마트 냉장고","유무선 공유기만","월패드"],"a":0,"why":"지그비 센서는 지그비 허브(코디네이터)에 붙고, 허브가 공유기를 통해 인터넷으로 나가요."}],"walk":{"head":{"b":[0.0823,0.125,0.5246,0.0638],"c":[0.0561,0.109,0.5771,0.0958],"r":8.5193,"img":"img/I2/walk/p007_h.jpg"},"parts":[{"b":[0.107,0.288,0.061,0.104],"c":[0.0375,0.272,0.2,0.136],"r":2.0798,"img":"img/I2/walk/p007_30_01.jpg","say":"Sensor / Sense: 센서가 물리적 변화를 감지해요. 우리말 라벨은 '센서 감지'."},{"b":[0.179,0.288,0.061,0.104],"c":[0.1095,0.272,0.2,0.136],"r":2.0798,"img":"img/I2/walk/p007_30_02.jpg","say":"WPAN / Communicate Data: 근거리 무선으로 데이터를 보내요. 우리말 '근거리 전송'."},{"b":[0.25,0.288,0.1,0.111],"c":[0.2,0.272,0.2,0.143],"r":1.9779,"img":"img/I2/walk/p007_30_03.jpg","say":"Edge or Fog Node / Locally filter, store, aggregate, package data: 로컬에서 거르고, 저장하고, 모으고, 포장해요. 우리말 '로컬 필터링, 저장'."},{"b":[0.363,0.288,0.06,0.104],"c":[0.293,0.272,0.2,0.136],"r":2.0798,"img":"img/I2/walk/p007_30_04.jpg","say":"WAN / Transmit Data: 광역망으로 데이터를 전송해요. 우리말 '광역 전송'."},{"b":[0.437,0.288,0.149,0.104],"c":[0.4115,0.272,0.2,0.136],"r":2.0798,"img":"img/I2/walk/p007_31_01.jpg","say":"Cloud Storage & Networking / Store Data Lake, Inspect: 데이터 레이크에 저장하고 검사해요. 우리말 '클라우드 저장, 검사'."},{"b":[0.604,0.288,0.141,0.104],"c":[0.5745,0.272,0.2,0.136],"r":2.0798,"img":"img/I2/walk/p007_31_02.jpg","say":"Analytics Service / Predict, Respond: 예측하고 응답해요. 우리말 '예측, 응답'."},{"b":[0.813,0.288,0.069,0.104],"c":[0.7475,0.272,0.2,0.136],"r":2.0798,"img":"img/I2/walk/p007_31_03.jpg","say":"Dashboard / Alert: 대시보드에서 경보를 띄워요. 우리말 '대시보드 경보'."},{"b":[0.286,0.384,0.357,0.111],"c":[0.2681,0.368,0.3927,0.143],"r":3.8837,"img":"img/I2/walk/p007_31_04.jpg","say":"Response Back To Edge: Predict에서 출발한 빨간 점선이 Edge 박스로 돌아가요. 클라우드 분석 결과를 로컬 허브로 회신해 즉각 실행하는 길이에요."}]}},{"p":8,"title":"2.1.3 IoT 데이터 파이프라인과 1-Loop 동작 매핑","terms":["IoT Data Pipeline","1-Loop","Sense","Transmit","Analyze","Act","Backend Infrastructure","Human-Centered Design","WPAN","WAN","Data Lake"],"pass1":[{"kind":"analogy","head":"뜨거운 냄비를 만졌을 때","scene":"뜨거운 냄비에 손이 닿으면 손끝이 먼저 느껴요. 소식이 뇌로 가고, 뇌가 '앗 뜨거' 판단하면 손을 떼죠. 뇌가 기억을 어디에 보관하는지는 못 느껴요. 집도 느끼는 네 동작만 남겨 봐요.","map":[["피부가 느낌","**감지(Sense)**"],["소식이 뇌로 전해짐","**전달(Transmit)**"],["뇌가 '앗 뜨거' 판단","**판단(Analyze)**"],["손을 뗌","**실행(Act)**, 손발인 액추에이터가 움직임"]]},{"kind":"say","lines":["길이 일곱 단계라도, 사는 사람이 느끼는 건 네 동작뿐이에요.","이 네 동작의 한 바퀴를 **1-Loop(원 루프)**라고 불러요.","창고에 쌓아 두는 단계는 사람이 느끼지 못해서 빠져요."]}],"pass2":[{"kind":"compare","head":"일곱 단계를 네 동작에 짝짓기","cols":["파이프라인 단계","1-Loop"],"rows":[["1단계 센서 감지","**감지(Sense)**"],["2단계 WPAN 전송 / 4단계 WAN 전송","**전달(Transmit)**"],["3단계 로컬 임시 저장 / 5단계 클라우드 저장","짝 없음 (경유, 저장)"],["6단계 AI 결정, 회신","**판단(Analyze)** → **실행(Act)**"],["7단계 대시보드 경보","**실행(Act)**"]]},{"kind":"points","head":"왜 저장은 빠질까","items":["**백엔드 인프라 경유 통로(Backend Infrastructure)**: 눈에 안 보이는 뒤쪽 창고와 복도라는 뜻이에요.","데이터가 잠깐 머물거나 다듬어지는 곳일 뿐, 공간을 직접 바꾸지 않아요.","그래서 사는 사람 기준으로 보는 **인간중심 설계(Human-Centered Design)** 관점에서는 걷어내요."]},{"kind":"check","q":"파이프라인의 '클라우드 데이터 레이크 저장' 단계는 1-Loop의 어디에 짝지어질까?","choices":["감지","전달","판단","짝지어지는 단계 없음"],"a":3,"why":"저장은 **백엔드 인프라 경유 통로(Backend Infrastructure)**라서 1-Loop에서 빠져요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"표의 오른쪽 칸만 위에서부터","items":["감지 / 전달 / 대응 없음 / 전달 / 대응 없음 / 판단 → 실행 / 실행.","'대응 없음'은 3단계와 5단계, 둘 다 저장이 들어간 단계예요.","**전달(Transmit)**은 두 번 나와요. **WPAN(근거리 무선망)**도 **WAN(광역 인터넷망)**도 결국 데이터를 옮기는 일이거든요."]},{"kind":"warn","head":"표에서 놓치기 쉬운 칸","items":["6단계 하나가 **판단(Analyze)**과 **실행(Act)** 두 동작에 걸쳐 있어요. 결정(판단)하고 회신(실행 지시)까지 하기 때문이에요.","7단계 대시보드 알림도 **실행(Act)**이에요. 사람에게 알려 주는 것도 실제 반응으로 봐요."]}],"pass4":[{"kind":"check","q":"IoT 데이터 파이프라인 7단계와 1-Loop 매핑으로 옳지 않은 것은?","choices":["1단계 센서 감지 → 감지(Sense)","3단계 Edge 노이즈 필터링 및 임시 저장 → 판단(Analyze)","4단계 WAN 광역 전송 → 전달(Transmit)","7단계 대시보드 알림 경보 → 실행(Act)"],"a":1,"why":"3단계는 경유, 저장이라 1-Loop에 직접 대응하는 단계가 없어요."},{"kind":"check","q":"6단계 'AI 엔진이 제어 지시를 결정, 회신'은 1-Loop의 어느 단계에 대응할까?","choices":["감지 하나","전달 하나","판단과 실행 두 단계","대응 없음"],"a":2,"why":"슬라이드 표기는 '판단(Analyze) → 실행(Act)'이에요."},{"kind":"english","head":"답안 문장으로 외우기","en":"로컬 임시 저장과 클라우드 대규모 저장은 백엔드 인프라 경유 통로일 뿐 공간을 직접 변화시키는 판단이나 실행이 아니므로 1-Loop에서 제외된다.","ko":"'왜 저장 단계가 1-Loop에 없나'를 서술로 물으면 이 문장을 써요.","tip":"'창고는 안 보인다, 안 보이면 빠진다'로 기억해요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.7292,0.1124],"c":[0.0458,0.1096,0.8022,0.1444],"r":7.8566,"img":"img/I2/walk/p008_h.jpg"},"parts":[{"b":[0.089,0.24,0.825,0.053],"c":[0.0477,0.1748,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p008_30_01.jpg","say":"1단계: 공간 내 물리적 변화(온도, 조도, 동작 등)를 센서가 측정해 디지털 데이터로 변환 → 감지(Sense)."},{"b":[0.089,0.293,0.825,0.155],"c":[0.0477,0.277,0.9075,0.187],"r":6.8632,"img":"img/I2/walk/p008_30_02.jpg","say":"2단계 WPAN으로 센서 패킷을 허브에 전달, 4단계 WAN으로 세대 밖 클라우드에 패킷 전송 → 둘 다 전달(Transmit). 가운데 3단계 Edge 노이즈 필터링, 임시 저장은 '경유, 저장, 1-Loop 직접 대응 없음'."},{"b":[0.089,0.447,0.825,0.052],"c":[0.0477,0.3813,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p008_30_03.jpg","say":"5단계: 클라우드 데이터 레이크에 대규모 데이터를 누적 저장하고 검사, 분석 → 경유, 저장, 대응 없음."},{"b":[0.089,0.499,0.825,0.052],"c":[0.0477,0.4333,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p008_30_04.jpg","say":"6단계: AI 엔진이 데이터를 분석해 거주자의 맥락을 추론하고 제어 지시를 결정, 회신 → 판단(Analyze) → 실행(Act)."},{"b":[0.089,0.551,0.825,0.054],"c":[0.0477,0.4863,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p008_30_05.jpg","say":"7단계: 대시보드 화면에 상태를 시각화하고 거주자에게 알림 경보 송출 → 실행(Act)."},{"b":[0.089,0.611,0.825,0.118],"c":[0.0477,0.5783,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p008_30_06.jpg","say":"이해의 공식: 로컬 임시 저장이나 클라우드 대규모 저장은 '백엔드 인프라 경유 통로'일 뿐, 공간을 직접 바꾸는 판단이나 실행이 아니라 1-Loop에서 제외돼요."}]}},{"p":9,"title":"2.1.4 Edge(로컬 허브) 처리 vs Cloud(클라우드) 서버 처리","terms":["Edge Computing","Gateway","Home Hub","Cloud Computing","Latency","Encryption","Remote Monitoring","Generative AI","Sensor"],"pass1":[{"kind":"analogy","head":"급한 일은 책상에서, 큰 공부는 도서관에서","scene":"짧은 계산은 내 책상에서 바로 해요. 인터넷이 끊겨도 책상은 그대로고, 일기장을 남에게 보일 일도 없죠. 몇 달 치 자료로 하는 큰 공부는 먼 곳의 큰 도서관이 훨씬 잘해요.","map":[["내 책상에서 바로 계산","**엣지 컴퓨팅(Edge Computing)**, 집 안 허브에서 처리"],["인터넷이 끊겨도 책상은 그대로","외부 인터넷이 끊겨도 집 안 제어는 계속"],["먼 곳의 큰 도서관","**클라우드 컴퓨팅(Cloud Computing)**, 몇 달 치 데이터와 큰 AI를 다룸"]]},{"kind":"say","lines":["가스가 새면 먼 도서관에 물어볼 틈이 없어요. 집 안 허브가 바로 밸브를 잠가야 해요.","몇 달 동안 전기를 얼마나 썼는지 분석하는 일은 클라우드에 맡기면 돼요.","급하고 안전한 일은 집 안, 크고 오래 걸리는 일은 먼 곳이에요."]}],"pass2":[{"kind":"compare","head":"두 처리 방식의 특징","cols":["","Edge / Gateway 로컬 처리","Cloud 서버 중앙 처리"],"rows":[["한 줄 요약","실시간성, 망 단절 대응, 보안","대규모 연산, 장기 학습"],["특징 하나","네트워크 지연 최소화","장기 시계열 분석"],["특징 둘","인프라 단절 방어","복합 AI 모델 연동"],["특징 셋","프라이버시 보호","원격 모니터링"]]},{"kind":"points","head":"표에 나온 말 풀이","items":["**게이트웨이(Gateway)**: 서로 다른 네트워크 사이의 문지기예요. 슬라이드는 이 자리를 '스마트홈 허브'라고 적었어요.","**지연 시간(Latency)**: 명령하고 기기가 반응할 때까지 기다리는 시간이에요. 집 안에서 처리하면 짧아져요.","**암호화(Encryption)**: 남이 못 읽게 데이터를 비밀 글씨로 바꾸는 일이에요.","**원격 모니터링(Remote Monitoring)**: 집 밖에서도 우리 집 상태를 들여다보는 일이에요.","**생성형 AI(Generative AI)**: 글, 그림, 목소리를 새로 만들어 내는 덩치 큰 AI예요. 집 안 허브에는 안 들어가서 클라우드가 맡아요."]},{"kind":"check","q":"외부 인터넷이 끊겨도 조명과 안전 센서가 계속 동작하게 하려면 어디서 처리해야 할까?","choices":["집 안 허브(Edge)","클라우드 서버","대시보드 화면","데이터 레이크"],"a":0,"why":"집 안 **홈 허브(Home Hub)**에서 처리하면 인터넷이 끊겨도 동작해요. 이게 '인프라 단절 방어'예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"steps","head":"안전 센서가 Edge에서 처리되는 순서","steps":["안전 **센서(Sensor)**가 위험 신호를 감지해요.","신호가 세대 안 허브(**게이트웨이(Gateway)**)로 바로 가요.","허브가 클라우드를 기다리지 않고 그 자리에서 바로 제어해요.","기록은 나중에 클라우드로 올라가 장기 분석에 쓰여요."],"answer":"급한 반응은 Edge, 쌓인 기록 분석은 Cloud로 역할을 나눠요."},{"kind":"points","head":"슬라이드 문장 그대로 챙길 것","items":["'세대 내'는 우리 집 안, '세대 밖'은 우리 집 밖이라는 뜻이에요.","Edge 쪽 보안은 '세대 내 **암호화(Encryption)** 처리'로 적혀 있어요.","Cloud 쪽에는 '대규모 **생성형 AI(Generative AI)** 에이전트 연동'이 들어가요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 7번","q":"일부 기능은 가정 내 게이트웨이에서 처리하고, 대규모 데이터 분석과 외부 원격 서비스는 클라우드에서 수행하도록 구성할 때 특징으로 가장 적절한 것은?","qko":"게이트웨이와 클라우드를 같이 쓰는 구성이 어떤 장점이 있는지 묻는 문제예요.","solve":["'클라우드에서만 처리하니 게이트웨이가 필요 없다'는 구성 자체와 맞지 않아요.","'서로 다른 통신 기기는 연동할 수 없다'는 틀린 말이에요.","'게이트웨이에서 처리하면 클라우드 연계를 못 한다'도 틀린 말이에요.","게이트웨이는 기기 제어와 일부 처리, 클라우드는 대규모 분석과 원격 서비스로 역할을 나눌 수 있어요."],"answer":"게이트웨이와 클라우드가 역할을 분담할 수 있다"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 24번","q":"외부에서 원격 제어할 때 전송 중 제3자가 데이터 내용을 임의로 확인하기 어렵게 보호하는 데 가장 적합한 보안 기술은? (접근 제어, 사용자 인증, 암호화, 무결성 검증)","qko":"남이 중간에서 봐도 내용을 모르게 하는 기술을 고르는 문제예요.","solve":["접근 제어와 사용자 인증은 '누가 들어올 수 있나'를 정해요.","무결성 검증은 '내용이 바뀌지 않았나'를 확인해요.","내용 자체를 못 읽게 만드는 건 암호화예요. 슬라이드 Edge 쪽 '세대 내 암호화 처리'와 같은 말이에요."],"answer":"암호화(Encryption)"},{"kind":"check","q":"강의에서 Cloud 서버 중앙 처리의 특징으로 나온 것은?","choices":["네트워크 지연 최소화","인프라 단절 방어","복합 AI 모델 연동","세대 내 암호화"],"a":2,"why":"나머지 셋은 Edge 쪽이에요. Cloud는 장기 시계열 분석, 복합 AI 모델 연동, **원격 모니터링(Remote Monitoring)**이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["필기 36번 기출은 허브나 게이트웨이가 '모든 기기의 통신 규격을 자동으로 똑같이 바꿔 완전한 호환을 보장한다'는 보기를 틀린 설명으로 냈어요. 허브는 중계, 상태 수집, 명령 전달을 할 뿐이에요.","용어해설집 12번은 **엣지 컴퓨팅(Edge Computing)**이 응답 지연을 줄이고, 네트워크 부하를 나누고, 프라이버시 보호에 도움이 된다고 정의해요."]}],"pass5":[{"kind":"compare","head":"실기 연결: 지능형홈 서비스 모델 선정 (실기 가이드북 2권 1-1 #3)","cols":["모델","예","가이드북에 적힌 특징"],"rows":[["스마트게이트웨이 모델","건설사 아파트 유선 플랫폼","상당히 안정적, 주차 제어나 엘리베이터 호출처럼 다른 플랫폼이 어려운 일이 가능"],["IoT 클라우드 모델","스마트싱스, 홈킷, 구글홈","기기 종류와 상관없이 여러 서비스 개발 가능. 작동 딜레이가 생길 수 있고 플랫폼 서버 문제 시 먹통"],["하이브리드 모델","홈 어시스턴트(HA)","확장성이 뛰어나고 개인 서버라 반응이 빠름. 개발 지식이 없으면 구축이 어렵고 Zigbee, Z-Wave는 허브 같은 부가 장치 필요"]]},{"kind":"points","head":"슬라이드와 짝짓기","items":["IoT 클라우드 모델의 단점 '작동 딜레이, 서버 문제 시 먹통'이 바로 Cloud만 믿을 때의 약점이에요.","그래서 강의는 안전 센서와 조명을 세대 내 허브에서 로컬로 실행되게 우선 설계하라고 했어요.","가이드북은 현재 대다수 스마트기기 제조업체가 IoT 클라우드 모델을 채용하고 있다고 적었어요."]},{"kind":"check","q":"실기 가이드북에서 '플랫폼 서버 문제 발생 시 먹통'을 단점으로 적은 서비스 모델은?","choices":["스마트게이트웨이 모델","IoT 클라우드 모델","하이브리드 모델","해당 없음"],"a":1,"why":"IoT 클라우드 모델은 서버에 의존해서 작동 딜레이와 서버 장애에 약해요."}],"walk":{"head":{"b":[0.0823,0.125,0.6185,0.0687],"c":[0.0514,0.109,0.6803,0.1007],"r":9.5541,"img":"img/I2/walk/p009_h.jpg"},"parts":[{"b":[0.089,0.196,0.407,0.317],"c":[0.0686,0.18,0.4477,0.349],"r":1.8142,"img":"img/I2/walk/p009_30_01.jpg","say":"Edge / Gateway(스마트홈 허브) 로컬 처리: 실시간성, 망 단절 대응, 보안. 지연 최소화(허브에서 즉각 반응), 단절 방어(인터넷이 끊겨도 제어 유지), 프라이버시 보호(세대 내 암호화)."},{"b":[0.507,0.196,0.407,0.317],"c":[0.4867,0.18,0.4477,0.349],"r":1.8142,"img":"img/I2/walk/p009_30_02.jpg","say":"Cloud 서버 중앙 처리: 대규모 연산, 장기 학습. 장기 시계열 분석(수개월 에너지, 생활 패턴), 복합 AI 모델 연동(대규모 AI, 외부 서비스), 원격 모니터링(원격 접속, 통합 관제)."},{"b":[0.089,0.525,0.407,0.146],"c":[0.0686,0.509,0.4477,0.178],"r":3.557,"img":"img/I2/walk/p009_30_03.jpg","say":"세대 내 Edge(허브) 계층 역할: 안전 센서 및 조명 제어는 외부 인터넷 장애와 무관하게 세대 내 허브(Gateway)를 통해 로컬에서 실행되도록 우선 설계."},{"b":[0.507,0.525,0.407,0.146],"c":[0.4867,0.509,0.4477,0.178],"r":3.557,"img":"img/I2/walk/p009_30_04.jpg","say":"원격 Cloud 계층 역할: 세대 밖 원격 제어, 장기 누적 에너지 분석, 대규모 생성형 AI 에이전트 연동 등 중앙 연산 전담."}]}},{"p":10,"title":"2.1.5 Loop 데이터 순환 메커니즘","terms":["1-Loop","Sense","Transmit","Analyze","Act","Sensor","Actuator","Feedback Control","Packet","Home Hub","Human-Centered Design"],"pass1":[{"kind":"analogy","head":"느끼고, 알리고, 생각하고, 움직이는 몸","scene":"어두운 방에 들어서면 눈이 먼저 '어둡네' 하고 느껴요. 그 소식이 신경을 타고 머리로 가고, 머리가 '불을 켜자' 하고 정하면 손이 스위치를 눌러요. 불이 켜지면 눈이 다시 밝아진 걸 느끼고, 이렇게 한 바퀴가 닫혀요.","map":[["어둡다고 느끼는 눈","**센서(Sensor)**, 집의 감각기관"],["소식을 나르는 신경","무선망, 네트워크"],["'불을 켜자' 정하는 머리","판단하는 엔진"],["스위치를 누르는 손","**액추에이터(Actuator)**, 집의 손발"]]},{"kind":"figure","head":"집이 한 바퀴 도는 모양","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n2 b1\" x=\"185\" y=\"20\" width=\"110\" height=\"46\" rx=\"3\"/><text class=\"tl b1\" x=\"240\" y=\"49\" font-size=\"15\" text-anchor=\"middle\">감지 (센서)<\/text><line class=\"e2 b1\" x1=\"295\" y1=\"50\" x2=\"353.4\" y2=\"103.9\"/><polygon class=\"arrow b1\" points=\"360.0,110.0 356.8,100.2 350.0,107.6\"/><rect class=\"n b2\" x=\"345\" y=\"112\" width=\"125\" height=\"46\" rx=\"3\"/><text class=\"tl b2\" x=\"407\" y=\"141\" font-size=\"15\" text-anchor=\"middle\">전달 (무선망)<\/text><line class=\"e2 b2\" x1=\"385\" y1=\"158\" x2=\"307.7\" y2=\"205.3\"/><polygon class=\"arrow b2\" points=\"300.0,210.0 310.3,209.6 305.1,201.0\"/><rect class=\"n3 b3\" x=\"185\" y=\"208\" width=\"110\" height=\"46\" rx=\"3\"/><text class=\"tl b3\" x=\"240\" y=\"237\" font-size=\"15\" text-anchor=\"middle\">판단 (엔진)<\/text><line class=\"e2 b3\" x1=\"185\" y1=\"232\" x2=\"111.7\" y2=\"166.0\"/><polygon class=\"arrow b3\" points=\"105.0,160.0 108.3,169.7 115.0,162.3\"/><rect class=\"n b4\" x=\"10\" y=\"112\" width=\"140\" height=\"46\" rx=\"3\"/><text class=\"tl b4\" x=\"80\" y=\"141\" font-size=\"15\" text-anchor=\"middle\">실행 (손발)<\/text><line class=\"e2 b4\" x1=\"90\" y1=\"112\" x2=\"175.5\" y2=\"55.0\"/><polygon class=\"arrow b4\" points=\"183.0,50.0 172.7,50.8 178.3,59.2\"/><text class=\"tb\" x=\"240\" y=\"142\" font-size=\"18\" text-anchor=\"middle\">한 바퀴<\/text><\/svg>","caption":"감지 → 전달 → 판단 → 실행, 그리고 다시 감지로 돌아와요.","builds":4},{"kind":"say","lines":["이 한 바퀴를 **1-Loop(원 루프)**라고 불러요. 1은 '한', Loop는 '바퀴'라는 뜻이에요.","센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요."]}],"pass2":[{"kind":"points","head":"루프가 무엇이고 왜 필요한지","items":["루프: **센서(Sensor)**에서 출발한 데이터가 네트워크와 계산을 거쳐 **액추에이터(Actuator)**가 실제로 움직이며 끝나는 순환이에요.","슬라이드는 이것을 '자율 순환 **피드백 제어(Feedback Control)** 체계'라고 불러요. 결과를 다시 확인하며 조절한다는 뜻이에요.","데이터가 중간에 끊기면 집은 느끼기만 하고 아무것도 못 해요. 현장으로 되돌아와야 해요.","일곱 단계에서 사는 사람이 느끼는 흐름만 남긴 게 네 단계예요. 이게 **인간중심 설계(Human-Centered Design)** 관점이에요."]},{"kind":"compare","head":"네 단계의 주인공","cols":["단계","주인공","하는 일"],"rows":[["**감지(Sense)**","센서","공간의 변화를 디지털 데이터로 잡아요."],["**전달(Transmit)**","무선망","모은 **패킷(Packet)**을 허브, 엣지, 클라우드로 실시간으로 보내요."],["**판단(Analyze)**","엔진","데이터를 분석해 사는 사람의 상황을 추론하고 실행할지 정해요."],["**실행(Act)**","액추에이터","조명을 켜고, 냉난방을 돌리고, 밸브를 잠가요."]]},{"kind":"check","q":"**액추에이터(Actuator)**에 대한 설명으로 알맞은 것은?","choices":["온도를 느끼는 장치","명령을 받아 실제로 움직이는 장치","데이터를 저장하는 창고","무선 신호를 보내는 길"],"a":1,"why":"느끼는 건 **센서(Sensor)**, 실제로 움직이는 손발은 **액추에이터(Actuator)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"look","walked":1},{"kind":"steps","head":"예시: 밤에 욕실 앞에서 물이 샐 때","steps":["**감지(Sense)**: 바닥의 누수 센서가 물을 느껴요.","**전달(Transmit)**: 무선망이 그 신호를 **홈 허브(Home Hub)**로 보내요.","**판단(Analyze)**: 엔진이 '위험하니 밸브를 잠그자'로 정해요.","**실행(Act)**: **액추에이터(Actuator)**가 급수 밸브를 잠가요."],"answer":"네 단계가 끊기지 않아야 물이 더 새기 전에 막혀요."},{"kind":"points","head":"카드 제목 네 개","items":["센서의 상태 측정 / 네트워크 신호 전송 / 상황 해석 및 결정 / 물리 공간 환경 제어.","감지 카드의 예: 온도, 조도, 동작, 문열림.","실행 카드의 예: 조명 점등, 냉난방 가동, 밸브 차단."]}],"pass4":[{"kind":"check","q":"1-Loop 3단계 판단(Analyze)의 설명으로 가장 적절한 것은?","choices":["센서가 물리적 변화를 디지털 데이터로 포착","무선망이 패킷을 처리 계층으로 실시간 전송","엔진이 데이터를 분석해 거주자의 맥락을 추론하고 실행 여부를 결정","액추에이터가 물리 환경을 변경"],"a":2,"why":"판단 카드의 제목은 '상황 해석 및 결정'이에요."},{"kind":"check","q":"1-Loop 설명으로 옳지 않은 것은?","choices":["거주자가 체감하는 흐름만 남긴 것이다","감지, 전달, 판단, 실행 네 단계이다","클라우드 저장까지 모두 포함한 일곱 단계 모델이다","액추에이터 구동으로 완결되는 순환 체계이다"],"a":2,"why":"저장, 경유 인프라 과정은 추상화해 걷어냈어요. 1-Loop는 네 단계예요."},{"kind":"english","head":"답안 문장으로 외우기","en":"루프(Loop)란 센서에서 출발한 데이터가 네트워크와 연산 처리를 거쳐 물리적 액추에이터 구동으로 완결되는 자율 순환 피드백 제어 체계이다.","ko":"출발(센서), 거쳐 감(네트워크, 연산), 끝(액추에이터)이 한 문장에 다 있어야 해요.","tip":"용어해설집 48번의 액추에이터 정의 '제어 신호를 받아 밸브 차단, 조명 점등 같은 물리적 동작을 실제로 수행하는 장치'와 같이 외워요."}],"pass5":[{"kind":"steps","head":"실기 연결: 스마트 주방 센서 배치 (실기 가이드북 2권 1-1 #1, #2)","steps":["요구: 식탁에 다가가 앉으면 식탁등이 자동으로 켜지고 앉아 있는 동안 유지돼요.","**감지(Sense)**: 사람을 알아채는 모션(동작) 감지 센서가 필요해요.","**판단(Analyze)** → **실행(Act)**: 식탁에 사람이 있으면 식탁등 On, 없거나 싱크대 통로를 지나가면 식탁등 Off.","배치 주의: 모션 감지 영역은 120도라 각도를 못 맞추면 오작동해요. 싱크대 센서는 90도로 맞춰 식탁 통로에서 감지되지 않게 해요."],"answer":"센서 자리를 잘못 잡으면 감지 단계부터 틀어져서 한 바퀴 전체가 오작동해요."},{"kind":"warn","head":"가이드북에 적힌 흔한 실수","items":["PIR 센서는 사람이 움직이지 않으면 사람이 없는 것으로 보고 불을 꺼 버리는 오작동이 생겨요.","그래서 가이드북은 'PIR 센서의 문제점 해결 필요'를 주의사항으로 적었어요."]}],"walk":{"head":{"b":[0.0823,0.125,0.3535,0.0682],"c":[0.0646,0.109,0.3888,0.1002],"r":5.4876,"img":"img/I2/walk/p010_h.jpg"},"parts":[{"b":[0.125,0.212,0.786,0.076],"c":[0.0857,0.1627,0.8646,0.1747],"r":6.9991,"img":"img/I2/walk/p010_30_01.jpg","say":"루프(Loop)란: 공간에 배치된 센서에서 출발한 데이터가 네트워크와 연산 처리를 거쳐 물리적 액추에이터 구동으로 완결되는 '자율 순환 피드백 제어 체계'."},{"b":[0.125,0.291,0.786,0.068],"c":[0.0857,0.2377,0.8646,0.1747],"r":6.9991,"img":"img/I2/walk/p010_30_02.jpg","say":"필요성: 공간이 스스로 판단하고 반응하는 지능형 환경이 되려면 데이터가 끊기지 않고 현장으로 되돌아와 물리적 변화를 만드는 순환 구조(Loop)로 이어져야 함."},{"b":[0.125,0.364,0.786,0.073],"c":[0.0857,0.3132,0.8646,0.1747],"r":6.9991,"img":"img/I2/walk/p010_30_03.jpg","say":"추출 원칙: 1-Loop는 파이프라인 7단계를 인간(거주자) 중심 설계 관점에서 거주자가 체감하는 흐름(감지→전달→판단→실행)만 남기고, 클라우드를 포함한 저장, 경유 인프라 과정은 추상화해 걷어낸 것."},{"b":[0.089,0.467,0.2,0.251],"c":[0.077,0.451,0.224,0.283],"r":1.1194,"img":"img/I2/walk/p010_31_01.jpg","say":"1단계 감지(Sense), 센서의 상태 측정: 센서가 공간의 물리적 변화(온도, 조도, 동작, 문열림 등)를 디지털 데이터로 포착."},{"b":[0.297,0.467,0.2,0.251],"c":[0.285,0.451,0.224,0.283],"r":1.1194,"img":"img/I2/walk/p010_31_02.jpg","say":"2단계 전달(Transmit), 네트워크 신호 전송: 무선망이 수집된 패킷을 허브 및 엣지/클라우드 처리 계층으로 실시간 전송."},{"b":[0.505,0.467,0.201,0.251],"c":[0.493,0.451,0.225,0.283],"r":1.1244,"img":"img/I2/walk/p010_31_03.jpg","say":"3단계 판단(Analyze), 상황 해석 및 결정: 엔진이 데이터를 분석하여 거주자의 맥락을 추론하고 실행 여부를 결정."},{"b":[0.714,0.467,0.201,0.251],"c":[0.702,0.451,0.225,0.283],"r":1.1244,"img":"img/I2/walk/p010_31_04.jpg","say":"4단계 실행(Act), 물리 공간 환경 제어: 액추에이터가 구동하여 조명 점등, 냉난방 가동, 밸브 차단 등 물리 환경을 변경."}]}},{"p":11,"title":"2.1강 CHECKPOINT ①","terms":["Digital Data","Edge Computing","Fog Computing","WPAN","WAN","Transmit","1-Loop","Data Lake","Analyze","Act"],"pass1":[{"kind":"say","lines":["지금까지 배운 것을 문제로 확인하는 쪽이에요.","초록 칸이 답이에요. 답을 손으로 가리고 먼저 떠올려 봐요.","틀려도 괜찮아요. 한 번 더 읽으면 돼요."]}],"pass2":[{"kind":"points","head":"다섯 문제를 쉬운 말로","items":["Q1 센서는 느낀 변화를 무엇으로 바꿀까요? → **디지털 데이터(Digital Data)**, 컴퓨터가 읽는 0과 1의 기록.","Q2 클라우드로 보내기 전 집 가까이서 거르고 모으고 포장하는 층은? → **엣지 컴퓨팅(Edge Computing)** 쪽, 슬라이드 표기로 Edge(Fog Node).","Q3 가까운 무선 길과 먼 인터넷 길을 1-Loop에서 한 이름으로 부르면? → **전달(Transmit)**.","Q4 클라우드에 쌓고 살펴보는 단계는 1-Loop 어디? → 짝 없음.","Q5 예측하고 응답하는 단계는? → **판단(Analyze)**과 **실행(Act)** 두 단계."]},{"kind":"check","q":"**WPAN(근거리 무선망)** 전송과 **WAN(광역 인터넷망)** 전송을 1-Loop에서 함께 부르는 이름은?","choices":["감지","전달","판단","실행"],"a":1,"why":"둘 다 데이터를 옮기는 일이라 **전달(Transmit)**이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"Q2 답을 정확히 읽기","items":["p.7 그림 3단계 박스 이름이 'Edge or Fog Node'였어요.","필터링, 집계, 패키징은 그 박스의 filter, aggregate, package data를 우리말로 옮긴 거예요."]}],"pass4":[{"kind":"check","q":"'Store Data Lake & Inspect' 단계는 1-Loop의 어느 단계에 대응할까?","choices":["감지","전달","판단","대응하는 단계 없음"],"a":3,"why":"**데이터 레이크(Data Lake)** 저장과 검사는 경유, 저장 인프라 과정이라 체감 순환에서 빠져요."},{"kind":"check","q":"클라우드로 보내기 전 로컬에서 필터링, 집계, 패키징을 하는 계층은?","choices":["Dashboard","Edge (Fog Node)","WAN","Analytics Service"],"a":1,"why":"p.7 그림 3단계 'Edge or Fog Node'예요. **포그 컴퓨팅(Fog Computing)**도 같은 자리를 가리켜요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.2815,0.0632],"c":[0.0682,0.1096,0.3097,0.0952],"r":4.6007,"img":"img/I2/walk/p011_h.jpg"},"parts":[{"b":[0.089,0.2,0.825,0.113],"c":[0.0477,0.1648,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p011_30_01.jpg","say":"Q1 센서가 공간의 물리적 변화(온도, 조도, 동작 등)를 측정해 무엇으로 변환하는가? → 디지털 데이터."},{"b":[0.089,0.316,0.825,0.114],"c":[0.0477,0.2813,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p011_30_02.jpg","say":"Q2 클라우드로 보내기 전 로컬에서 필터링, 집계, 패키징을 수행하는 계층은? → Edge (Fog Node)."},{"b":[0.089,0.433,0.825,0.114],"c":[0.0477,0.3983,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p011_30_03.jpg","say":"Q3 근거리 전송(WPAN)과 광역 전송(WAN)을 1-Loop에서는 공통으로 무엇이라 부르는가? → 전달(Transmit)."},{"b":[0.089,0.551,0.825,0.113],"c":[0.0477,0.5158,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p011_30_04.jpg","say":"Q4 'Store Data Lake & Inspect' 단계는 1-Loop 중 어느 단계에 대응하는가? → 대응하는 단계 없음. 저장, 경유 인프라 과정이라 체감 순환에서 제외."},{"b":[0.089,0.667,0.825,0.114],"c":[0.0477,0.6323,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p011_30_05.jpg","say":"Q5 'Predict & Respond' 단계는 1-Loop의 어느 두 단계에 대응하는가? → 판단(Analyze) + 실행(Act)."}]}},{"p":12,"title":"2.1강 CHECKPOINT ②","terms":["Act","Dashboard","Response Back To Edge","Actuator","Human-Centered Design","IoT Data Pipeline","1-Loop","Sense","Transmit","Analyze","Backend Infrastructure"],"pass1":[{"kind":"say","lines":["확인 문제 뒷부분이에요.","알림 화면, 되돌아오는 길, 네 단계, 저장이 빠지는 이유를 물어요.","앞 쪽에서 본 몸의 한 바퀴를 떠올리면 다 풀려요."]}],"pass2":[{"kind":"points","head":"네 문제를 쉬운 말로","items":["Q6 대시보드 알림 단계는? → **실행(Act)**. 사람에게 알려 주는 것도 실제 반응이에요.","Q7 클라우드가 정한 답이 집으로 내려와 손발을 움직이게 하는 길은? → **엣지 환류(Response Back To Edge)**.","Q8 일곱 단계를 사람이 느끼는 것만 남기면? → 네 단계, **감지(Sense)**, **전달(Transmit)**, **판단(Analyze)**, **실행(Act)**.","Q9 저장은 왜 빠질까? → 사람이 느끼지 못하는 **백엔드 인프라 경유 통로(Backend Infrastructure)**이기 때문."]},{"kind":"check","q":"클라우드 분석 결과가 다시 현장으로 내려와 액추에이터를 움직이는 길의 이름은?","choices":["Response Back To Edge","Data Lake","Transmit Data","Alert"],"a":0,"why":"**엣지 환류(Response Back To Edge)**예요. 그림에서 빨간 점선으로 그려졌어요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"Q8의 말 풀이","items":["'추상화'는 자잘한 것을 걷어내고 뼈대만 남긴다는 뜻이에요.","'인간(거주자) 중심 설계'는 **인간중심 설계(Human-Centered Design)**예요. 사는 사람이 느끼는 것을 기준으로 삼아요."]}],"pass4":[{"kind":"check","q":"'Alert & Dashboard' 단계는 1-Loop의 어느 단계에 대응할까?","choices":["감지","전달","판단","실행"],"a":3,"why":"대시보드 화면에 보여 주고 알림을 보내는 것도 **실행(Act)**이에요."},{"kind":"english","head":"서술형 답안 (Q9)","en":"저장은 거주자가 체감하지 못하는 경유, 인프라 과정일 뿐 공간을 직접 변화시키는 판단이나 실행이 아니기 때문에 1-Loop에 별도 저장 단계가 없다.","ko":"p.8 '이해의 공식'과 같은 내용이에요. '체감 못 함'과 '공간을 직접 바꾸지 않음' 두 가지를 꼭 넣어요.","tip":"'안 보이고, 안 바꾼다' 두 마디로 떠올려요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.2815,0.0632],"c":[0.0682,0.1096,0.3097,0.0952],"r":4.6007,"img":"img/I2/walk/p012_h.jpg"},"parts":[{"b":[0.089,0.2,0.825,0.113],"c":[0.0477,0.1648,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p012_30_01.jpg","say":"Q6 'Alert & Dashboard' 단계는 1-Loop의 어느 단계에 대응하는가? → 실행(Act)."},{"b":[0.089,0.316,0.825,0.114],"c":[0.0477,0.2813,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p012_30_02.jpg","say":"Q7 클라우드 분석 결과가 다시 현장(Edge)으로 내려와 액추에이터를 구동시키는 환류 경로의 명칭은? → Response Back To Edge(엣지 환류)."},{"b":[0.089,0.433,0.825,0.146],"c":[0.0477,0.4143,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p012_30_03.jpg","say":"Q8 인간(거주자) 중심 설계 원칙에 따라 7단계를 거주자 체감 기준으로 추상화하면 1-Loop는 몇 단계이며 무엇인가? → 4단계, 감지, 전달, 판단, 실행."},{"b":[0.089,0.583,0.825,0.147],"c":[0.0477,0.5648,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p012_30_04.jpg","say":"Q9 참조모델엔 저장이 두 번(로컬 필터링, 클라우드 저장) 나오는데 1-Loop엔 '저장' 단계가 없는 이유는? → 저장은 거주자가 체감하지 못하는 경유, 인프라 과정일 뿐, 공간을 직접 변화시키는 판단, 실행이 아니기 때문."}]}},{"p":13,"title":"2.2 AIoT 공간 데이터의 3대 유형과 공간적 의미 (목차)","terms":["AIoT","Digital Data","State Data","Event Data","Time-series Data","Feedback Control","Trigger-Action","Routine"],"pass1":[{"kind":"say","lines":["둘째 묶음은 집에서 나오는 데이터를 종류별로 나눠 보는 시간이에요.","지금 몇 도인지 계속 알려 주는 것, 문이 열린 순간 한 번 알리는 것, 날마다 쌓이는 기록이 있어요.","이 세 가지를 잘 섞어야 집이 헛갈리지 않고 알맞게 움직여요."]}],"pass2":[{"kind":"points","head":"일곱 소절을 한 줄씩","items":["2.2.1 데이터란 무엇이고, 어떻게 **디지털 데이터(Digital Data)**로 바뀌는지.","2.2.2 센서가 공간을 표현하는 세 가지 데이터.","2.2.3 **상태 데이터(State Data)**: 계속 이어지는 환경값과 **피드백 제어(Feedback Control)**.","2.2.4 **이벤트 데이터(Event Data)**: 순간의 사건과 자동화를 깨우는 신호.","2.2.5 **시계열 데이터(Time-series Data)**: 시간이 쌓여 드러나는 생활 패턴.","2.2.6 세 데이터를 엮어 **자동화 로직(Trigger-Action)** 만들기.","2.2.7 스마트홈 앱의 **루틴(Routine)** 화면에 짝짓기."]},{"kind":"check","q":"'문이 열린 순간 딱 한 번 알리는 데이터'는 어느 소절에서 다룰까?","choices":["2.2.3 상태 데이터","2.2.4 이벤트 데이터","2.2.5 시계열 데이터","2.2.7 루틴 화면"],"a":1,"why":"순간의 사건은 **이벤트 데이터(Event Data)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"제목 속 AIoT","items":["**AIoT(인공지능 사물인터넷)**은 사물인터넷(IoT)에 인공지능(AI)을 더한 말이에요.","그래서 '**AIoT(인공지능 사물인터넷)** 공간 데이터'는 AI가 판단 재료로 쓰는 집 안 데이터라는 뜻이에요."]}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.0835,0.2738,0.6062,0.1049],"c":[0.0532,0.2578,0.6668,0.1369],"r":6.8883,"img":"img/I2/walk/p013_h.jpg"},"parts":[{"b":[0.121,0.417,0.371,0.037],"c":[0.1024,0.3805,0.4081,0.11],"r":5.2468,"img":"img/I2/walk/p013_30_01.jpg","say":"2.2.1 스마트홈 데이터의 정의와 디지털 변환의 본질."},{"b":[0.121,0.463,0.404,0.037],"c":[0.1008,0.4265,0.4444,0.11],"r":5.7135,"img":"img/I2/walk/p013_30_02.jpg","say":"2.2.2 센서가 공간을 표현하는 3대 데이터 매핑 체계 개요."},{"b":[0.121,0.508,0.418,0.037],"c":[0.1001,0.4715,0.4598,0.11],"r":5.9115,"img":"img/I2/walk/p013_30_03.jpg","say":"2.2.3 ① 상태 데이터(State), 연속 환경값과 피드백 제어."},{"b":[0.121,0.554,0.436,0.037],"c":[0.0992,0.5175,0.4796,0.11],"r":6.166,"img":"img/I2/walk/p013_30_04.jpg","say":"2.2.4 ② 이벤트 데이터(Event), 순간 사건과 자동화 트리거."},{"b":[0.121,0.599,0.454,0.037],"c":[0.0983,0.5625,0.4994,0.11],"r":6.4206,"img":"img/I2/walk/p013_30_05.jpg","say":"2.2.5 ③ 시계열 데이터(Time-series), 시간 축적과 패턴 추론."},{"b":[0.121,0.644,0.432,0.083],"c":[0.0994,0.628,0.4752,0.115],"r":5.8438,"img":"img/I2/walk/p013_30_06.jpg","say":"2.2.6 자동화 로직(Trigger-Action) 구축을 위한 데이터 결합, 2.2.7 스마트홈 앱 [루틴] 화면과 데이터 매핑 실무."}]}},{"p":14,"title":"2.2.1 [데이터 기초] 스마트홈 데이터의 정의와 디지털 변환의 본질","terms":["Digital Data","Sensor","Analog","Encoding","Packet","IoT Data Pipeline"],"pass1":[{"kind":"say","lines":["방 안의 온도는 뚝뚝 끊기지 않고 부드럽게 오르내려요.","그런데 컴퓨터는 0과 1, 두 가지 숫자만 읽을 줄 알아요.","그래서 **센서(Sensor)**가 느낀 값을 0과 1로 바꿔 적어요. 이 기록이 **디지털 데이터(Digital Data)**예요."]},{"kind":"figure","head":"느낀 값이 데이터가 되기까지","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box b1\" x=\"10\" y=\"70\" width=\"140\" height=\"110\" rx=\"3\"/><text class=\"tb b1\" x=\"80\" y=\"60\" font-size=\"15\" text-anchor=\"middle\">실제 세상<\/text><polyline class=\"e2 b1\" fill=\"none\" points=\"22,140 40,110 58,140 76,110 94,140 112,110 130,140\"/><text class=\"tm b1\" x=\"80\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">끊김 없는 값<\/text><line class=\"e2 b2\" x1=\"152\" y1=\"125\" x2=\"179.0\" y2=\"125.0\"/><polygon class=\"arrow b2\" points=\"188.0,125.0 179.0,120.0 179.0,130.0\"/><rect class=\"n2 b2\" x=\"190\" y=\"70\" width=\"130\" height=\"110\" rx=\"3\"/><text class=\"tb b2\" x=\"255\" y=\"60\" font-size=\"15\" text-anchor=\"middle\">0과 1로 적기<\/text><text class=\"tl b2\" x=\"255\" y=\"120\" font-size=\"18\" text-anchor=\"middle\">0 1 1 0<\/text><text class=\"tl b2\" x=\"255\" y=\"146\" font-size=\"18\" text-anchor=\"middle\">1 0 1 1<\/text><line class=\"e2 b3\" x1=\"322\" y1=\"125\" x2=\"349.0\" y2=\"125.0\"/><polygon class=\"arrow b3\" points=\"358.0,125.0 349.0,120.0 349.0,130.0\"/><rect class=\"n3 b3\" x=\"360\" y=\"95\" width=\"110\" height=\"60\" rx=\"3\"/><text class=\"tb b3\" x=\"415\" y=\"60\" font-size=\"15\" text-anchor=\"middle\">길에 올리기<\/text><text class=\"tl b3\" x=\"415\" y=\"130\" font-size=\"15\" text-anchor=\"middle\">파이프라인<\/text><text class=\"t b3\" x=\"240\" y=\"225\" font-size=\"15\" text-anchor=\"middle\">느낀 값 → 컴퓨터가 읽는 숫자 → 데이터 길<\/text><\/svg>","caption":"부드러운 실제 값을 0과 1로 적고, 그 기록을 데이터 길에 올려 보내요.","builds":3},{"kind":"say","lines":["공간을 기획하는 사람은 기기를 어디에 둘지만 정하면 끝이 아니에요.","그 데이터가 얼마나 자주 생기고 어디로 흘러가는지까지 그려 봐야 해요."]}],"pass2":[{"kind":"steps","head":"변환의 세 단계","steps":["물리량 포착: 온도, 빛, 움직임 같은 실제 값을 잡아요. 끊김 없이 이어지는 실제 세상의 값을 **아날로그(Analog)**라고 해요.","디지털 패킷화: 잡은 값을 0과 1로 바꿔 적고 작은 상자에 담아요. 0과 1로 바꿔 적는 일을 **부호화(Encoding)**라고 해요. 작은 상자는 **패킷(Packet)**이에요.","파이프라인 진입: 그 상자가 **IoT 데이터 파이프라인(IoT Data Pipeline)**에 올라 흘러가기 시작해요."],"answer":"포착(아날로그) → 패킷화(부호화) → 파이프라인 진입."},{"kind":"points","head":"데이터의 정의를 쉬운 말로","items":["데이터는 공간의 변화(온도, 빛, 움직임)를 **센서(Sensor)**가 재서,","시스템이 읽을 수 있는 0과 1의 신호로 바꾼 기록이에요.","그러니 **디지털 데이터(Digital Data)**는 '컴퓨터가 읽을 수 있게 바꿔 적은 공간의 일기'라고 생각하면 돼요."]},{"kind":"check","q":"**아날로그(Analog)**에 대한 설명으로 알맞은 것은?","choices":["0과 1로만 된 값","끊김 없이 부드럽게 이어지는 실제 세상의 값","데이터를 담는 작은 상자","클라우드의 큰 창고"],"a":1,"why":"실제 온도나 빛처럼 끊김 없이 이어지는 값이 **아날로그(Analog)**예요. 이걸 0과 1로 바꾸는 게 **부호화(Encoding)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"괄호 속 말까지 정확히","items":["물리량 포착 옆 괄호는 **아날로그**, 디지털 패킷화 옆 괄호는 **부호화**예요.","'어떤 주기로 발생하고'는 다음 쪽들의 보고 주기, 순간 사건, 누적 기록으로 이어져요.","'어디로 흐르는지'는 2.1강 파이프라인 이야기와 연결돼요."]},{"kind":"bg","src":"기초 다지기 2단원 (신호와 숫자)","lines":["0과 1 한 자리를 비트라고 해요. 비트가 여럿 모이면 더 큰 숫자나 글자를 나타낼 수 있어요.","켜짐은 1, 꺼짐은 0처럼, 스위치 두 상태로 세상의 값을 적는다고 생각하면 쉬워요."]}],"pass4":[{"kind":"check","q":"스마트홈 데이터 변환의 세 단계를 순서대로 바르게 나열한 것은?","choices":["디지털 패킷화 → 물리량 포착 → 파이프라인 진입","물리량 포착(아날로그) → 디지털 패킷화(부호화) → 파이프라인 진입","파이프라인 진입 → 물리량 포착 → 디지털 패킷화","물리량 포착 → 파이프라인 진입 → 디지털 패킷화"],"a":1,"why":"먼저 잡고, 0과 1로 적어 담고, 길에 올려요."},{"kind":"check","q":"p.11 체크포인트 Q1: 센서가 공간의 물리적 변화를 측정해 변환하는 것은?","choices":["아날로그 신호","디지털 데이터","데이터 레이크","대시보드"],"a":1,"why":"센서는 물리적 변화를 **디지털 데이터(Digital Data)**로 바꿔요."},{"kind":"english","head":"답안 문장으로 외우기","en":"스마트홈 데이터란 물리적 공간의 환경 변화를 센서가 측정하여 시스템이 판독할 수 있는 디지털 신호(0과 1)로 변환한 기록이다.","ko":"'측정한 주체(센서)', '바꾼 형태(0과 1)', '결과(기록)' 세 가지가 들어가야 해요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.125,0.6692,0.0687],"c":[0.0488,0.109,0.7362,0.1007],"r":10.3392,"img":"img/I2/walk/p014_h.jpg"},"parts":[{"b":[0.089,0.203,0.825,0.136],"c":[0.0477,0.1793,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p014_30_01.jpg","say":"데이터의 정의: 물리적 공간의 환경 변화(온도, 빛, 움직임 등)를 센서가 측정하여 시스템이 판독할 수 있는 디지털 신호(0과 1)로 변환한 기록."},{"b":[0.089,0.352,0.825,0.104],"c":[0.0477,0.3123,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p014_30_02.jpg","say":"변환의 3단계: 물리량 포착(아날로그) → 디지털 패킷화(부호화) → 파이프라인 진입으로 이어지는 3단계 변환 고리."},{"b":[0.089,0.47,0.825,0.125],"c":[0.0477,0.4408,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p014_30_03.jpg","say":"스마트 공간 기획자의 핵심 역할: 고정된 하드웨어 배치를 넘어, 이 디지털 변수가 어떤 주기로 발생하고 어디로 흐르는지 그 궤적까지 설계할 수 있어야 스마트홈 구현의 주도권을 쥘 수 있어요."}]}},{"p":15,"title":"2.2.2 센서가 공간을 표현하는 3대 데이터 매핑 체계","terms":["State Data","Event Data","Time-series Data","Sensor","1-Loop","Analyze","Feedback Control","Trigger"],"pass1":[{"kind":"say","lines":["집에서 생기는 수많은 일은 성격에 따라 딱 세 종류의 데이터로 나뉘어요.","종류를 알아야 집이 어떤 데이터를 보고 움직일지 정할 수 있어요."]},{"kind":"compare","head":"세 종류를 우리 집 예로","cols":["종류","어떤 모양","우리 집 예"],"rows":[["**상태 데이터(State Data)**","지금 값을 계속 알려 줘요","거실이 지금 몇 도인지"],["**이벤트 데이터(Event Data)**","어떤 순간에 딱 한 번 알려요","현관문이 방금 열림"],["**시계열 데이터(Time-series Data)**","날마다 쌓여서 버릇이 보여요","매일 아침 비슷한 시각에 일어남"]]},{"kind":"say","lines":["셋 중 하나만 보면 집이 헛갈려서 엉뚱하게 움직이기 쉬워요.","그래서 세 가지를 함께 엮어 봐야 해요."]}],"pass2":[{"kind":"points","head":"세 데이터의 뜻","items":["**상태 데이터(State Data)**: 온도, 밝기, 습도처럼 공간이 지금 유지하고 있는 값을 계속 보고해요.","**이벤트 데이터(Event Data)**: 문 열림, 버튼 누름, 물 샘처럼 어느 순간 한 번 생기는 사건 신호예요.","**시계열 데이터(Time-series Data)**: 상태와 이벤트가 시간 순서대로 쌓여서, 사는 사람의 생활 패턴을 짐작하게 하는 큰 기록이에요."]},{"kind":"points","head":"어디로 가는 데이터일까","items":["세 데이터는 모두 **1-Loop(원 루프)**의 **판단(Analyze)** 층으로 전달돼요.","즉 집이 '지금 무엇을 할지' 정하는 재료가 이 세 가지예요.","센서 하나의 값만 믿으면 오작동하기 쉬워서, 셋을 짜임새 있게 엮어야 해요."]},{"kind":"check","q":"'문 열림, 버튼 클릭, 누수 발생처럼 특정 시점에 딱 한 번 발생하는 신호'는?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","디지털 변환"],"a":1,"why":"순간 한 번이면 **이벤트 데이터(Event Data)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"카드 부제 세 개","cols":["유형","부제","키워드"],"rows":[["**상태 데이터(State Data)**","연속적 환경값과 피드백","**피드백 제어(Feedback Control)**"],["**이벤트 데이터(Event Data)**","순간적 사건과 트리거","**트리거(Trigger)**"],["**시계열 데이터(Time-series Data)**","시간 축적과 패턴 추론","생활 패턴"]]},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["시계열 데이터는 따로 생기는 새 종류가 아니라, 상태와 이벤트가 시간 순서로 쌓인 것이에요.","세 데이터가 전달되는 곳은 1-Loop의 '판단' 계층이에요. '실행' 계층이 아니에요."]}],"pass4":[{"kind":"check","q":"현재 온도, 조도, 습도처럼 공간이 실시간으로 유지하고 있는 연속적인 수치값은?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","연계정보"],"a":0,"why":"계속 이어지는 환경값이라 **상태 데이터(State Data)**예요."},{"kind":"check","q":"슬라이드에 따르면 3대 데이터는 1-Loop의 어느 계층으로 전달될까?","choices":["감지","전달","판단","실행"],"a":2,"why":"부제에 '1-Loop 판단 계층으로 전달된다'고 적혀 있어요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.5331,0.0574],"c":[0.0557,0.1096,0.5864,0.0894],"r":9.2763,"img":"img/I2/walk/p015_h.jpg"},"parts":[{"b":[0.089,0.185,0.714,0.035],"c":[0.0533,0.1232,0.7854,0.1587],"r":6.999,"img":"img/I2/walk/p015_30_01.jpg","say":"부제: 공간에서 발생하는 수많은 현상은 성격에 따라 3가지 형태의 데이터 유형으로 분류되어 1-Loop 판단 계층으로 전달돼요."},{"b":[0.089,0.228,0.268,0.216],"c":[0.0756,0.212,0.2948,0.248],"r":1.6811,"img":"img/I2/walk/p015_30_02.jpg","say":"① 상태 데이터(State), 연속적 환경값과 피드백: 현재 온도, 조도, 습도 등 공간이 실시간으로 유지하고 있는 연속적인 수치값."},{"b":[0.366,0.228,0.269,0.216],"c":[0.3525,0.212,0.2959,0.248],"r":1.6874,"img":"img/I2/walk/p015_30_03.jpg","say":"② 이벤트 데이터(Event), 순간적 사건과 트리거: 문 열림, 버튼 클릭, 누수 발생 등 특정 시점에 딱 한 번 발생하는 단발성 사건 신호."},{"b":[0.644,0.228,0.27,0.216],"c":[0.6305,0.212,0.297,0.248],"r":1.6937,"img":"img/I2/walk/p015_30_04.jpg","say":"③ 시계열 데이터(Time-series), 시간 축적과 패턴 추론: 상태와 이벤트가 시간 순서대로 누적되어 거주자의 생활 패턴을 유추하는 대규모 데이터."},{"b":[0.089,0.457,0.825,0.094],"c":[0.0477,0.4123,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p015_30_05.jpg","say":"자동화 로직과의 연계: 단일 센서의 오작동을 막고 정교한 지능형 공간을 구축하려면 이 3가지 데이터 유형을 유기적으로 결합해야 해요."}]}},{"p":16,"title":"2.2.3 ① 상태 데이터 (State Data): 연속 환경값과 피드백 제어","terms":["State Data","Feedback Control","Reporting Interval","Sensor","Event Data"],"pass1":[{"kind":"say","lines":["거실 온도계를 떠올려 봐요. 숫자가 조금씩 바뀌면서 늘 그 자리에 떠 있어요.","이렇게 '지금 값'을 쉬지 않고 알려 주는 데이터를 **상태 데이터(State Data)**라고 해요."]},{"kind":"analogy","head":"피부가 계속 알려 주니까 알맞게 조절해요","scene":"목욕물에 손을 담가 두면 피부가 '아직 차갑네', '이제 좋네' 하고 계속 알려 줘요. 그 느낌대로 뜨거운 물을 줄이다가 알맞으면 멈추죠. 집도 **센서(Sensor)**가 알려 주는 대로 보일러가 세기를 맞춰요.","map":[["계속 온도를 알려 주는 피부","**센서(Sensor)**가 보내는 **상태 데이터(State Data)**"],["뜨거운 물을 줄였다 늘렸다","보일러나 에어컨의 출력 조절"],["알맞을 때 멈춤","목표 온도에 닿으면 멈추는 **피드백 제어(Feedback Control)**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 말 풀이","items":["**상태 데이터(State Data)**: 지금 이 순간의 환경 상태를 계속 보고하는 데이터예요. 일정한 간격으로 값이 새로 바뀌어요.","**피드백 제어(Feedback Control)**: 결과를 계속 확인하면서 목표에 닿을 때까지 조절하는 방식이에요.","**보고 주기(Reporting Interval)**: 센서가 몇 초, 몇 분마다 소식을 보낼지 정한 간격이에요."]},{"kind":"figure","head":"보일러가 온도를 맞추는 한 바퀴","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"t\" x=\"240\" y=\"40\" font-size=\"15\" text-anchor=\"middle\">목표에 닿을 때까지 확인하며 조절해요<\/text><rect class=\"n b1\" x=\"10\" y=\"100\" width=\"110\" height=\"50\" rx=\"3\"/><text class=\"tl b1\" x=\"65\" y=\"131\" font-size=\"15\" text-anchor=\"middle\">목표 온도<\/text><line class=\"e2 b1\" x1=\"120\" y1=\"125\" x2=\"149.0\" y2=\"125.0\"/><polygon class=\"arrow b1\" points=\"158.0,125.0 149.0,120.0 149.0,130.0\"/><rect class=\"n2 b1\" x=\"160\" y=\"100\" width=\"110\" height=\"50\" rx=\"3\"/><text class=\"tl b1\" x=\"215\" y=\"131\" font-size=\"15\" text-anchor=\"middle\">보일러 출력<\/text><line class=\"e2 b1\" x1=\"270\" y1=\"125\" x2=\"299.0\" y2=\"125.0\"/><polygon class=\"arrow b1\" points=\"308.0,125.0 299.0,120.0 299.0,130.0\"/><rect class=\"n3 b1\" x=\"310\" y=\"100\" width=\"110\" height=\"50\" rx=\"3\"/><text class=\"tl b1\" x=\"365\" y=\"131\" font-size=\"15\" text-anchor=\"middle\">방 온도<\/text><line class=\"e b2\" x1=\"365\" y1=\"150\" x2=\"365\" y2=\"212\"/><line class=\"e2 b2\" x1=\"365\" y1=\"212\" x2=\"301.0\" y2=\"212.0\"/><polygon class=\"arrow b2\" points=\"292.0,212.0 301.0,217.0 301.0,207.0\"/><rect class=\"n b2\" x=\"170\" y=\"190\" width=\"120\" height=\"44\" rx=\"3\"/><text class=\"tl b2\" x=\"230\" y=\"217\" font-size=\"15\" text-anchor=\"middle\">온도 센서<\/text><line class=\"e b2\" x1=\"170\" y1=\"212\" x2=\"65\" y2=\"212\"/><line class=\"e2 b2\" x1=\"65\" y1=\"212\" x2=\"65.0\" y2=\"161.0\"/><polygon class=\"arrow b2\" points=\"65.0,152.0 60.0,161.0 70.0,161.0\"/><text class=\"tm b2\" x=\"118\" y=\"200\" font-size=\"14\" text-anchor=\"middle\">비교해요<\/text><\/svg>","caption":"목표 온도에 맞춰 출력을 내고, 센서가 잰 방 온도와 비교해 다시 조절해요.","builds":2},{"kind":"check","q":"**상태 데이터(State Data)**를 너무 짧은 간격으로 자꾸 보내면 생기는 문제는?","choices":["센서가 온도를 못 잰다","네트워크에 부담이 커진다","데이터가 이벤트로 바뀐다","보일러가 꺼진다"],"a":1,"why":"너무 자주 보내면 길이 막혀요. 그래서 공간에 맞는 **보고 주기(Reporting Interval)**를 정해야 해요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"숫자 챙기기","items":["정의 속 예: 거실 온도 **22.5°C**, 조명 밝기 **80%**.","예시 카드: 거실 온도 센서 **32.9°C**.","'범위 값을 가진다'는 켜짐, 꺼짐 두 가지가 아니라 22.4, 22.5, 22.6처럼 이어지는 값이라는 뜻이에요."]},{"kind":"compare","head":"상태 데이터 한 장 정리","cols":["항목","내용"],"rows":[["부제","연속 환경값과 피드백 제어"],["특징","주기적으로 값이 갱신되고 범위 값을 가짐"],["쓰임","냉난방, 환기 등 **피드백 제어(Feedback Control)**의 기준값"],["적용 루틴","항온, 항습 및 조도 유지 루틴"],["설계 포인트","공간 특성에 맞는 **보고 주기(Reporting Interval)** 설정"]]}],"pass4":[{"kind":"check","q":"상태 데이터에 대한 설명으로 옳지 않은 것은?","choices":["현재 시점의 환경적 상태를 지속적으로 보고한다","주기적으로 값이 갱신되며 범위 값을 가진다","냉난방, 환기 등 피드백 제어의 기준값으로 쓴다","짧은 주기로 자주 보낼수록 네트워크에 무조건 좋다"],"a":3,"why":"너무 짧은 주기는 네트워크 부하를 줘요. 알맞은 **보고 주기(Reporting Interval)**가 필요해요."},{"kind":"check","q":"'보일러가 목표 온도에 닿을 때까지 출력을 조절한다'는 어떤 데이터를 바탕으로 한 제어일까?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","식별 데이터"],"a":0,"why":"온도 센서가 계속 보내는 **상태 데이터(State Data)**로 **피드백 제어(Feedback Control)**를 해요."},{"kind":"english","head":"답안 문장으로 외우기","en":"상태 데이터는 현재 시점의 환경적 상태를 지속적으로 보고하는 데이터로, 냉난방과 환기 같은 피드백 제어의 기준값이 되며 적절한 보고 주기 설정이 필요하다.","ko":"정의, 쓰임, 설계 포인트를 한 문장에 담았어요.","tip":"'계속, 기준값, 주기' 세 단어를 먼저 떠올려요."}],"pass5":[{"kind":"steps","head":"실기 연결: 온도로 에어컨 자동화 구상하기 (실기 가이드북 2권 1-1 #5 구축 및 자동화)","steps":["실습 문장: 실내 온도가 28도 이상이면 에어컨을 켜고, 22도가 되면 송풍으로 바꾸고, 송풍이 1시간 넘게 이어지면 멈춰요.","가이드북 설명: 한 자동화에 동작을 줄줄이 넣으면 앱에서 실행이 안 된다는 오류가 날 수 있어요.","해결: 시작조건을 나눠 자동화를 따로 만들어요. ① 온도 센서가 28도 이상일 때 → 에어컨 작동.","② 온도가 22도 이하일 때 → 에어컨이 작동 중이면(선택적 요소) → 송풍 모드 전환.","③ 송풍 모드이고 온도가 22도 이하일 때 → 1시간 후(선택적 요소) → 꺼짐."],"answer":"온도라는 **상태 데이터(State Data)** 값을 기준으로 시작조건을 하나씩 나눠야 앱 자동화가 제대로 돌아가요."}],"walk":{"head":{"b":[0.0823,0.1256,0.6735,0.0678],"c":[0.0486,0.1096,0.7408,0.0998],"r":10.4976,"img":"img/I2/walk/p016_h.jpg"},"parts":[{"b":[0.089,0.196,0.407,0.385],"c":[0.0686,0.1768,0.4477,0.4235],"r":1.495,"img":"img/I2/walk/p016_30_01.jpg","say":"실시간 값의 연속적 유지: 거실 온도 22.5°C, 조명 밝기 80%처럼 현재 환경 상태를 지속적으로 보고하는 데이터. 주기적으로 갱신되고 범위 값을 가지며, 냉난방, 환기 피드백 제어의 기준값이에요."},{"b":[0.507,0.196,0.407,0.2],"c":[0.4867,0.18,0.4477,0.232],"r":2.7291,"img":"img/I2/walk/p016_30_02.jpg","say":"공간 자동화 적용 예시, 항온, 항습 및 조도 유지 루틴: 온도 센서가 전하는 상태 데이터를 바탕으로 보일러나 시스템 에어컨이 목표 온도에 도달할 때까지 출력을 조절하는 피드백 제어."},{"b":[0.524,0.399,0.373,0.161],"c":[0.5053,0.383,0.4103,0.193],"r":3.0065,"img":"img/I2/walk/p016_30_03.jpg","say":"설계 포인트: 상태 데이터는 너무 짧은 주기로 전송하면 네트워크 부하를 주므로 공간 특성에 맞는 적절한 보고 주기 설정이 필요해요."},{"b":[0.304,0.592,0.396,0.254],"c":[0.2842,0.576,0.4356,0.286],"r":2.154,"img":"img/I2/walk/p016_30_04.jpg","say":"예시 카드: 거실 온도 센서, 상태 데이터 예시 32.9°C. '일정 주기로 계속 갱신되는 연속 값'."}]}},{"p":17,"title":"2.2.4 ② 이벤트 데이터 (Event Data): 순간 사건과 자동화 트리거","terms":["Event Data","State Data","Trigger","Water Leak Sensor","Home Hub","Latency","Trigger-Action"],"pass1":[{"kind":"say","lines":["현관문이 열리는 건 아주 짧은 순간이에요.","그 순간 '방금 열렸어!' 하고 딱 한 번 보내는 신호를 **이벤트 데이터(Event Data)**라고 해요."]},{"kind":"figure","head":"계속 알리기와 한 번 알리기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tb b1\" x=\"40\" y=\"84\" font-size=\"16\" text-anchor=\"middle\">상태<\/text><line class=\"e b1\" x1=\"80\" y1=\"100\" x2=\"460\" y2=\"100\"/><polyline class=\"e2 b1\" fill=\"none\" points=\"90,80 150,77 210,82 270,78 330,81 390,76 450,79\"/><circle class=\"n b1\" cx=\"90\" cy=\"80\" r=\"4\"/><circle class=\"n b1\" cx=\"150\" cy=\"77\" r=\"4\"/><circle class=\"n b1\" cx=\"210\" cy=\"82\" r=\"4\"/><circle class=\"n b1\" cx=\"270\" cy=\"78\" r=\"4\"/><circle class=\"n b1\" cx=\"330\" cy=\"81\" r=\"4\"/><circle class=\"n b1\" cx=\"390\" cy=\"76\" r=\"4\"/><circle class=\"n b1\" cx=\"450\" cy=\"79\" r=\"4\"/><text class=\"tm b1\" x=\"270\" y=\"55\" font-size=\"14\" text-anchor=\"middle\">지금 값을 계속 알려 줘요<\/text><text class=\"tb b2\" x=\"40\" y=\"214\" font-size=\"16\" text-anchor=\"middle\">이벤트<\/text><line class=\"e b2\" x1=\"80\" y1=\"230\" x2=\"460\" y2=\"230\"/><line class=\"e2 b2\" x1=\"280\" y1=\"230\" x2=\"280\" y2=\"172\"/><circle class=\"n2 b2\" cx=\"280\" cy=\"168\" r=\"7\"/><text class=\"t b2\" x=\"280\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">문이 열린 순간 딱 한 번<\/text><text class=\"tm b2\" x=\"430\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">시간 →<\/text><\/svg>","caption":"위는 늘 값을 보내는 상태 데이터, 아래는 사건이 생긴 순간에만 보내는 이벤트 데이터예요.","builds":2},{"kind":"analogy","head":"반장이 '선생님 오신다!' 외치는 순간","scene":"쉬는 시간에 떠들던 반이 반장의 '선생님 오신다!' 한마디에 순식간에 제자리로 돌아가요. 반장은 하루 종일 떠들지 않고, 딱 그 순간 한 번만 외치죠. 집에서는 문이 열리거나 물이 새는 순간의 신호가 반장의 외침처럼 자동화를 깨워요.","map":[["딱 한 번 외치는 소리","**이벤트 데이터(Event Data)**"],["자리로 돌아가게 만드는 한마디","자동화를 시작시키는 **트리거(Trigger)**"],["외침을 바로 듣는 반장 자리","신호를 바로 받는 집 안 **홈 허브(Home Hub)**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 말 풀이","items":["**이벤트 데이터(Event Data)**: 어떤 행동이나 사고가 벌어지는 순간에만 한 번 보내는 짧은 신호예요. 켜짐/꺼짐, 참/거짓 둘 중 하나로 와요.","**트리거(Trigger)**: 자동화를 '땅!' 하고 시작시키는 신호예요.","**누수 센서(Water Leak Sensor)**: 바닥에 물이 새면 알려 주는 센서예요."]},{"kind":"compare","head":"같은 도어락, 보내는 방식이 기준","cols":["보내는 내용","데이터 종류"],"rows":[["'지금 잠겨 있어요'를 계속 알림","**상태 데이터(State Data)**"],["'방금 풀렸어요' 그 순간만 알림","**이벤트 데이터(Event Data)**"]]},{"kind":"check","q":"같은 도어락이 '방금 해제된 순간'만 알린다면 어떤 데이터일까?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","피드백 제어"],"a":1,"why":"기기 종류가 아니라 보내는 방식이 기준이에요. 순간만 알리면 **이벤트 데이터(Event Data)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"괄호 속 영어 읽기","items":["ON/OFF는 켜짐/꺼짐, True/False는 참/거짓이에요. 둘 중 하나만 오는 신호라는 뜻이에요.","'단발성 패킷'은 한 번 쏘고 끝나는 작은 데이터 상자예요.","로컬 허브 직결: 멀리 클라우드를 거치지 않고 집 안 **홈 허브(Home Hub)**에 바로 붙어야 **지연 시간(Latency)**이 없어요. 집 가까이서 바로 처리하는 **엣지 컴퓨팅(Edge Computing)**과 같은 생각이에요."]},{"kind":"steps","head":"누수 루틴이 도는 순서","steps":["**누수 센서(Water Leak Sensor)**가 욕실 앞 바닥의 물을 감지해요.","**이벤트 데이터(Event Data)**가 집 안 **홈 허브(Home Hub)**로 바로 가요.","시스템이 즉시 메인 급수 밸브를 차단해요.","스마트폰으로 경보를 울려요."],"answer":"사건 → **트리거(Trigger)** → 즉시 반응. 기다리면 안 되니 로컬 허브 직결이에요."}],"pass4":[{"kind":"check","q":"이벤트 데이터에 관한 설명으로 옳지 않은 것은?","choices":["순간적으로 송출되는 단발성 패킷(ON/OFF, True/False)이다","자동화 로직을 즉시 깨우는 트리거 역할을 한다","지연 시간이 없어야 하므로 로컬 허브 직결 통신이 필수이다","주기적으로 값이 갱신되며 범위 값을 가진다"],"a":3,"why":"주기적 갱신과 범위 값은 **상태 데이터(State Data)**의 특징이에요."},{"kind":"check","q":"'재실센서가 사람을 감지하면 조명을 켠다'에서 트리거에 해당하는 것은?","choices":["조명","조명을 켠다","사람 감지","재실센서의 전원"],"a":2,"why":"용어해설집 72번: 사람 감지가 **트리거(Trigger)**이고, 조명 켜기는 실행 동작이에요. 트리거는 조건일 뿐 실행 동작과 분리돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["도어락은 늘 이벤트 데이터가 아니에요. '현재 잠김 여부'를 계속 보내면 **상태 데이터(State Data)**예요.","이벤트 데이터의 설계 포인트는 '로컬 허브 직결'이고, 시계열 데이터의 설계 포인트는 '클라우드 중앙 연산'이에요. 서로 바꿔 낸 보기에 주의해요."]}],"pass5":[{"kind":"steps","head":"실기 연결: 자동화 3단계로 나누기 (실기 가이드북 2권 1-1 #5 구축 및 자동화)","steps":["문제: '어두울 때 모션센서가 감지되면 불을 켜고, 동작이 감지되지 않으면 30초 뒤 불을 꺼라'를 구성도로 완성해요.","자동화 3단계는 '트리거 → 조건 → 동작'이에요. 가이드북은 이를 '시작조건 → 조건만족 → 동작'으로도 적어요.","자동화 조건 1: ① 시작조건 모션이 감지될 때, ② 조건만족 어두우면, ③ 동작 불이 켜진다.","자동화 조건 2: ① 시작조건 모션이 감지되지 않을 때, ③ 동작 불이 꺼진다."],"answer":"'모션이 감지될 때'라는 순간 신호가 **이벤트 데이터(Event Data)**이고, 자동화의 **트리거(Trigger)**예요."},{"kind":"check","q":"실기 예제에서 '모션이 감지될 때'는 자동화 3단계 중 무엇일까?","choices":["시작조건(트리거)","조건만족","동작","해당 없음"],"a":0,"why":"순간 사건이 자동화를 시작시키니 시작조건, 즉 **트리거(Trigger)**예요. '어두우면'은 조건만족이에요."}],"walk":{"head":{"b":[0.0823,0.1256,0.7015,0.0678],"c":[0.0472,0.1096,0.7717,0.0998],"r":10.9355,"img":"img/I2/walk/p017_h.jpg"},"parts":[{"b":[0.089,0.196,0.407,0.385],"c":[0.0686,0.1768,0.4477,0.4235],"r":1.495,"img":"img/I2/walk/p017_30_01.jpg","say":"돌발적, 순간적 상태 변화: 사고나 행위가 벌어지는 순간에만 송출되는 단발성 패킷(ON/OFF, True/False). 같은 도어락도 '현재 잠김 여부'를 계속 보내면 상태, '방금 해제된 순간'만 알리면 이벤트예요."},{"b":[0.114,0.432,0.379,0.113],"c":[0.095,0.416,0.4169,0.145],"r":4.0662,"img":"img/I2/walk/p017_30_02.jpg","say":"예: 도어락 해제, 창문 열림, 가스 누출 감지 등. 자동화 로직을 즉시 깨우는 '트리거(Trigger)' 역할 담당."},{"b":[0.507,0.196,0.407,0.2],"c":[0.4867,0.18,0.4477,0.232],"r":2.7291,"img":"img/I2/walk/p017_30_03.jpg","say":"공간 자동화 적용 예시, 안전사고 방지 및 즉각 반응 루틴: 욕실 앞 누수 센서에서 물이 감지되는 이벤트 데이터가 들어오면 시스템은 즉시 메인 급수 밸브를 차단하고 스마트폰 경보를 울려요."},{"b":[0.524,0.399,0.373,0.161],"c":[0.5053,0.383,0.4103,0.193],"r":3.0065,"img":"img/I2/walk/p017_30_04.jpg","say":"설계 포인트: 이벤트 데이터는 지연 시간이 없어야 하므로 무선 신호 도달 거리가 확보된 로컬 허브 직결 통신이 필수예요."},{"b":[0.304,0.592,0.396,0.24],"c":[0.2842,0.576,0.4356,0.272],"r":2.2648,"img":"img/I2/walk/p017_30_05.jpg","say":"예시 카드: 현관 도어락, 이벤트 데이터 예시 '열림 감지'. 발생 순간에 단 한 번만 송출되는 값."}]}},{"p":18,"title":"2.2.5 ③ 시계열 데이터 (Time-series): 시간 누적과 패턴 추론","terms":["Time-series Data","State Data","Event Data","Data Lake","Cloud Computing","Home Hub"],"pass1":[{"kind":"analogy","head":"하루치 일기와 몇 달 치 일기","scene":"일기 한 장만 읽으면 그날 일만 알아요. 몇 달 치 일기를 먼 곳의 큰 도서관에 모아 넘겨 보면 '늘 아침 일곱 시쯤 일어나는구나' 하는 버릇이 보여요. 집 데이터도 쌓여야 버릇이 드러나요.","map":[["한 장짜리 일기","한 시점의 값, 그것만으로는 의미를 알기 어려움"],["몇 달 치 일기 묶음","**시계열 데이터(Time-series Data)**"],["먼 곳의 큰 도서관 서가","클라우드의 **데이터 레이크(Data Lake)**"]]},{"kind":"say","lines":["시간 순서대로 쌓인 기록을 **시계열 데이터(Time-series Data)**라고 해요.","버릇을 알면 집이 사는 사람이 일어나기 전에 미리 방을 데워 둘 수 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 말 풀이","items":["**시계열 데이터(Time-series Data)**: **상태 데이터(State Data)**와 **이벤트 데이터(Event Data)**가 시간 순서대로 수없이 쌓여 변화의 흐름을 그리는 큰 기록이에요.","**데이터 레이크(Data Lake)**: 데이터를 일단 몽땅 담아 두는 큰 호수 같은 저장소예요. 시계열 데이터가 여기 쌓여요.","**클라우드 컴퓨팅(Cloud Computing)**: 집 밖 멀리 있는 아주 큰 컴퓨터예요. 쌓인 데이터를 분석하는 힘이 커요."]},{"kind":"compare","head":"세 데이터의 설계 포인트 한눈에","cols":["데이터","설계 포인트"],"rows":[["**상태 데이터(State Data)**","알맞은 보고 주기"],["**이벤트 데이터(Event Data)**","지연 없이 로컬 허브 직결"],["**시계열 데이터(Time-series Data)**","허브 용량을 넘으니 클라우드 중앙 연산"]]},{"kind":"check","q":"시계열 데이터 분석을 주로 맡는 곳은?","choices":["센서 자체","집 안 허브만","원격 클라우드 서버","현관 도어락"],"a":2,"why":"분석량이 집 안 **홈 허브(Home Hub)** 용량을 넘어서 원격 **클라우드 컴퓨팅(Cloud Computing)**의 중앙 연산이 필요해요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"숫자 챙기기","items":["적용 예시의 기상 시각은 **매일 아침 7시**예요.","예시 카드는 **최근 7일** 기상 시각의 **평균 07:12**예요.","평균은 여러 날 값을 모아야 나오는 숫자라서, 한 시점 값이 아니라 쌓인 값이라는 표시예요."]},{"kind":"points","head":"2.1강과 이어지는 곳","items":["'클라우드 **데이터 레이크(Data Lake)**에 누적'은 p.7 파이프라인 5단계 Store Data Lake와 같은 자리예요.","'원격 클라우드 서버의 중앙 연산'은 p.9 Cloud 쪽 특징 '장기 시계열 분석'과 같은 말이에요."]}],"pass4":[{"kind":"check","q":"시계열 데이터의 설계 포인트로 가장 적절한 것은?","choices":["보고 주기를 최대한 짧게 설정한다","로컬 허브 직결 통신만 사용한다","분석이 로컬 허브 용량을 초과하므로 원격 클라우드 서버의 중앙 연산이 필수이다","단일 시점 값만으로 생활 패턴을 판단한다"],"a":2,"why":"시계열은 단일 시점으로 의미를 알기 어렵고, 분석은 클라우드 몫이에요."},{"kind":"check","q":"p.21 체크포인트 Q3: 시간의 흐름에 따라 상태와 이벤트가 누적되어 생활 패턴과 반복 습관을 유추하게 하는 데이터는?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","식별 데이터"],"a":2,"why":"**시계열 데이터(Time-series Data)**(Time-series Data)예요."},{"kind":"english","head":"답안 문장으로 외우기","en":"시계열 데이터는 상태와 이벤트 데이터가 시간 순서대로 누적된 대용량 기록으로, 클라우드 데이터 레이크에 쌓여 AI 학습의 원천이 되며 분석에는 원격 클라우드 서버의 중앙 연산이 필요하다.","ko":"'누적', '데이터 레이크', '클라우드 중앙 연산' 세 말이 핵심이에요.","tip":"용어해설집 10번의 순환 신경망(RNN)은 '순차적인 흐름을 가진 데이터 처리에 적합한 딥러닝 구조'예요. 시간 순서 데이터와 함께 기억해 둬요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.6727,0.0678],"c":[0.0487,0.1096,0.74,0.0998],"r":10.4863,"img":"img/I2/walk/p018_h.jpg"},"parts":[{"b":[0.089,0.196,0.407,0.385],"c":[0.0686,0.1768,0.4477,0.4235],"r":1.495,"img":"img/I2/walk/p018_30_01.jpg","say":"데이터 정의 및 특징, 시간 축에 따른 대규모 축적: 상태와 이벤트 데이터가 수없이 쌓여 시간의 흐름에 따른 변화 궤적을 그리는 대용량 데이터 기록. 단일 시점에서는 의미를 알기 어렵고, 클라우드 데이터 레이크에 누적되어 인공지능 학습의 원천이 돼요."},{"b":[0.507,0.196,0.407,0.2],"c":[0.4867,0.18,0.4477,0.232],"r":2.7291,"img":"img/I2/walk/p018_30_02.jpg","say":"공간 자동화 적용 예시, 생활 패턴 학습 및 에너지 절감: 거주자가 매일 아침 7시에 기상해 거실 조명을 켜고 커튼을 여는 시계열 데이터를 AI가 분석해, 일어나기 전 미리 실내 온도를 맞춰 놓는 사전 제어."},{"b":[0.524,0.399,0.373,0.161],"c":[0.5053,0.383,0.4103,0.193],"r":3.0065,"img":"img/I2/walk/p018_30_03.jpg","say":"설계 포인트: 시계열 데이터 분석은 로컬 허브의 용량을 초과하므로 2.1강에서 배운 원격 클라우드 서버의 중앙 연산 능력이 필수예요."},{"b":[0.304,0.592,0.396,0.228],"c":[0.2842,0.576,0.4356,0.26],"r":2.3694,"img":"img/I2/walk/p018_30_04.jpg","say":"예시 카드: 최근 7일 기상 시각, 시계열 데이터 예시 '평균 07:12'. 단일 시점이 아닌 누적된 값들의 패턴."}]}},{"p":19,"title":"2.2.6 자동화 로직(Trigger-Action) 구축을 위한 데이터 결합","terms":["Trigger-Action","IF-THEN","State Data","Event Data","Time-series Data","Illuminance Sensor","Trigger"],"pass1":[{"kind":"say","lines":["'어두워지면 무조건 불 켜' 약속 하나만 있는 집을 생각해 봐요.","낮잠 자려고 커튼을 쳤더니 방이 어두워져서 불이 확 켜져요.","센서 하나만 믿으면 이렇게 엉뚱하게 움직여요. 이걸 오작동이라고 해요."]},{"kind":"figure","head":"세 가지를 함께 보면 헛갈리지 않아요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n b1\" x=\"10\" y=\"30\" width=\"170\" height=\"50\" rx=\"3\"/><text class=\"tl b1\" x=\"95\" y=\"61\" font-size=\"14\" text-anchor=\"middle\">문이 방금 열렸어요<\/text><rect class=\"n b1\" x=\"10\" y=\"110\" width=\"170\" height=\"50\" rx=\"3\"/><text class=\"tl b1\" x=\"95\" y=\"141\" font-size=\"14\" text-anchor=\"middle\">거실이 어두워요<\/text><rect class=\"n b1\" x=\"10\" y=\"190\" width=\"170\" height=\"50\" rx=\"3\"/><text class=\"tl b1\" x=\"95\" y=\"221\" font-size=\"14\" text-anchor=\"middle\">늘 퇴근하는 시간이에요<\/text><line class=\"e2 b2\" x1=\"180\" y1=\"55\" x2=\"222.7\" y2=\"112.8\"/><polygon class=\"arrow b2\" points=\"228.0,120.0 226.7,109.8 218.6,115.7\"/><line class=\"e2 b2\" x1=\"180\" y1=\"135\" x2=\"219.0\" y2=\"135.0\"/><polygon class=\"arrow b2\" points=\"228.0,135.0 219.0,130.0 219.0,140.0\"/><line class=\"e2 b2\" x1=\"180\" y1=\"215\" x2=\"222.7\" y2=\"157.2\"/><polygon class=\"arrow b2\" points=\"228.0,150.0 218.6,154.3 226.7,160.2\"/><rect class=\"n2 b2\" x=\"230\" y=\"105\" width=\"90\" height=\"60\" rx=\"3\"/><text class=\"tl b2\" x=\"275\" y=\"131\" font-size=\"15\" text-anchor=\"middle\">셋 다<\/text><text class=\"tl b2\" x=\"275\" y=\"153\" font-size=\"15\" text-anchor=\"middle\">맞으면<\/text><line class=\"e2 b3\" x1=\"320\" y1=\"135\" x2=\"339.0\" y2=\"135.0\"/><polygon class=\"arrow b3\" points=\"348.0,135.0 339.0,130.0 339.0,140.0\"/><rect class=\"n3 b3\" x=\"350\" y=\"105\" width=\"120\" height=\"60\" rx=\"3\"/><text class=\"tl b3\" x=\"410\" y=\"131\" font-size=\"15\" text-anchor=\"middle\">귀가 모드<\/text><text class=\"tl b3\" x=\"410\" y=\"153\" font-size=\"14\" text-anchor=\"middle\">불, 에어컨<\/text><\/svg>","caption":"문이 열렸고, 어둡고, 늘 돌아오는 시간일 때만 귀가 모드가 켜져요.","builds":3},{"kind":"say","lines":["이렇게 '만약 이러면, 그러면 이렇게 해'로 짜 둔 집의 약속을 **자동화 로직(Trigger-Action)**이라고 불러요."]}],"pass2":[{"kind":"steps","head":"자동화 로직을 만드는 세 가지 생각","steps":["단일 조건의 허점: '조도가 어두워지면 무조건 조명 켜기'는 낮에 커튼을 쳐서 어두워져도 작동해요.","데이터 결합의 원리: **이벤트 데이터(Event Data)**(도어락 해제) + **상태 데이터(State Data)**(거실 조도 낮음) + **시계열 데이터(Time-series Data)**(귀가 시간대 패턴)을 함께 엮어요.","공간 기획의 완성: 기획자는 세 데이터가 어떤 **조건문(IF-THEN)**으로 맞물려 돌아가는지까지 기획해요."],"answer":"하나만 보지 말고, 셋을 엮어서 조건문으로 짜요."},{"kind":"points","head":"말 풀이","items":["**자동화 로직(Trigger-Action)**: '이러면 → 저렇게 해' 하고 정한 집의 약속이에요. 영어로 Trigger-Action, 신호와 동작이라는 뜻이에요.","**조건문(IF-THEN)**: '만약 ~면(IF), 그러면 ~해(THEN)'로 쓰는 문장 틀이에요.","**조도 센서(Illuminance Sensor)**: 얼마나 밝은지 재는 센서예요. 거실이 어두운지는 이 센서가 알려 줘요."]},{"kind":"check","q":"'조도가 어두워지면 무조건 조명 켜기' 규칙의 약점은?","choices":["낮에 커튼을 쳐서 어두워져도 켜지는 오작동","조명이 절대 켜지지 않음","센서가 필요 없음","인터넷이 꼭 필요함"],"a":0,"why":"단일 조건은 어두워진 이유를 몰라서 오작동해요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"괄호 속 예시를 데이터 종류와 짝짓기","cols":["슬라이드 괄호","데이터 종류","왜"],"rows":[["도어락 해제","**이벤트 데이터(Event Data)**","그 순간 한 번 생기는 사건"],["거실 조도 낮음","**상태 데이터(State Data)**","지금 밝기 값을 계속 보고"],["귀가 시간대 패턴","**시계열 데이터(Time-series Data)**","여러 날 쌓여야 보이는 버릇"]]},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["제목의 Trigger-Action은 '트리거가 오면 동작한다'는 뜻이에요. 이 과목 용어로는 **자동화 로직(Trigger-Action)**이에요.","'조도 낮음'은 이벤트가 아니라 상태예요. 밝기 값을 계속 재고 있기 때문이에요."]}],"pass4":[{"kind":"check","q":"슬라이드 ② 데이터 결합의 원리에서 '귀가 시간대 패턴'은 어떤 데이터일까?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","식별 데이터"],"a":2,"why":"여러 날 쌓인 패턴이라 **시계열 데이터(Time-series Data)**예요."},{"kind":"english","head":"서술형 답안: 단일 센서 규칙의 한계","en":"단일 조건 규칙은 낮에 커튼을 쳐서 어두워진 경우에도 조명이 켜지는 오작동을 일으키므로, 이벤트, 상태, 시계열 데이터를 결합한 조건문(IF-THEN)으로 자동화 로직을 설계해야 한다.","ko":"문제 상황(오작동) → 해결(세 데이터 결합) → 형식(조건문) 순서로 써요.","tip":"'커튼, 셋, 조건문'으로 떠올려요."},{"kind":"bg","src":"용어해설집 76, 78번","lines":["AUTOMATION RULE(자동화 룰): 특정 조건 발생 시 사전에 정의된 동작을 자동 수행하도록 설정한 제어 규칙이에요.","IF-THEN-ELSE: 조건을 충족하면 동작을 하고, 충족하지 않으면 대안 동작을 하는 제어 로직 구조예요."]}],"pass5":[{"kind":"points","head":"실기 연결: 자동화가 안 될 때 점검 순서 (실기 가이드북 2권 1-1 #5 구축 및 자동화)","items":["가이드북은 앱 자동화의 필수 구성요소를 '시작조건'과 '동작' 두 가지로, 선택적 요소를 '조건만족'으로 나눠요.","셋을 합친 자동화 3단계: 시작조건 → 조건만족 → 동작. '시작조건일 때 조건만족이 되면 동작을 실행해라'라는 문장이에요.","제대로 안 될 때 점검 1: 시작조건은 명확한가?","점검 2: 조건만족과 여러 시작조건의 and/or를 제대로 만족시켰는가?","점검 3: 동작에 이상은 없는가?"]},{"kind":"check","q":"실기 가이드북에서 앱 자동화의 '선택적 요소'로 적은 것은?","choices":["시작조건","조건만족","동작","스마트기기 이름"],"a":1,"why":"필수는 시작조건과 동작, 선택은 조건만족이에요. 슬라이드의 **조건문(IF-THEN)**에서 IF 안의 추가 조건에 해당해요."}],"walk":{"head":{"b":[0.0823,0.125,0.6392,0.0687],"c":[0.0503,0.109,0.7032,0.1007],"r":9.8757,"img":"img/I2/walk/p019_h.jpg"},"parts":[{"b":[0.089,0.197,0.557,0.116],"c":[0.0612,0.181,0.6127,0.148],"r":5.8547,"img":"img/I2/walk/p019_30_01.jpg","say":"큰 제목: 단일 센서 규칙의 한계를 극복하려면... 상태, 이벤트, 시계열 데이터의 융합이 필요하다."},{"b":[0.089,0.325,0.825,0.099],"c":[0.0477,0.2828,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p019_30_02.jpg","say":"① 단일 조건의 허점: '조도가 어두워지면 무조건 조명 켜기' 같은 단순 규칙은 낮에 커튼을 쳐서 어두워졌을 때도 작동하는 오작동을 유발해요."},{"b":[0.089,0.435,0.825,0.13],"c":[0.0477,0.4083,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p019_30_03.jpg","say":"② 데이터 결합의 원리: 이벤트(도어락 해제) + 상태(거실 조도 낮음) + 시계열(귀가 시간대 패턴)을 복합적으로 엮어내야 완벽한 자동화 시나리오가 성립해요."},{"b":[0.089,0.577,0.825,0.13],"c":[0.0477,0.5503,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p019_30_04.jpg","say":"③ 공간 기획의 완성: 스마트 공간 기획자는 단순 기기 배치를 넘어 이 3대 데이터가 어떤 조건문(IF-THEN)으로 맞물려 돌아가는지 기획할 수 있어야 해요."}]}},{"p":20,"title":"2.2.7 스마트홈 앱 [루틴] 화면과 데이터 매핑 실무","terms":["Routine","Event Data","State Data","Time-series Data","Illuminance Sensor","IF-THEN","Trigger-Action","Smart Home"],"pass1":[{"kind":"say","lines":["휴대폰의 **스마트홈(Smart Home)** 앱에는 '이러면 저렇게 해' 약속을 만드는 메뉴가 있어요.","그 메뉴를 **루틴(Routine)**이라고 불러요.","앞 쪽에서 배운 세 가지 데이터가 이 화면에 그대로 들어가요."]},{"kind":"compare","head":"퇴근해서 집에 올 때의 약속","cols":["조건","무엇을 보고 알까"],"rows":[["현관문이 방금 열렸어요","순간 한 번 오는 신호"],["거실이 많이 어두워요","밝기를 계속 재는 값"],["평소 돌아오는 저녁 시간이에요","여러 날 쌓인 버릇"],["셋 다 맞으면","현관과 복도 불을 켜고 거실 에어컨을 틀어요"]]}],"pass2":[{"kind":"points","head":"말 풀이","items":["**루틴(Routine)**: 스마트홈 앱에서 만드는 자동 실행 묶음이에요. 조건(IF)과 실행(THEN)을 넣어요.","**조도 센서(Illuminance Sensor)**: 밝기를 재는 센서예요. 밝기 단위는 룩스(lux)예요.","좋은 자동화는 사는 사람이 앱을 열어 손으로 누르지 않아도 알아서 돌아가요."]},{"kind":"compare","head":"루틴 표를 데이터 종류와 짝짓기","cols":["조건","데이터 종류"],"rows":[["IF ① 도어락이 '열림'으로 바뀔 때","**이벤트 데이터(Event Data)** (순간 사건)"],["IF ② 거실 조도가 10룩스 미만일 때","**상태 데이터(State Data)** (연속 환경값)"],["IF ③ 평균 귀가 시간대 패턴에 맞을 때","**시계열 데이터(Time-series Data)** (누적 패턴)"]]},{"kind":"check","q":"루틴 조건 '거실 조도 센서 값이 10룩스 미만일 때'는 어떤 데이터일까?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","연계정보"],"a":0,"why":"밝기 값을 계속 재는 연속 환경값이라 **상태 데이터(State Data)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"숫자와 이름 챙기기","items":["조도 기준: **10룩스 미만**.","귀가 시간대: **오후 6시~8시**.","실행 이름: **[귀가 모드 실행]**, 현관 및 복도 간접등 점등, 거실 에어컨 가동.","부제: 상용 스마트홈 앱의 자동화 설정 화면은 결국 3대 데이터의 조합이에요."]},{"kind":"warn","head":"표에서 놓치기 쉬운 점","items":["THEN 칸은 조건 셋이 함께 쓰는 한 칸이에요. 조건마다 실행이 따로 있는 게 아니에요.","IF ①은 '열림 상태로 변경될 때'예요. '열려 있을 때'가 아니라 바뀌는 순간이라 이벤트예요."]}],"pass4":[{"kind":"check","q":"강의의 루틴 설정 항목과 데이터 유형 매핑으로 옳지 않은 것은?","choices":["현관 도어락이 '열림' 상태로 변경될 때 → 이벤트 데이터","거실 조도 센서 값이 10룩스 미만일 때 → 상태 데이터","평균 귀가 시간대(오후 6시~8시) 패턴에 부합할 때 → 시계열 데이터","거실 조도 센서 값이 10룩스 미만일 때 → 이벤트 데이터"],"a":3,"why":"조도 값은 연속 환경값이라 **상태 데이터(State Data)**예요."},{"kind":"check","q":"귀가 모드의 실행 액션(THEN)으로 강의에 나온 것은?","choices":["현관 및 복도 간접등 점등, 거실 에어컨 가동","가스 밸브 차단","보일러 끄기","창문 열기"],"a":0,"why":"[귀가 모드 실행] 현관 및 복도 간접등 점등, 거실 에어컨 가동이에요."},{"kind":"bg","src":"용어해설집 52번","lines":["**조도 센서(Illuminance Sensor)**: 주변 밝기(lux)를 측정해 조명 밝기를 자동 조절하는 기준값을 주는 센서예요.","루틴 IF ②의 '10룩스'가 바로 이 단위예요."]}],"pass5":[{"kind":"compare","head":"실기 연결: 모드와 자동화, And와 Or (실기 가이드북 2권 2-2 지능형홈 운용 및 문제해결)","cols":["구분","가이드북 설명"],"rows":[["모드","한 번 클릭해서 내가 원할 때 여러 제품을 한꺼번에 작동(제어)하는 것"],["자동화","내가 설정한 상황과 일치하면 제품이 자동으로 작동(제어)하는 것"],["조건이 하나라도 충족","여러 조건 중 하나만 맞아도 실행 항목이 모두 동작"],["모든 조건이 충족","조건이 전부 맞을 때만 실행 항목이 동작"]]},{"kind":"steps","head":"가이드북의 귀가 시 자동화 예","steps":["상황: 집에 사람이 없으면 5분 뒤 전등을 끄고, 사람이 들어오면 전등을 켜자.","① 시작조건: 모션센서 움직임 없을 때, 도어센서는 열렸을 때.","② 조건만족: 모든 조건이 충족하면.","③ 동작: 모든 전등 켜짐."],"answer":"슬라이드의 귀가 모드도 세 조건이 '모두 충족'일 때 실행되도록 짜야 오작동이 줄어요."},{"kind":"check","q":"슬라이드의 귀가 모드처럼 '문 열림, 어두움, 귀가 시간대'가 전부 맞을 때만 켜지게 하려면 앱에서 무엇을 골라야 할까?","choices":["어떤 조건이든 충족되었을 경우(Or)","모든 조건이 충족되었을 경우(And)","모드","조건 없음"],"a":1,"why":"하나만 맞아도 켜지면 커튼 오작동이 다시 생겨요. 가이드북 표현으로 '모든 조건이 충족'이에요."}],"walk":{"head":{"b":[0.0815,0.125,0.5988,0.0992],"c":[0.0516,0.109,0.6587,0.1312],"r":7.1003,"img":"img/I2/walk/p020_h.jpg"},"parts":[{"b":[0.089,0.232,0.825,0.042],"c":[0.0477,0.1613,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p020_30_01.jpg","say":"열 이름: 구분 / 상용 앱 [루틴] 설정 항목 / 공간 데이터 유형 매핑 / 실행 액션(THEN)."},{"b":[0.089,0.277,0.582,0.077],"c":[0.0599,0.2508,0.6402,0.1293],"r":7.0022,"img":"img/I2/walk/p020_30_02.jpg","say":"조건(IF ①): 현관 도어락이 '열림' 상태로 변경될 때 → 이벤트 데이터(순간 사건)."},{"b":[0.089,0.356,0.582,0.079],"c":[0.0599,0.3308,0.6402,0.1293],"r":7.0022,"img":"img/I2/walk/p020_30_03.jpg","say":"조건(IF ②): 거실 조도 센서 값이 10룩스 미만일 때 → 상태 데이터(연속 환경값)."},{"b":[0.089,0.436,0.582,0.081],"c":[0.0599,0.4118,0.6402,0.1293],"r":7.0022,"img":"img/I2/walk/p020_30_04.jpg","say":"조건(IF ③): 평균 귀가 시간대(오후 6시~8시) 패턴에 부합할 때 → 시계열 데이터(누적 패턴)."},{"b":[0.671,0.277,0.243,0.24],"c":[0.6588,0.261,0.2673,0.272],"r":1.3898,"img":"img/I2/walk/p020_30_05.jpg","say":"실행 액션(THEN): [귀가 모드 실행] 현관 및 복도 간접등 점등, 거실 에어컨 가동. 세 조건이 한 칸의 실행을 함께 가리켜요."},{"b":[0.089,0.528,0.825,0.125],"c":[0.0477,0.4988,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p020_30_06.jpg","say":"실무 설계 인사이트: 좋은 공간 자동화란 거주자가 앱을 열어 수동 조작할 필요 없이, 이 3가지 데이터가 알아서 맞물려 공간의 품격을 높여 주는 설계예요."}]}},{"p":21,"title":"2.2강 CHECKPOINT","terms":["State Data","Event Data","Time-series Data","Trigger","Illuminance Sensor"],"pass1":[{"kind":"say","lines":["둘째 묶음을 문제로 확인하는 쪽이에요.","세 가지 데이터를 구별하는 문제가 대부분이에요.","'계속 알림, 한 번 알림, 쌓인 기록'만 떠올리면 풀려요."]}],"pass2":[{"kind":"points","head":"다섯 문제를 쉬운 말로","items":["Q1 지금 거실 온도를 계속 보고하는 데이터는? → **상태 데이터(State Data)**.","Q2 도어락 해제, 누수처럼 한 번 생겨 자동화를 깨우는 데이터는? → **이벤트 데이터(Event Data)**.","Q3 쌓여서 생활 버릇을 짐작하게 하는 기록은? → **시계열 데이터(Time-series Data)**.","Q4 커튼 때문에 불이 켜지는 오작동을 막으려면? → 이벤트나 시계열 데이터를 함께 엮어요.","Q5 앱의 '거실 온도 27.1°C'와 '도어락 열림 알림'은? → 상태, 이벤트."]},{"kind":"check","q":"앱에 뜬 '현관 도어락 열림 알림'은 어떤 데이터일까?","choices":["상태 데이터","이벤트 데이터","시계열 데이터","피드백 제어"],"a":1,"why":"열린 순간 한 번 온 알림이라 **이벤트 데이터(Event Data)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"숫자 구별","items":["Q1의 **22.5°C**와 Q5의 **27.1°C**는 둘 다 온도라서 **상태 데이터(State Data)**예요.","숫자가 달라도 '지금 값을 계속 보여 준다'는 점이 같아요."]}],"pass4":[{"kind":"english","head":"서술형 답안 (Q4)","en":"이벤트 데이터(도어락 해제 등 실제 귀가 신호)나 시계열 데이터(평소 재실 패턴)를 함께 결합해야 한다. 상태 데이터만으로는 어두워진 원인이 사람이 없어서인지 커튼 때문인지 구분할 수 없기 때문이다.","ko":"무엇을 더할지(이벤트, 시계열)와 왜인지(원인 구분 불가) 두 부분을 다 써야 해요.","tip":"'무엇을, 왜' 두 칸을 채운다고 생각해요."},{"kind":"check","q":"Q4 상황에서 상태 데이터만으로 부족한 이유는?","choices":["조도 센서가 밝기를 잴 수 없어서","어두워진 원인이 커튼 때문인지 사람이 없어서인지 구분할 수 없어서","상태 데이터는 클라우드로만 가서","상태 데이터는 한 번만 보내져서"],"a":1,"why":"**조도 센서(Illuminance Sensor)**는 어둡다는 사실만 알려 줘요. 왜 어두운지는 다른 데이터가 알려 줘야 해요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.2596,0.0632],"c":[0.0693,0.1096,0.2856,0.0952],"r":4.2427,"img":"img/I2/walk/p021_h.jpg"},"parts":[{"b":[0.089,0.2,0.825,0.113],"c":[0.0477,0.1648,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p021_30_01.jpg","say":"Q1 현재 거실 온도가 22.5°C인지와 같이 실시간 환경적 상태를 지속적으로 보고하는 데이터 유형은? → 상태 데이터(State Data)."},{"b":[0.089,0.316,0.825,0.114],"c":[0.0477,0.2813,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p021_30_02.jpg","say":"Q2 도어락 해제나 누수 감지처럼 특정 시점에 단발성으로 발생해 자동화를 즉시 깨우는 트리거 역할의 데이터 유형은? → 이벤트 데이터(Event Data)."},{"b":[0.089,0.433,0.825,0.146],"c":[0.0477,0.4143,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p021_30_03.jpg","say":"Q3 시간의 흐름에 따라 수많은 상태와 이벤트가 누적되어 생활 패턴과 반복 습관을 유추하게 하는 데이터 기록은? → 시계열 데이터(Time-series Data)."},{"b":[0.089,0.583,0.825,0.18],"c":[0.0477,0.567,0.9075,0.212],"r":6.0538,"img":"img/I2/walk/p021_30_04.jpg","say":"Q4 낮에 커튼을 쳐서 어두워졌는데 '조도가 어두우면 조명 켜기' 단일 규칙으로 조명이 켜졌다. → 이벤트(도어락 해제 등 실제 귀가 신호)나 시계열(평소 재실 패턴)을 함께 결합. 상태 데이터만으로는 어두워진 원인을 구분할 수 없기 때문."},{"b":[0.089,0.766,0.825,0.131],"c":[0.0477,0.7398,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p021_30_05.jpg","say":"Q5 앱의 '거실 온도 27.1°C' 표시와 '현관 도어락 열림 알림'은 각각 어떤 유형인가? → 거실 온도 = 상태 데이터, 도어락 알림 = 이벤트 데이터."}]}},{"p":22,"title":"2.3 공간 데이터 가시화와 비식별 센싱 (목차)","terms":["Dashboard","Widget","Clutter","Privacy-by-Design","Personal Information Protection Act","Non-identifying Sensing"],"pass1":[{"kind":"say","lines":["셋째 묶음이에요.","눈에 안 보이는 데이터를 화면으로 보여 주는 법을 먼저 배워요.","그다음, 얼굴을 찍지 않고도 사람이 있는지 알아채서 사생활을 지키는 법을 배워요."]}],"pass2":[{"kind":"points","head":"다섯 소절을 한 줄씩","items":["2.3.1 보이지 않는 데이터 흐름을 한눈에 보여 주는 **대시보드(Dashboard)**.","2.3.2 대시보드에 꼭 필요한 세 가지 **위젯(Widget)**.","2.3.3 보여 줄수록 복잡해지는 역설과 **정보 과부하(Clutter)** 해결.","2.3.4 **Privacy-by-Design(프라이버시 바이 디자인)**과 **개인정보 보호법(Personal Information Protection Act)**.","2.3.5 **비식별 센싱(Non-identifying Sensing)** 기술을 사생활 침해 정도 순으로 늘어놓기."]},{"kind":"check","q":"'처음 설계할 때부터 사생활 보호를 기본으로 넣는 원칙'을 다루는 소절은?","choices":["2.3.1","2.3.2","2.3.3","2.3.4"],"a":3,"why":"2.3.4 **Privacy-by-Design(프라이버시 바이 디자인)**과 개인정보보호 법령이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"'스펙트럼'이라는 말","items":["스펙트럼은 한쪽 끝에서 다른 쪽 끝까지 차례로 늘어놓은 띠예요.","2.3.5에서는 사생활 침해가 큰 센서부터 거의 없는 센서까지 늘어놓아요."]}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.0835,0.3196,0.4954,0.1042],"c":[0.0587,0.3036,0.5449,0.1362],"r":5.658,"img":"img/I2/walk/p022_h.jpg"},"parts":[{"b":[0.121,0.463,0.471,0.037],"c":[0.0974,0.4265,0.5181,0.11],"r":6.661,"img":"img/I2/walk/p022_30_01.jpg","say":"2.3.1 보이지 않는 데이터 흐름의 시각화(대시보드의 정의 및 목적)."},{"b":[0.121,0.508,0.354,0.037],"c":[0.1033,0.4715,0.3894,0.11],"r":5.0064,"img":"img/I2/walk/p022_30_02.jpg","say":"2.3.2 지능형 공간을 지탱하는 3대 필수 위젯 구성."},{"b":[0.121,0.554,0.393,0.037],"c":[0.1013,0.5175,0.4323,0.11],"r":5.5579,"img":"img/I2/walk/p022_30_03.jpg","say":"2.3.3 가시화의 역설과 정보 과부하(Clutter) 함정 극복."},{"b":[0.121,0.599,0.346,0.037],"c":[0.1037,0.5625,0.3806,0.11],"r":4.8932,"img":"img/I2/walk/p022_30_04.jpg","say":"2.3.4 Privacy-by-Design과 개인정보보호 법령."},{"b":[0.121,0.644,0.243,0.037],"c":[0.1089,0.6075,0.2673,0.11],"r":3.4366,"img":"img/I2/walk/p022_30_05.jpg","say":"2.3.5 비식별 센싱 기술 스펙트럼."}]}},{"p":23,"title":"2.3.1 [대시보드 기초] 보이지 않는 데이터 흐름의 시각화","terms":["Dashboard","Real-time Monitoring","Instant Control","Widget","Actuator","State Data","Event Data","Time-series Data"],"pass1":[{"kind":"say","lines":["데이터는 눈에 보이지 않아요. 전선 속이나 공기 중을 조용히 지나가죠.","그래서 우리 집 상태를 한눈에 보고 바로 누를 수 있는 화면이 필요해요.","그 화면이 **대시보드(Dashboard)**예요."]},{"kind":"figure","head":"대시보드가 하는 두 가지 일","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box\" x=\"150\" y=\"10\" width=\"180\" height=\"250\" rx=\"3\"/><rect class=\"n b1\" x=\"165\" y=\"35\" width=\"150\" height=\"95\" rx=\"3\"/><text class=\"tl b1\" x=\"240\" y=\"75\" font-size=\"18\" text-anchor=\"middle\">보기<\/text><text class=\"tl b1\" x=\"240\" y=\"102\" font-size=\"14\" text-anchor=\"middle\">온도, 문 상태<\/text><rect class=\"n2 b2\" x=\"165\" y=\"145\" width=\"150\" height=\"95\" rx=\"3\"/><text class=\"tl b2\" x=\"240\" y=\"185\" font-size=\"18\" text-anchor=\"middle\">누르기<\/text><text class=\"tl b2\" x=\"240\" y=\"212\" font-size=\"14\" text-anchor=\"middle\">조명 켜고 끄기<\/text><text class=\"tb b1\" x=\"400\" y=\"78\" font-size=\"15\" text-anchor=\"middle\">실시간<\/text><text class=\"tb b1\" x=\"400\" y=\"98\" font-size=\"15\" text-anchor=\"middle\">모니터링<\/text><text class=\"tb b2\" x=\"400\" y=\"188\" font-size=\"15\" text-anchor=\"middle\">즉각적<\/text><text class=\"tb b2\" x=\"400\" y=\"208\" font-size=\"15\" text-anchor=\"middle\">제어<\/text><text class=\"tm\" x=\"75\" y=\"140\" font-size=\"14\" text-anchor=\"middle\">휴대폰 앱 화면<\/text><\/svg>","caption":"위는 지금 상태를 보는 곳, 아래는 눌러서 기기를 움직이는 곳이에요.","builds":2}],"pass2":[{"kind":"points","head":"말 풀이","items":["**대시보드(Dashboard)**: 파이프라인으로 흘러 들어온 데이터(상태, 이벤트, 시계열)를 한눈에 보고 조작하게 해 주는 화면이에요.","**실시간 모니터링(Real-time Monitoring)**: 지금 온도, 습도, 기기 상태를 바로바로 보는 기능이에요.","**즉각적 제어(Instant Control)**: 화면을 톡 눌러 **액추에이터(Actuator)**를 바로 움직이는 기능이에요.","**위젯(Widget)**: 대시보드에 붙은 작은 정보 타일이에요. 온도 타일, 조명 버튼 타일 같은 것이에요."]},{"kind":"check","q":"대시보드 화면을 톡 눌러 조명을 바로 켜는 기능은?","choices":["실시간 모니터링","즉각적 제어","시계열 분석","데이터 레이크"],"a":1,"why":"화면 터치로 액추에이터를 움직이는 **즉각적 제어(Instant Control)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"파이프라인과 이어 보기","items":["p.7 그림 맨 끝 Dashboard / Alert가 바로 이 화면이에요.","p.8 표에서 7단계 대시보드는 1-Loop의 실행(Act)에 짝지어졌어요.","화면에 흘러오는 데이터는 **상태 데이터(State Data)**, **이벤트 데이터(Event Data)**, **시계열 데이터(Time-series Data)** 세 가지예요."]}],"pass4":[{"kind":"check","q":"스마트홈 대시보드의 2대 핵심 기능으로 옳은 것은?","choices":["실시간 모니터링, 즉각적 제어","데이터 레이크, 엣지 환류","노이즈 필터링, 패키징","가명화, 암호화"],"a":0,"why":"**실시간 모니터링(Real-time Monitoring)**(온습도, 기기 상태 파악)과 **즉각적 제어(Instant Control)**(화면 터치로 액추에이터 제어)예요."},{"kind":"english","head":"답안 문장으로 외우기","en":"대시보드는 IoT 파이프라인으로 들어오는 보이지 않는 데이터를 거주자가 한눈에 보고 조작하는 화면이며, 실시간 모니터링과 즉각적 제어가 2대 핵심 기능이다.","ko":"정의와 기능 두 가지를 한 번에 써요.","tip":"'보기와 누르기'로 줄여 기억해요."}],"pass5":[{"kind":"steps","head":"실기 연결: 앱 제어가 안 될 때 (실기 가이드북 2권 2-2 지능형홈 운용 및 문제해결)","steps":["상황: 난방 컨트롤러, 환기 컨트롤러, 조명 스위치를 스마트폰으로 제어할 수 없어요.","확인 1: 컨트롤러에서 직접 조작하면 정상으로 제어돼요.","확인 2: Wi-Fi로 연결된 다른 기기는 문제없이 동작해요.","판단: 월패드에서는 제어되니 집 안 문제가 아니라, 홈네트워크사가 제공하는 앱에서 제어가 안 되는 장애예요.","조치: 홈네트워크사 고객센터에 장애를 접수해 해결해요."],"answer":"대시보드(앱)의 **즉각적 제어(Instant Control)**만 안 될 때는 앱을 제공하는 쪽에 장애를 접수해요."}],"walk":{"head":{"b":[0.0823,0.125,0.6558,0.171],"c":[0.0495,0.109,0.7213,0.203],"r":5.025,"img":"img/I2/walk/p023_h.jpg"},"parts":[{"b":[0.246,0.298,0.496,0.081],"c":[0.2212,0.282,0.5456,0.113],"r":6.8284,"img":"img/I2/walk/p023_30_01.jpg","say":"위쪽 대시보드 줄: 기기 5개, 미디어 출력, 28.2°C, 41~61%, 수면 환경, 알아보기, 허브 2개. 오른쪽 위에는 27°C 좋음 날씨 표시가 있어요."},{"b":[0.389,0.306,0.139,0.066],"c":[0.3585,0.284,0.2,0.11],"r":2.5713,"img":"img/I2/walk/p023_30_02.jpg","say":"28.2°C(온도), 41~61%(습도) 타일: 지금 값을 보여 주는 실시간 모니터링이에요."},{"b":[0.246,0.424,0.496,0.109],"c":[0.2212,0.408,0.5456,0.141],"r":5.4724,"img":"img/I2/walk/p023_30_03.jpg","say":"즐겨찾기 줄: 현관 도어락(잠김), 현관 도어벨(움직임 없음), 전체 조명 그룹(켜짐), 전체 다운라이트(켜짐)."},{"b":[0.311,0.533,0.364,0.047],"c":[0.2928,0.5015,0.4004,0.11],"r":5.1478,"img":"img/I2/walk/p023_30_04.jpg","say":"아래 탭: 홈, 기기, 라이프, 자동화, 메뉴."},{"b":[0.089,0.613,0.825,0.17],"c":[0.0477,0.597,0.9075,0.202],"r":6.3535,"img":"img/I2/walk/p023_30_05.jpg","say":"이것이 대시보드입니다: IoT 파이프라인으로 흘러 들어오는 보이지 않는 데이터(상태, 이벤트, 시계열)를 거주자가 한눈에 보고 조작하는 화면. 실시간 모니터링(온습도, 기기 상태 파악)과 즉각적 제어(화면 터치로 액추에이터 제어)가 2대 핵심 기능."}]}},{"p":24,"title":"2.3.2 [대시보드 기능] 지능형 공간을 지탱하는 3대 필수 위젯","terms":["Widget","Dashboard","State Data","Event Data","Act","Real-time Monitoring","Instant Control"],"pass1":[{"kind":"say","lines":["대시보드 속 작은 타일을 **위젯(Widget)**이라고 해요.","위젯은 하는 일에 따라 크게 세 가지로 나뉘어요."]},{"kind":"compare","head":"세 가지 위젯, 쉬운 말로","cols":["위젯","하는 일","앱 화면 예"],"rows":[["지금 상태를 보여 주는 타일","지금 값을 계속 띄워요","거실 온도, 도어락 잠김"],["지난 일을 적어 두는 기록","한 번씩 생긴 일을 쌓아 둬요","'도어락 해제' 알림 기록"],["누르는 버튼 타일","눌러서 기기를 움직여요","전체 조명 켜기, 끄기"]]}],"pass2":[{"kind":"compare","head":"위젯과 데이터 짝짓기","cols":["위젯","데이터 / 1-Loop"],"rows":[["① 상태 모니터링 위젯","**상태 데이터(State Data)**"],["이벤트 로그 위젯","**이벤트 데이터(Event Data)**"],["③ 제어 및 자동화 위젯","**실행(Act)**"]]},{"kind":"points","head":"말 풀이","items":["모니터링은 지켜본다는 뜻이에요. **실시간 모니터링(Real-time Monitoring)**이 상태 모니터링 위젯의 일이에요.","로그는 일지, 기록이라는 뜻이에요. 이벤트 로그는 '사건 기록장'이에요.","제어 위젯은 사람이 직접 끼어들어 **실행(Act)**을 일으켜요. **즉각적 제어(Instant Control)**가 이 위젯의 일이에요."]},{"kind":"check","q":"'전체 조명 그룹' 켜기/끄기 버튼은 어떤 위젯일까?","choices":["상태 모니터링 위젯","이벤트 로그 위젯","제어 및 자동화 위젯","위젯이 아님"],"a":2,"why":"거주자가 직접 눌러 **실행(Act)**을 일으키니 제어 및 자동화 위젯이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'도어락 잠김'은 상태 모니터링 위젯이고, '도어락 해제 알림'은 이벤트 로그 위젯이에요. 같은 도어락이라도 보여 주는 방식이 달라요.","슬라이드 번호가 ①, ③만 보이고 ②는 아래 파란 상자의 이벤트 로그 위젯이에요.","이벤트 기록은 홈 화면이 아니라 각 기기의 기록(History) 탭에서 봐요."]}],"pass4":[{"kind":"check","q":"강의의 3대 필수 위젯 설명으로 옳지 않은 것은?","choices":["상태 모니터링 위젯은 지금 이 순간의 값을 계속 보여 준다","제어 및 자동화 위젯은 거주자가 직접 개입해 실행(Act)을 일으킨다","이벤트 로그 위젯은 각 기기의 기록(History) 탭 등에서 확인할 수 있다","'도어락 잠김' 표시는 이벤트 로그 위젯에 해당한다"],"a":3,"why":"'도어락 잠김'은 현재 상태를 계속 보여 주는 상태 모니터링 위젯이에요."},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 34번","q":"스마트 스위치로 기존 조명기기를 원격 제어하고 자동화할 때, 효과에 대한 설명으로 가장 적절하지 않은 것은?","qko":"스마트 스위치 효과 넷 중 틀린 말을 고르는 문제예요.","solve":["기존 조명을 바꾸지 않고 원격 제어를 더할 수 있어요. 맞는 말이에요.","앱 연동으로 켜고 끄기, 예약 실행, 외출 모드 자동화가 돼요. 맞는 말이에요.","여러 조명을 한꺼번에 끄면 불필요한 전력 사용이 줄어요. 대시보드의 '전체 조명 그룹' 버튼과 같은 효과예요.","그래서 '전력 사용을 줄이는 데 도움이 되지 않는다'가 틀린 말이에요."],"answer":"여러 조명기기를 동시에 제어할 수 있지만 불필요한 전력 사용을 줄이는 데에는 도움이 되지 않는다"}],"pass5":[{"kind":"points","head":"실기 연결: 모드와 제어 위젯 (실기 가이드북 2권 2-2 지능형홈 운용 및 문제해결)","items":["가이드북: 지능형홈 서비스의 꽃은 제대로 된 모드와 자동화예요.","모드: 한 번 클릭으로 내가 원할 때 여러 제품을 한꺼번에 작동(제어)하는 것. 동작에 초점이 있어요.","슬라이드의 '전체 조명 그룹' 버튼처럼 한 번 눌러 여러 조명을 움직이는 게 모드에 가까워요.","자동화: 설정한 상황과 맞으면 알아서 작동하는 것. '~라면 ~해라'처럼 조건과 실행을 지정해요."]},{"kind":"check","q":"실기 가이드북에서 '한 번 클릭해 원할 때 여러 제품을 한꺼번에 작동하는 것'은?","choices":["모드","자동화","트리거","이벤트 로그"],"a":0,"why":"사람이 눌러야 동작하면 모드, 조건이 맞아 알아서 동작하면 자동화예요."}],"walk":{"head":{"b":[0.0823,0.125,0.6558,0.1787],"c":[0.0495,0.109,0.7213,0.2107],"r":4.8414,"img":"img/I2/walk/p024_h.jpg"},"parts":[{"b":[0.389,0.306,0.139,0.066],"c":[0.3585,0.284,0.2,0.11],"r":2.5713,"img":"img/I2/walk/p024_30_01.jpg","say":"28.2°C, 41~61% 타일: 상태 모니터링 위젯의 예."},{"b":[0.246,0.424,0.121,0.109],"c":[0.2065,0.408,0.2,0.141],"r":2.006,"img":"img/I2/walk/p024_30_02.jpg","say":"현관 도어락 '잠김' 타일: 지금 잠겨 있다는 값을 계속 보여 주니 이것도 상태 모니터링 위젯의 예."},{"b":[0.496,0.424,0.246,0.109],"c":[0.4837,0.408,0.2706,0.141],"r":2.7141,"img":"img/I2/walk/p024_30_03.jpg","say":"전체 조명 그룹, 전체 다운라이트 전원 버튼: 제어 및 자동화 위젯의 예."},{"b":[0.089,0.613,0.407,0.126],"c":[0.0686,0.597,0.4477,0.158],"r":4.0073,"img":"img/I2/walk/p024_30_04.jpg","say":"① 상태 모니터링 위젯: '28.2°C', '41~61%', '도어락 잠김' 등 지금 이 순간의 값을 계속 보여 주는 상태 데이터 위젯."},{"b":[0.507,0.613,0.407,0.126],"c":[0.4867,0.597,0.4477,0.158],"r":4.0073,"img":"img/I2/walk/p024_30_05.jpg","say":"③ 제어 및 자동화 위젯: '전체 조명 그룹' 켜기/끄기 버튼처럼 거주자가 직접 개입해 실행(Act)을 일으키는 위젯."},{"b":[0.089,0.747,0.825,0.121],"c":[0.0477,0.7158,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p024_30_06.jpg","say":"2.2강 소환, 이벤트 로그 위젯은?: 홈 화면엔 안 보이지만 '도어락 해제 알림'처럼 단발성 사건이 쌓이는 이벤트 데이터 위젯은 각 기기의 기록(History) 탭 등에서 확인 가능."}]}},{"p":25,"title":"2.3.3 [한계와 과제] 가시화의 역설과 직관적 인터페이스","terms":["Clutter","Context-based UI","Privacy","AI@Home","Dashboard","Widget"],"pass1":[{"kind":"say","lines":["집에 기기가 몇 개 없을 땐 화면이 깔끔해요.","그런데 기기가 수십 개로 늘어 아이콘을 전부 늘어놓으면 뭘 눌러야 할지 몰라 오히려 피곤해져요.","보여 주려고 만든 화면이 오히려 불편해지는 거예요."]},{"kind":"points","head":"그래서 이렇게 해요","items":["평소에는 꼭 필요한 것만 보여 줘요.","밤이나 집을 비웠을 때처럼 필요한 순간에만 해당 버튼을 꺼내 줘요.","사는 사람의 생활이 너무 많이 드러나지 않게 조심해요."]},{"kind":"say","lines":["그리고 진짜 똑똑한 집은 화면을 누를 일이 적어요.","위험을 스스로 막고, 사람에게는 결과만 알려 줘요."]}],"pass2":[{"kind":"points","head":"말 풀이","items":["**정보 과부하(Clutter)**: 화면에 아이콘이 너무 많아 머리가 아픈 상태예요. 제어 피로감이 생겨요.","**컨텍스트 기반 UI(Context-based UI)**: 상황(컨텍스트)에 맞춰 필요할 때만 필요한 버튼이 나타나는 화면 설계예요.","**프라이버시(Privacy)**: 남에게 보이고 싶지 않은 나만의 생활이에요. 화면에 너무 많이 띄우면 침해로 이어져요."]},{"kind":"compare","head":"가스 밸브로 보는 세대 차이","cols":["","사람이 누르는 집","스스로 막는 집"],"rows":[["가스가 새면","거주자가 매번 **대시보드(Dashboard)**에서 직접 눌러 잠가요","센서가 위험을 감지해 스스로 차단해요"],["사람에게는","일일이 조작을 요구해요","결과만 사후에 알려요"],["수준","2세대 원격제어 수준","3세대 **지능형 홈(AI@Home)**에 더 가까움"]]},{"kind":"check","q":"**정보 과부하(Clutter)**를 줄이는 설계 기법으로 강의에 나온 것은?","choices":["모든 아이콘 단순 나열","컨텍스트 기반 UI(상황별 노출)","상태 데이터 보고 주기 단축","카메라 추가 설치"],"a":1,"why":"평소엔 주요 지표만, 야간이나 부재 같은 상황에서만 필요한 메뉴를 켜는 **컨텍스트 기반 UI(Context-based UI)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"'역설'이라는 말","items":["역설은 기대와 반대로 되는 일이에요.","보기 편하려고 만든 **대시보드(Dashboard)**가, 너무 많이 보여 주면 오히려 불편하고 사생활까지 위험해져요.","그래서 이 쪽 제목이 '가시화의 역설'이에요."]}],"pass4":[{"kind":"check","q":"강의 내용과 맞지 않는 것은?","choices":["기기가 늘 때 아이콘을 단순 나열하면 제어 피로감이 생긴다","야간이나 부재 등 특정 맥락에서만 필요한 제어 메뉴를 활성화한다","대시보드 의존도가 높을수록 AI@Home이 완성되었다는 뜻이다","개인 생활 정보를 너무 많이 띄우면 프라이버시 침해로 이어진다"],"a":2,"why":"반대예요. 의존도가 높을수록 **지능형 홈(AI@Home)**은 아직 완성되지 않았다는 뜻이에요."},{"kind":"english","head":"서술형 답안: AI@Home 관점의 대시보드 한계","en":"가스 밸브를 매번 대시보드에서 직접 잠가야 하면 2세대 원격제어 수준이고, 센서가 스스로 차단하고 결과만 사후에 알리면 3세대 AI@Home에 가깝다. 대시보드 의존도가 높을수록 AI@Home은 미완성이다.","ko":"예시(가스 밸브) → 비교(2세대와 3세대) → 결론(의존도) 순서예요.","tip":"'많이 누를수록 덜 똑똑한 집'으로 기억해요."},{"kind":"bg","src":"용어해설집 81번","lines":["UX 시나리오: 사용자 행동과 상황에 따른 공간의 반응을 시간 흐름과 조건에 따라 구조화한 설계 명세서예요.","상황마다 필요한 메뉴를 정하는 **컨텍스트 기반 UI(Context-based UI)**도 이런 상황별 설계에서 나와요."]}],"pass5":[],"walk":{"head":{"b":[0.0823,0.125,0.5765,0.0687],"c":[0.0535,0.109,0.6342,0.1007],"r":8.9067,"img":"img/I2/walk/p025_h.jpg"},"parts":[{"b":[0.089,0.197,0.55,0.114],"c":[0.0615,0.181,0.605,0.146],"r":5.8603,"img":"img/I2/walk/p025_30_01.jpg","say":"큰 제목: 기기가 늘어날수록 화면은 복잡해진다... 정보 과부하를 넘어서는 직관적 설계의 필요성."},{"b":[0.104,0.333,0.811,0.069],"c":[0.0635,0.2774,0.8921,0.1802],"r":7.0013,"img":"img/I2/walk/p025_30_02.jpg","say":"정보 과부하(Clutter)의 함정: 세대 내 기기가 수십 개로 늘어날 때 모든 아이콘을 단순 나열하면 거주자는 오히려 제어 피로감을 느껴요."},{"b":[0.104,0.412,0.811,0.069],"c":[0.0635,0.3564,0.8921,0.1802],"r":7.0013,"img":"img/I2/walk/p025_30_03.jpg","say":"컨텍스트 기반 UI(상황별 노출): 평상시에는 주요 환경 지표만 보여 주다가, 야간이나 부재 등 특정 맥락에서만 필요한 제어 메뉴를 활성화하는 설계 기법이 필요해요."},{"b":[0.104,0.491,0.811,0.07],"c":[0.0635,0.4359,0.8921,0.1802],"r":7.0013,"img":"img/I2/walk/p025_30_04.jpg","say":"가시화와 프라이버시의 교차점: 화면에 너무 많은 개인 생활 정보를 띄우는 것은 가시화의 편의를 넘어 거주자 프라이버시 침해 문제로 직결돼요."},{"b":[0.089,0.572,0.825,0.156],"c":[0.0477,0.556,0.9075,0.188],"r":6.8267,"img":"img/I2/walk/p025_30_05.jpg","say":"AI@Home 관점의 대시보드 한계: 가스 밸브를 매번 직접 눌러 잠가야 하면 2세대 원격제어 수준, 센서가 스스로 차단하고 결과만 알리면 3세대에 가까워요. 의존도가 높을수록 AI@Home은 미완성."}]}},{"p":26,"title":"2.3.4 [비식별 센싱] Privacy-by-Design과 개인정보보호 법령","terms":["Privacy","Linked Information","Privacy-by-Design","Personal Information Protection Act","De-identification","Pseudonymization","Subnet Isolation","mmWave Presence Sensor","Environmental Sensor","Encryption","Edge Computing","Power Monitoring","Time-series Data"],"pass1":[{"kind":"say","lines":["전기를 얼마나 썼는지 하나, '방에 사람 있음' 신호 하나는 별것 아니에요.","그런데 이런 조각이 매일 쌓이고 합쳐지면 몇 시에 자고 언제 집을 비우는지 다 드러나요.","그래서 집의 데이터는 **프라이버시(Privacy)**를 지키는 게 아주 중요해요."]},{"kind":"say","lines":["사고가 난 뒤에 막는 건 늦어요.","도면을 그리는 처음 단계부터 사생활 보호를 기본으로 넣어요.","이 생각을 **Privacy-by-Design(프라이버시 바이 디자인)**이라고 불러요."]}],"pass2":[{"kind":"points","head":"말 풀이","items":["**연계정보(Linked Information)**: 따로 보면 누군지 몰라도, 합치면 누군지 알게 되는 정보예요.","**Privacy-by-Design(프라이버시 바이 디자인)**: 처음 설계할 때부터 사생활 보호를 기본값으로 넣는 설계 생각이에요. 줄여서 PbD라고 해요.","**비식별 조치(De-identification)**: 누구의 데이터인지 알아볼 수 없게 가리는 처리예요.","**가명화(Pseudonymization)**: 진짜 이름 대신 별명을 붙여 두는 처리예요.","**세대망 분리(Subnet Isolation)**: 옆집과 우리 집 네트워크 길을 따로 나누는 것이에요."]},{"kind":"points","head":"도면 설계 때 쓰는 두 가지 방어","items":["침실, 욕실 같은 사는 공간에는 영상, 음성 대신 **mmWave 재실센서(mmWave Presence Sensor)**나 **환경센서(Environmental Sensor)**를 기본으로 둬요.","민감한 생활 패턴 데이터는 집 밖 클라우드로 새지 않게 집 안 허브에서 **암호화(Encryption)**해요. 이게 p.9에서 본 **엣지 컴퓨팅(Edge Computing)**의 프라이버시 보호예요."]},{"kind":"check","q":"**Privacy-by-Design(프라이버시 바이 디자인)**을 가장 잘 설명한 것은?","choices":["사고가 난 뒤 보안 패치를 붙이는 방식","공간 기획과 도면 설계 초기부터 프라이버시 보호를 기본값으로 넣는 설계 철학","모든 방에 카메라를 기본으로 두는 원칙","모든 원본 영상을 클라우드로 보내 분석하는 방식"],"a":1,"why":"사후가 아니라 처음부터, 기본값(Default)으로 넣는 게 핵심이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"개인정보보호 4대 핵심 기준","cols":["근거","내용"],"rows":[["보호법 제3조","목적에 맞는 최소한의 정보만 수집"],["보호법 제2조 제1호","결합해 식별 가능한 **연계정보(Linked Information)** 규제"],["보호법 제28조의2","AI 분석 시 **비식별 조치(De-identification)**, **가명화(Pseudonymization)** 조치 의무"],["홈네트워크 고시","세대 간 네트워크 침해 방지를 위한 **세대망 분리(Subnet Isolation)** 의무"]]},{"kind":"points","head":"첫 상자의 예시 두 개","items":["'단일 전력량'은 **전력 모니터링(Power Monitoring)**으로 얻는 값이에요.","'단순 재실 신호'는 방에 사람이 있는지 알려 주는 값이에요.","이 둘이 **시계열 데이터(Time-series Data)**로 쌓이고 합쳐지면 **연계정보(Linked Information)**가 돼요."]},{"kind":"bg","src":"지능형 홈네트워크 설비 설치 및 기술기준 제14조의2","lines":["단지서버와 세대별 홈게이트웨이 사이의 망은 데이터 노출, 탈취를 막기 위해 물리적으로 분리해야 해요.","또는 가상사설통신망, 가상근거리통신망, 암호화 기술 같은 논리적 방법으로 분리해 구성해요. 슬라이드의 '세대망 분리 의무'가 이 조항이에요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 3번","q":"「개인정보 보호법」상 개념에 관한 설명으로 옳지 않은 것은?","qko":"개인정보 보호법의 용어 설명 넷 중 틀린 것을 고르는 문제예요.","solve":["'정보주체는 처리되는 정보로 알아볼 수 있는, 그 정보의 주체가 되는 사람'은 맞는 말이에요.","'수집, 생성, 연계, 연동은 모두 처리에 해당'은 맞는 말이에요. 슬라이드의 연계정보와 같은 '연계'예요.","'개인정보파일은 쉽게 검색하도록 규칙에 따라 배열한 개인정보 집합물'도 맞는 말이에요.","개인정보처리자는 공공기관, 법인, 단체, 개인을 모두 포함해요. '살아 있는 개인만'이라는 보기가 틀렸어요."],"answer":"개인정보처리자는 살아 있는 개인이어야 하므로 공공기관, 법인, 단체는 해당되지 않는다"},{"kind":"check","q":"강의의 개인정보보호 4대 핵심 기준 연결로 옳지 않은 것은?","choices":["보호법 제3조: 목적에 맞는 최소한의 정보만 수집","보호법 제2조 제1호: 결합해 식별 가능한 연계정보 규제","보호법 제28조의2: AI 분석 시 비식별, 가명화 조치 의무","홈네트워크 고시: 영상 카메라 전 세대 의무 설치"],"a":3,"why":"홈네트워크 고시는 **세대망 분리(Subnet Isolation)** 의무예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["조항 번호를 섞어 내기 쉬워요. 최소 수집은 제3조, 연계정보는 제2조 제1호, 비식별과 가명화는 제28조의2예요.","세대망 분리는 개인정보 보호법이 아니라 홈네트워크 고시(기술기준)에서 나와요."]}],"pass5":[{"kind":"points","head":"실기 연결: IoT 공통 보안 7대 원칙 ① (실기 가이드북 2권 1-2 지능형홈 네트워크 설계 및 구성)","items":["① 정보보호와 프라이버시 강화를 고려한 IoT 제품, 서비스 설계: 'Security by Design' 및 'Privacy by Design' 기본원칙 준수.","③ 안전한 초기 보안 설정 방안 제공: 'Secure by Default' 기본원칙 준수.","⑥ 안전한 운영, 관리를 위한 정보보호 및 프라이버시 관리체계 마련: 사용자 정보 취득, 사용, 폐기의 전주기 보호.","7대 원칙은 IoT 장치의 전주기에서 개발자와 사용자가 함께 고려할 공통 보안 요구사항이에요."]},{"kind":"check","q":"실기 가이드북의 IoT 공통 보안 7대 원칙 ①에서 설계 단계에 지키라고 한 기본원칙은?","choices":["Secure by Default","Security by Design 및 Privacy by Design","세대망 분리","보안 패치 지속"],"a":1,"why":"설계 단계는 by Design 두 가지, 초기 설정 단계는 Secure by Default예요. 슬라이드의 **Privacy-by-Design(프라이버시 바이 디자인)**과 같은 원칙이에요."}],"walk":{"head":{"b":[0.0823,0.125,0.6592,0.0687],"c":[0.0493,0.109,0.7252,0.1007],"r":10.1847,"img":"img/I2/walk/p026_h.jpg"},"parts":[{"b":[0.089,0.196,0.825,0.168],"c":[0.0477,0.18,0.9075,0.2],"r":6.4171,"img":"img/I2/walk/p026_30_01.jpg","say":"왜 개인정보가 치명적인가: 단일 전력량, 단순 재실 신호 자체는 침해가 아니지만, 시계열로 축적, 결합(연계정보)되면 기상 시각, 외출 시간, 생활 루틴이 드러나요. 그래서 설계 초기부터 PbD가 필수."},{"b":[0.089,0.373,0.407,0.258],"c":[0.0686,0.357,0.4477,0.29],"r":2.1833,"img":"img/I2/walk/p026_30_02.jpg","say":"실무 방어 대책: 비식별 센서 기본값(침실, 욕실엔 영상, 음성 대신 mmWave 레이더, 환경센서), 세대 내 Edge 암호화(라이프 패턴 데이터가 클라우드로 새지 않게 로컬 허브에서 암호화)."},{"b":[0.507,0.373,0.407,0.258],"c":[0.4867,0.357,0.4477,0.29],"r":2.1833,"img":"img/I2/walk/p026_30_03.jpg","say":"개인정보보호 4대 핵심 기준: 보호법 제3조(최소 수집), 제2조 제1호(연계정보 규제), 제28조의2(AI 분석 시 비식별, 가명화 의무), 홈네트워크 고시(세대망 분리 의무). 표로 다음 장면에서 다시 봐요."},{"b":[0.089,0.639,0.825,0.133],"c":[0.0477,0.6138,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p026_30_04.jpg","say":"용어 정의 PbD(Privacy-by-Design): 사후에 보안 패치를 붙이는 방식이 아니라, 공간 기획과 도면 설계 초기 단계부터 프라이버시 보호를 시스템의 기본값(Default)으로 내재화하는 설계 철학."}]}},{"p":27,"title":"2.3.5 Privacy-by-Design 센서 기술 스펙트럼","terms":["Identifiable Data","AI RGB Camera","Non-identifying Sensing","mmWave Presence Sensor","PIR Sensor","Environmental Sensor","Power Monitoring","Personal Information Protection Act","Penalty Surcharge","De-identification","Pseudonymization","Privacy-by-Design","AI@Home"],"pass1":[{"kind":"compare","head":"얼굴을 찍는 센서, 찍지 않는 센서","cols":["센서","무엇을 알까","사생활 걱정"],"rows":[["**AI RGB 카메라(AI RGB Camera)**","색깔 영상(RGB)으로 얼굴과 행동을 그대로 찍어요","가장 커요"],["**mmWave 재실센서(mmWave Presence Sensor)**","아주 짧은 전파(mmWave)로, 영상 없이 숨쉬기, 잠, 넘어짐을 알아채요","거의 없어요"],["**PIR 센서(PIR Sensor)**, **환경센서(Environmental Sensor)**, **전력 모니터링(Power Monitoring)**","몸의 열 움직임(PIR)으로 사람이 있는지, 온도와 습도, 전기 사용량만 재요","없어요"]]},{"kind":"figure","head":"집 도면에 센서 놓기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box\" x=\"10\" y=\"20\" width=\"460\" height=\"240\" rx=\"3\"/><rect class=\"n b1\" x=\"20\" y=\"30\" width=\"150\" height=\"105\" rx=\"3\"/><text class=\"tl b1\" x=\"95\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">침실<\/text><text class=\"tl b1\" x=\"95\" y=\"96\" font-size=\"14\" text-anchor=\"middle\">레이더, 환경센서<\/text><rect class=\"n b1\" x=\"20\" y=\"145\" width=\"150\" height=\"105\" rx=\"3\"/><text class=\"tl b1\" x=\"95\" y=\"185\" font-size=\"16\" text-anchor=\"middle\">욕실<\/text><text class=\"tl b1\" x=\"95\" y=\"211\" font-size=\"14\" text-anchor=\"middle\">얼굴 안 찍는 센서<\/text><rect class=\"n3 b2\" x=\"180\" y=\"30\" width=\"180\" height=\"220\" rx=\"3\"/><text class=\"tl b2\" x=\"270\" y=\"125\" font-size=\"16\" text-anchor=\"middle\">거실<\/text><text class=\"tl b2\" x=\"270\" y=\"151\" font-size=\"14\" text-anchor=\"middle\">동작센서, 전기 사용량<\/text><rect class=\"n4 b3\" x=\"370\" y=\"145\" width=\"90\" height=\"105\" rx=\"3\"/><text class=\"tl b3\" x=\"415\" y=\"185\" font-size=\"16\" text-anchor=\"middle\">현관<\/text><text class=\"tl b3\" x=\"415\" y=\"211\" font-size=\"14\" text-anchor=\"middle\">카메라는<\/text><text class=\"tl b3\" x=\"415\" y=\"231\" font-size=\"14\" text-anchor=\"middle\">여기만<\/text><rect class=\"n2 b3\" x=\"370\" y=\"30\" width=\"90\" height=\"105\" rx=\"3\"/><text class=\"tl b3\" x=\"415\" y=\"75\" font-size=\"16\" text-anchor=\"middle\">허브<\/text><text class=\"tl b3\" x=\"415\" y=\"101\" font-size=\"14\" text-anchor=\"middle\">집 안 잠금<\/text><\/svg>","caption":"침실과 욕실은 얼굴을 찍지 않는 센서, 카메라는 현관 같은 꼭 필요한 곳에만 둬요.","builds":3},{"kind":"say","lines":["사는 공간에는 얼굴을 찍지 않고 '사람이 있다'만 알아내는 센서를 기본으로 둬요.","이런 감지 방식을 **비식별 센싱(Non-identifying Sensing)**이라고 해요."]}],"pass2":[{"kind":"points","head":"센서 이름 풀이","items":["**식별 데이터(Identifiable Data)**: 얼굴처럼 누군지 바로 알아보는 데이터예요. **AI RGB 카메라(AI RGB Camera)**가 만드는 영상이 여기에 들어가요.","**mmWave 재실센서(mmWave Presence Sensor)**: 아주 짧은 전파로 가만히 있는 사람의 숨쉬기까지 알아채요. 슬라이드 이름은 'mmWave 레이더 센서'예요.","**PIR 센서(PIR Sensor)**: 몸에서 나오는 열(적외선)이 움직일 때 알아채는 동작 센서예요.","**환경센서(Environmental Sensor)**: 온도, 습도, 공기 같은 주변 환경을 재는 센서예요.","**전력 모니터링(Power Monitoring)**: 전기를 얼마나 쓰는지 지켜보는 일이에요."]},{"kind":"points","head":"처벌이 있다는 것","items":["**개인정보 보호법(Personal Information Protection Act)**을 어기면 징역이나 벌금을 받을 수 있어요.","특히 **비식별 조치(De-identification)**나 **가명화(Pseudonymization)** 없이 개인정보를 쓰면 안 돼요.","크게 유출되면 회사가 매출에 비례한 **과징금(Penalty Surcharge)**까지 내야 해요.","**Privacy-by-Design(프라이버시 바이 디자인)**은 이런 위험을 사업 설계 단계에서 미리 막는 장치예요."]},{"kind":"check","q":"**지능형 홈(AI@Home)**이 침실, 욕실 같은 사는 공간에 권장하는 센서가 아닌 것은?","choices":["mmWave 레이더 센서","PIR 동작센서","환경센서","AI RGB 카메라"],"a":3,"why":"**AI RGB 카메라(AI RGB Camera)**는 얼굴과 행동을 찍는 **식별 데이터(Identifiable Data)**라 사생활 침해감이 가장 커요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"처벌 숫자","cols":["숫자","뜻"],"rows":[["5년 이하","징역 상한"],["5천만원 이하","벌금 상한"],["제71조","처벌 조항"],["최대 3%","대규모 유출, 관리 소홀 시 전체 매출액 대비 **과징금(Penalty Surcharge)** 상한"]]},{"kind":"points","head":"센서 칸에 적힌 짧은 설명 그대로","items":["mmWave 레이더 센서: 미세 호흡, 수면, 낙상을 영상 없이 감지, 비식별.","PIR 동작센서, 환경센서, 전력 모니터링: 단순 재실, 환경 측정만 수행, 침해감 없음.","AI RGB 카메라: 얼굴, 행동을 그대로 촬영, 침해감이 가장 큼."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 31번","q":"거실에서 센서를 착용하거나 접촉하지 않은 상태로 사람의 움직임을 감지해 조명 제어와 재실 판단에 쓰려 한다. 비접촉 인체 움직임 감지에 가장 적합하지 않은 센서는?","qko":"몸에 붙이지 않고 움직임을 알아채는 센서가 아닌 것을 고르는 문제예요.","solve":["PIR 센서는 적외선 변화로 움직임을 알아채요. 비접촉이에요.","UWB 센서는 전파로 위치와 움직임을 알아채요. 비접촉이에요.","적외선 이미지 센서는 열 영상으로 알아채요. 비접촉이에요.","피부 접촉식 생체 신호 센서는 몸에 붙여야 작동해서 조건에 맞지 않아요."],"answer":"피부 접촉식 생체 신호 센서"},{"kind":"check","q":"보호법 제28조의2 등을 위반해 비식별, 가명화 없이 개인정보를 이용, 제공할 때의 처벌로 강의에 나온 것은?","choices":["3년 이하 징역 또는 3천만원 이하 벌금","5년 이하 징역 또는 5천만원 이하 벌금(제71조)","10년 이하 징역","처벌 조항 없음"],"a":1,"why":"5년, 5천만원, 제71조예요. 대규모 유출이나 관리 소홀은 매출액의 최대 3% **과징금(Penalty Surcharge)**까지 더해져요."},{"kind":"english","head":"답안 문장으로 외우기 (p.28 Q6)","en":"PbD 원칙상 침실에는 비식별 센서가 기본이지만, 현관과 공용부에는 방범, 출입통제처럼 식별이 꼭 필요한 목적이 있고 공용 공간이라 사생활 침해 우려가 상대적으로 적기 때문에 영상 카메라를 예외적으로 허용한다.","ko":"이유 두 가지(식별 목적, 침해 우려 적음)를 다 써요.","tip":"'필요하고, 덜 사적이다'로 기억해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["용어해설집 58번: **mmWave 재실센서(mmWave Presence Sensor)**는 정지 상태의 미세 움직임까지 감지해요. 59번: **PIR 센서(PIR Sensor)**는 움직임이 있을 때만 반응해요.","과징금 3%는 '순이익'이 아니라 '전체 매출액'의 최대 3%예요."]}],"pass5":[{"kind":"points","head":"실기 연결: PIR 센서의 약점 (실기 가이드북 2권 1-1 #1, #2 스마트 주방 문제)","items":["PIR 센서는 사람 몸(36.5℃)에서 나오는 원적외선을 감지하는 수동형 적외선 모션 센서예요.","주변 온도에 따라 감지 속도가 달라지고, 5℃ 이상 급격한 주변 온도 변화에 동작해요.","움직임이 없거나 미세하면 감지하지 못해요. 센서 수신부 수직 움직임에 대한 정확도도 낮아요.","렌즈 패턴에 따라 다르지만 PIR 센서 하나는 120도의 감지 범위를 가져요."]},{"kind":"warn","head":"실기에서 흔한 실수","items":["감지 각도를 못 맞추면 오작동해요.","PIR 센서는 사람이 움직이지 않으면 없는 것으로 보고 조명을 꺼 버려요. 가만히 앉아 있는 공간에는 정지 상태까지 감지하는 **mmWave 재실센서(mmWave Presence Sensor)**를 떠올려요."]}],"walk":{"head":{"b":[0.0823,0.1256,0.4996,0.0678],"c":[0.0573,0.1096,0.5496,0.0998],"r":7.7882,"img":"img/I2/walk/p027_h.jpg"},"parts":[{"b":[0.089,0.196,0.407,0.221],"c":[0.0686,0.18,0.4477,0.253],"r":2.5026,"img":"img/I2/walk/p027_30_01.jpg","say":"사생활 침해감 높음(식별 데이터): AI RGB 카메라. 얼굴, 행동을 그대로 촬영하는 영상 데이터라 사생활 침해감이 가장 커요."},{"b":[0.507,0.196,0.407,0.221],"c":[0.4867,0.18,0.4477,0.253],"r":2.5026,"img":"img/I2/walk/p027_30_02.jpg","say":"AI@Home 권장 비식별 센싱 영역: mmWave 레이더 센서(미세 호흡, 수면, 낙상을 영상 없이 감지, 비식별), PIR 동작센서, 환경센서, 전력 모니터링(단순 재실, 환경 측정만 수행, 침해감 없음)."},{"b":[0.089,0.428,0.825,0.125],"c":[0.0477,0.3988,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p027_30_03.jpg","say":"설계 기준: 거주 공간(침실, 욕실 등)엔 오른쪽 비식별 센싱 영역을 기본값으로 채택하고, 영상 기반 센서는 현관, 공용부 등 꼭 필요한 곳에만 예외적으로 배치해요."},{"b":[0.089,0.564,0.825,0.164],"c":[0.0477,0.548,0.9075,0.196],"r":6.548,"img":"img/I2/walk/p027_30_04.jpg","say":"처벌 기준과 비즈니스 리스크: 제28조의2 등을 어기고 비식별, 가명화 없이 개인정보를 이용, 제공하면 5년 이하 징역 또는 5천만원 이하 벌금(제71조). 대규모 유출, 관리 소홀은 매출액 최대 3% 과징금."}]}},{"p":28,"title":"2.3강 CHECKPOINT","terms":["Dashboard","Real-time Monitoring","Instant Control","Event Data","Linked Information","Personal Information Protection Act","Privacy-by-Design","mmWave Presence Sensor","AI RGB Camera","AI@Home"],"pass1":[{"kind":"say","lines":["마지막 확인 문제예요.","화면의 두 가지 일, 사건 기록이 있는 곳, 사생활을 지키는 원칙과 센서를 물어요.","센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요."]}],"pass2":[{"kind":"points","head":"여섯 문제를 쉬운 말로","items":["Q1 대시보드의 두 가지 일은 보기와? → 누르기, 즉 **즉각적 제어(Instant Control)**.","Q2 '도어락 해제' 같은 사건 기록은 어디서 볼까? → 각 기기의 기록(History) 탭.","Q3 쌓이고 합쳐져서 누군지 알게 되는 정보는? → **연계정보(Linked Information)**.","Q4 침실, 욕실에 영상 대신 비식별 센서를 기본으로 두는 원칙은? → **Privacy-by-Design(프라이버시 바이 디자인)**.","Q5 카메라와 레이더 중 사는 공간에 권장하는 것은? → mmWave 레이더 센서.","Q6 현관에는 왜 카메라를 예외로 둘까? → 식별이 꼭 필요하고, 공용 공간이라 침해 우려가 적어서."]},{"kind":"check","q":"대시보드의 2대 핵심 기능은 실시간 모니터링과 무엇일까?","choices":["즉각적 제어","데이터 레이크","가명화","피드백 제어"],"a":0,"why":"**실시간 모니터링(Real-time Monitoring)**과 **즉각적 제어(Instant Control)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"Q2와 Q3가 앞 쪽과 이어지는 곳","items":["Q2는 p.24 파란 상자의 이벤트 로그 위젯이에요. **이벤트 데이터(Event Data)**는 기록 탭에 쌓여요.","Q3의 **연계정보(Linked Information)**는 p.26 보호법 제2조 제1호가 규제하는 대상이에요."]}],"pass4":[{"kind":"check","q":"센서 데이터가 시계열로 축적, 결합되어 개인을 특정할 수 있게 된 정보를 강의는 무엇이라 불렀을까?","choices":["식별 데이터","연계정보","가명정보","상태 데이터"],"a":1,"why":"**연계정보(Linked Information)**예요. **개인정보 보호법(Personal Information Protection Act)** 제2조 제1호가 규제한다고 슬라이드에 나왔어요."},{"kind":"check","q":"AI@Home이 거주 공간에 권장하는 비식별 센싱 기술은?","choices":["AI RGB 카메라","mmWave 레이더 센서","현관 CCTV","얼굴 인식 도어락"],"a":1,"why":"**mmWave 재실센서(mmWave Presence Sensor)**는 영상 없이 호흡, 수면, 낙상을 감지해요."}],"pass5":[],"walk":{"head":{"b":[0.0823,0.1256,0.26,0.0632],"c":[0.0693,0.1096,0.286,0.0952],"r":4.2486,"img":"img/I2/walk/p028_h.jpg"},"parts":[{"b":[0.089,0.2,0.825,0.113],"c":[0.0477,0.1648,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p028_30_01.jpg","say":"Q1 스마트홈 대시보드의 2대 핵심 기능은 실시간 모니터링과 무엇인가? → 즉각적 제어."},{"b":[0.089,0.316,0.825,0.114],"c":[0.0477,0.2813,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p028_30_02.jpg","say":"Q2 '도어락 해제'처럼 대시보드 홈 화면엔 잘 안 보이는 단발성 사건 기록은 보통 어디서 확인하는가? → 각 기기의 기록(History) 탭."},{"b":[0.089,0.433,0.825,0.114],"c":[0.0477,0.3983,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p028_30_03.jpg","say":"Q3 센서 데이터가 시계열로 축적, 결합되어 개인을 특정할 수 있게 되는 정보를 개인정보보호법은 무엇이라 부르는가? → 연계정보."},{"b":[0.089,0.551,0.825,0.113],"c":[0.0477,0.5158,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p028_30_04.jpg","say":"Q4 침실, 욕실처럼 민감한 공간엔 영상 대신 mmWave, 환경센서를 기본값으로 배치하는 설계 원칙의 이름은? → Privacy-by-Design(PbD)."},{"b":[0.089,0.667,0.825,0.114],"c":[0.0477,0.6323,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p028_30_05.jpg","say":"Q5 AI RGB 카메라와 mmWave 레이더 중 AI@Home이 거주 공간에 권장하는 비식별 센싱 기술은? → mmWave 레이더 센서."},{"b":[0.089,0.784,0.825,0.113],"c":[0.0477,0.7488,0.9075,0.1833],"r":7.0017,"img":"img/I2/walk/p028_30_06.jpg","say":"Q6 PbD 원칙상 침실엔 비식별 센서가 기본인데, 현관, 공용부엔 영상 카메라를 예외적으로 허용하는 이유는? → 방범, 출입통제처럼 식별이 꼭 필요한 목적이 있고, 공용 공간이라 사생활 침해 우려가 상대적으로 적기 때문 등."}]}}]};
